window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26616951"]={"book":{"id":26616951,"title":"WOOP思维心理学","author":"[美]加布里埃尔•厄廷根","translator":"吴国锦","publisher":"中国友谊出版公司","pubdate":"2015-8","isbn":"9787505735316","tags":["心理学","思维方式","积极心理学","思维","个人成长","自我管理","方法论","心理"],"memCount":11},"np":1,"pb":[23],"idx":[{"i":19323,"t":"愿望实现四步法","l":"TF2-2","c":"Cephas","g":1,"p":1},{"i":15693,"t":"如何利培养woop的思维方式，让你积极乐观、能量满满，目标明确，勇往直前","l":"TF3-3","c":"clund","g":1,"p":1},{"i":15513,"t":"WOOP思维工具，把梦想变成现实","l":"TF2-2","c":"耿耿","g":1,"p":1},{"i":11569,"t":"如何利用WOOP思维实现梦想","l":"TF1-1","c":"煦涵","g":1,"p":1},{"i":11315,"t":"用WOOP让美梦成真","l":"TF1-2","c":"小妖灵灵","g":1,"p":1},{"i":10666,"t":"WOOP思维方法","l":"TF3-3","c":"付盈盈","g":1,"p":1},{"i":10349,"t":" 【学习主题】   四步实现心中所愿","l":"TF2-1","c":"猫小杜","g":1,"p":1},{"i":10302,"t":"WOOP四步法则","l":"TF2-2","c":"yangzhuanfu","g":1,"p":1},{"i":9585,"t":"WOOP思维方法","l":"TF3-2","c":"付盈盈","g":1,"p":1},{"i":8027,"t":"WOOP思维的四个步骤","l":"TF2-3","c":"佐江","g":1,"p":1},{"i":7891,"t":"压力过大时如何缓解？","l":"TF1-2","c":"刘小七","g":1,"p":1},{"i":7686,"t":"能够采用心理对照的方式解决做事情过于理想化的情况","l":"TF3-2","c":"赵自力","g":1,"p":1},{"i":7328,"t":"目标实现！","l":"TF3-2","c":"赵自力","g":1,"p":1},{"i":7159,"t":"自我管理＆沟通表达","l":"TF3-1","c":"赵自力","g":1,"p":1},{"i":6406,"t":"如何用woop实现那些有难度，但是可以达成的事情。","l":"TF2-1","c":"清心悦行","g":1,"p":1},{"i":6016,"t":"如何分析自己失败的原因","l":"TF1-2","c":"方凯","g":1,"p":1},{"i":5969,"t":"梦想难以实现吗？woop一下","l":"TF1-1","c":"miranda","g":1,"p":1},{"i":4366,"t":"WOOP思维，开启你成功的秘密","l":"TF3-1","c":"馒头","g":0,"p":1},{"i":4365,"t":"WOOP思维，开启你成功的秘密！","l":"TF3-1","c":"馒头","g":0,"p":1},{"i":3029,"t":"WOOP思维，开启你成功的秘密！","l":"TF3-1","c":"馒头","g":0,"p":1},{"i":2079,"t":"WOOP四步法则","l":"TF1-2","c":"意为安","g":1,"p":1},{"i":1514,"t":"如何用WOOP思维工具实现一个小目标","l":"TF1-2","c":"夏彼得","g":1,"p":1},{"i":879,"t":"四个步骤，让你无压前行","l":"TF1-1","c":"文武","g":1,"p":1}],"ms":[{"id":19323,"topic":"愿望实现四步法","learn_goal":"","remark":"通过本次学习后，让学习者们能够掌握WOOP思维提升个人行动力，并运用该方法现场实践加工一个愿望转化为具体行动步骤，解决自身实际的问题。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"Cephas","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是Cephas。我的三个标签：爱书人，爱乐人，拆书家。\u003c/p>\u003cp>\u003cstrong>【介绍图书 FAB法】\u003c/strong> \u003c/p>\u003cp>【F（特征，Feature）】\u003c/p>\u003cp>今天给大家拆解的片段来自《WOOP思维心理学》 ，作者是世界著名心理学家、心理学教授、人类内心动力研究领域专家-加布里埃尔·厄廷根教授；本书是一本内容上佳的自助类书籍，内容聚焦“愿望与实现愿望”，提出科学的“WOOP思维理论”，指导将愿望转化为实践。\u003c/p>\u003cp>【A（优势，Advantage）】\u003c/p>\u003cp>本书理论支撑是基于作者20余年科研成果，和市面上的积极思维/心灵鸡汤类的书籍相比，颠覆了“积极思维有益”的传统观念，提出可落地的思维训练方法，区别于空洞的“心灵鸡汤”；本书重新审视积极思维，形成新动力学说，来解决实际问题，可直接用于改善和应对生活、工作中遇到的问题。\u003c/p>\u003cp>【B（利益，Benefit）】\u003c/p>\u003cp>• B1：帮你揭开梦想实现的心理学规律，避免陷入“积极思维”误区，找到推动愿望落地的科学路径；\u003c/p>\u003cp>• B2：通过实践“WOOP思维理论”，能将自己设定的愿望转化为具体行动。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>通过本次学习，让学习者们在生活工作中有想要达成愿望或目标时，通过运用愿望实现四步法-WOOP思维将愿望转化为具体行动步骤并落地实践，解决自身遇到的障碍，提升个人行动力。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>今天现场人少，我们分成1个小组，方便待会讨论环节交流分享。\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>下面请大家阅读这个片段，时间大约1分钟，大家读完了可以抬头示意我。\u003c/p>","ratings_count":1,"texts":[{"id":23681,"quote":"\u003cp>\u003cstrong> 【R阅读原文拆页】\u003c/strong>\u003c/p>\u003cp>《WOOP思维心理学》 \u003c/p>\u003cp>【愿望实现四步法】\u003c/p>\u003cp>W：愿望或心事。放松，深呼吸，想一个私人或工作方面的愿望或牵挂，虽然有些棘手但你觉得能够达成。它可以是你打算在当天、本周、本月、本年之内要达成的，只要是你想要WOOP的愿望都可以。如果你在同一时间段内有好几个愿望，那就选一个对你而言最重要的。然后把这件事放在思考的中心。\u003c/p>\u003cp>O：结果。你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。任思绪驰骋，不要有顾虑。不要着急，慢慢来，要是喜欢的话，可以闭上眼睛。\u003c/p>\u003cp>做好准备之后，睁开眼睛，进入下一个步骤：\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？是不是某种习惯或先入为主的想法？\u003c/p>\u003cp>P：计划。要克服或规避这个障碍的话，你能怎么做？想一个——最有效的那个——想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制订一个“如果……那么……”计划：“如果障碍X出现了（何时何地），那么我就采取行动Y。”\u003c/p>\u003cp>然后将这个计划重复一遍给自己听。\u003c/p>","explains":"\u003cp>\u003cstrong>【I重述知识点】\u003c/strong>\u003c/p>\u003cp> ……好的，我看大部分伙伴都读完了，没读完也没关系，可以跟随我的拆解来。下面我就来简单解读一下这个片段。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>这段讲的是WOOP思维方法，简单说就是我们想实现什么愿望，实现之后的样子（结果）是什么，回到现实中要成为理想样子遇到的阻力是什么，对此，我当下要做的行动是什么。\u003c/p>\u003cp>\u003cstrong>【行动步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【举例子说明】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>W (愿望/目标)\u003c/strong>：用 \u003cu>3个月   \u003c/u>时间，通过完成 \u003cu>拆书过级\u003c/u> ，使自己实现（成为） \u003cu>三级拆书家\u003c/u> 的目标。\u003c/p>\u003cp>\u003cstrong>O (结果/成果)\u003c/strong>：如果愿望实现，可以帮助我（使我获得）： \u003cu>在拆书现场，完成TF3-3成为三级拆书家的我，感到无比自豪和自我突破的满足感，同时获得大家的认可。 \u003c/u> \u003c/p>\u003cp>\u003cstrong>O (障碍/问题)\u003c/strong>：\u003c/p>\u003cp>实现目标的过程中可能会遇到这些挑战：\u003c/p>\u003cp>困难/能力挑战（√）\u003c/p>\u003cp>干扰/环境挑战（ ）\u003c/p>\u003cp>自制力提升/人性挑战（ ）\u003c/p>\u003cp>1、 \u003cu>拆书稿技能点理解不足，因“不知如何理解描述技能点”而畏难，导致拆书稿进度推迟。\u003c/u>（困难/能力挑战）\u003c/p>\u003cp>2、 \u003cu>加班、杂事多，导致拆书稿完成滞后。\u003c/u>（干扰/环境挑战）  \u003c/p>\u003cp>3、\u003cu>晚睡导致第二天精神不振。\u003c/u> （自制力提升/人性挑战）\u003c/p>\u003cp>\u003cstrong>P (计划/方案)\u003c/strong>：\u003c/p>\u003cp>实现目标我需要做什么？\u003c/p>\u003cp>如果\u003cu> 写拆书稿技能点理解不透停滞不前时\u003c/u>，那么我就\u003cu>看看原书籍或者百度搜索关键词，找找灵感继续写。\u003c/u> \u003c/p>\u003cp>\u003cstrong>【常见异议&amp;预防性讲解】\u003c/strong>\u003c/p>\u003cp>障碍预判不准：有学习者认为，如果障碍预判不准，那这个计划不是做了无用功，浪费了时间么？\u003c/p>\u003cp>你的担心没有错，不过这个方法的核心并不是让你一下子就找对障碍，而是存在这样的思维，在1次又1次的实践中，提升自己的判断力和敏锐度。\u003c/p>\u003cp>\u003cstrong>【适用场景】\u003c/strong>\u003c/p>\u003cp>适用于生活和工作中的各种个人目标，如养成习惯（运动、学习）、改善健康（减肥）、克服拖延、准备重要事件（演讲、考试）、改善人际关系、情绪管理等。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化应用\u003c/strong> \u003cstrong>分步催化1（显像提问）\u003c/strong>\u003c/p>\u003cp>各位伙伴，在我们生活和工作的中，常常会遇到一些渴望突破却又迟迟未能实现的改变。现在，请大家专注思考，想象一个具体的、未来很可能会发生的场景：\u003c/p>\u003cp>比如，\u003c/p>\u003cp>下周有一个重要的工作汇报或者拆书练级，你希望自己能够摆脱最后一刻才准备的拖延习惯，更加从容；\u003c/p>\u003cp>或者，天气转凉，你计划开始晨跑锻炼，但内心深知那股“再睡一会儿”的念头可能会冒出来；\u003c/p>\u003cp>不要只想一个抽象的愿望（比如“我想变美”），而是真切地想象出那个场景——什么时间、想要达成什么愿望或者目标。\u003c/p>\u003cp>请将对应的愿望写在便签上，然后在小组内分享。2分钟后请几位伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者A分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>W (愿望/目标)\u003c/strong>：\u003c/p>\u003cp>用 \u003cu>2个月   \u003c/u>时间，通过恢复 \u003cu>早起锻炼计划\u003c/u> ，实现 \u003cu>减重10斤\u003c/u> 的目标。\u003c/p>\u003cp>【过渡】谢谢学习者A分享的愿望。那么这样的愿望如何落地呢？\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong> \u003cstrong>分步催化2\u003c/strong>\u003c/p>\u003cp>请大家想一下刚才想要达成的愿望目标，运用今天所学的“愿望实现四步法”，在便签上写出“结果、障碍、计划”，让愿望目标落地。\u003c/p>\u003cp>然后给大家5分钟的时间先在小组讨论分享，5分钟后我们找小伙伴来给大家分享。\u003c/p>\u003cp>\u003cstrong>【学习者A分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>O (结果/成果)\u003c/strong>：\u003c/p>\u003cp>如果愿望实现，可以帮助我（使我获得）： \u003cu>身体更健康，身材更好。 \u003c/u> \u003c/p>\u003cp>\u003cstrong>O (障碍/问题)\u003c/strong>：\u003c/p>\u003cp>实现目标的过程中可能会遇到这些挑战：\u003c/p>\u003cp>困难/能力挑战（ ）\u003c/p>\u003cp>干扰/环境挑战（ ）\u003c/p>\u003cp>自制力提升/人性挑战（√ ）\u003c/p>\u003cp>\u003cu>喜欢吃甜食 。\u003c/u> （自制力提升/人性挑战）\u003c/p>\u003cp>\u003cstrong>P (计划/方案)\u003c/strong>：\u003c/p>\u003cp>实现目标我需要做什么？\u003c/p>\u003cp>如果 \u003cu>想吃甜食 \u003c/u>，那么我就\u003cu>快走1公里/运动15分钟。\u003c/u> \u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>谢谢小伙伴们的分享，今天我们学习了“愿望实现四步法”，通过“愿望、结果、障碍、计划”完成自己的愿望到落地的实践过程，希望今天的方法对大家有帮助，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1758555109000,"updated_at":1758585025000,"ria":true},{"id":15693,"topic":"如何利培养woop的思维方式，让你积极乐观、能量满满，目标明确，勇往直前","learn_goal":"","remark":"宣传语:到底是什么阻碍了你实现梦想，在你的内心深处，是什么限制了你，让你举步维艰，犹豫不前？\n\n拆书主题:如何利培养woop的思维方式，让你积极乐观、能量满满，目标明确，勇往直前","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"clund","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp> \u003cstrong>自我介绍及分组\u003c/strong>\u003c/p>\u003cp>大家好，感谢大家来参加我的拆书练级活动。我是陈慧云，现从事知识服务咨询方面的工作，如果用三个标签，我可以这样来介绍自己，1、职业上：自由的知识服务工作者。2、生活哲学方面：自律的斯多葛主义者。价值观取向：自省的保守主义者。今天我参加的是TF3-3级别的拆书学习，为了更好的促进大家的学习和互动讨论，我们要分组讨论，分成2个学习小组……\u003c/p>\u003cp> \u003cstrong>场景法介绍书籍及目标设定\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景法介绍图书】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>场景：\u003c/strong>\u003c/p>\u003cp>新年伊始，我们几乎每个人都许下新年愿望，对未来充满美好憧憬和期待，但我们常常听说一句话，理想很丰满，现实很骨感。往往在现实和愿望之间，横亘着一条巨大的鸿沟，一旦我们遭遇挫折，就容易放弃，萎靡不振，裹足不前。陷入“新年决心陷阱”，甚至对自我产生怀疑和否定。就拿我来说，我对照了一下去年的计划，完成都不到30%，所以直到现在，我干脆都制定出我的2023年计划。\u003c/p>\u003cp>\u003cstrong>提问： \u003c/strong>\u003c/p>\u003cp>那到底到底是什么阻碍了我们实现梦想，在的内心深处，是什么羁绊住了我们的脚步，使我们寸步难行？\u003c/p>\u003cp>我们该如何跨越从想到到做到的天堑鸿沟，朝着梦想勇往直前？\u003c/p>\u003cp>\u003cstrong> 影响:\u003c/strong> \u003c/p>\u003cp>如果我们不能拥有积极乐观的思维，将梦想照进现实，就会很容易陷入精神内耗的窘境，一边踩着油门，一边踩着刹车，让自己的心力和精力都在空耗，让我们疲惫不堪压力重重，却又裹足不前，无助于改变和成长，久之会限于悲观消极，甚至自暴自弃，甚至习得性无助。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>\u003c/p>\u003cp>有没有一种健康积极的思维方式，让我们能够既能对未来充满期待，又能从容面对现实生活中的困境和障碍，积极应对，逐一排除，坚毅前行，跨越想和做的鸿沟，将梦想照进现实。答案是有的，《 woop思维心理学》这本书将会告诉我们答案。当梦想无法实现，行动发生障碍，我们只需woop一下，我们就能能量满满的重新上路。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>1、希望通过今天的学习，大家能够分辨并陈述出什么是真正的积极的乐观主义（拆页1）\u003c/p>\u003cp>2、能简单模仿应用woop的四步法，去排除追逐梦想过程中的障碍，让自己阔步向前。（拆页2）\u003c/p>","ratings_count":1,"texts":[{"id":19762,"quote":"\u003cp> \u003cstrong>拆页R1-乐观的幻想\u003c/strong>\u003c/p>\u003cp>乐观的幻想能够消除当前的担忧和痛苦。幻想源于急迫的需求，能帮助我们在艰难中——在我们失去控制，只能等待外部条件来满足我们的需求时—坚持住。在并非极端的处境下，乐观的幻想能暂时给予我们逃避现实的愉悦，还能让我们在无形中探索更深层的渴望一—亦即我们真正想要的是什么，真正属于我们的是什么，我们的归属是什么，由此帮助我们保持清醒。\u003c/p>\u003cp>幻想有很多好处，但也因条件而论。它们无助于减肥、戒烟、找到工作，但它们能帮助我们在沙漠中保持希望，在政治压迫中存活，在等待法官判决贩毒的男友时保持信念。其关键在于，不要向幻想索取它无法提供的东西。只要能够把握好乐观的幻想有什么效果有什么局限，它们就能成为我们的助手，相反，它就是我们的束缚。抛弃幻想是不对的，同样，盲目地认为只需幻想就能达成心愿也是不对的。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段告诉我们，什么是乐观主义，乐观主义的价值和意义，它能做什么，以及不能做什么。\u003c/p>\u003cp>乐观主义能让我们在困境中保持希望，支撑自己走出人生的至暗时刻，比如说《活出生命的意义》的作者，意义疗法的奠基人弗兰克尔深陷纳粹的集中营，时刻面临生命威胁，但一定要活下去的希望，支撑他坚持到最后终于活了下来。\u003c/p>\u003cp>乐观主义让我们在现实中坚持梦想，信守使命的感召，比如说乔布斯：怀着活着就要改变世界想梦想，历经风雨挫折，包括中途被苹果扫地出门，仍矢志不移，使命和信念感召他不离不弃，最终王者归来，做出一系列划时代的伟大革新产品。\u003c/p>\u003cp>\u003cstrong>【不那么做的坏处】\u003c/strong>\u003c/p>\u003cp>所以，乐观主义对我们每个人都非常重要，如果你没有乐观主义的思维和心态，遇到人生重大打击，你就有可能一蹶不振，无法走出。\u003c/p>\u003cp>\u003cstrong>【异议预防】\u003c/strong>\u003c/p>\u003cp>但是，有个异议我也一定要跟大家澄清，我们一定要客观认知乐观主义，我们要做一个乐观主义者，就像硬币都有两面，乐观主义也不全是积极好的，他也有其局限的地方，一种是积极的乐观主义，一种是虚无的空想主义，。观主义无助我们改变结果，搞不好，我们反而容易陷入盲目乐观，自我麻痹或者自欺欺人。\u003c/p>\u003cp>\u003cstrong>【概念辨析】\u003c/strong>\u003c/p>\u003cp>为了增进大家的理解，我给大家列举几种现象，大家看看是不是积极的乐观主义。\u003c/p>\u003cp>反\u003c/p>\u003cp>1、天天躺在床上，不去干活，每天花2块钱买一支彩票，幻想有一天能中五百万。，迎娶白富美，走上人生巅峰，这是乐观主义吗？ \u003c/p>\u003cp>不是，那是自欺欺人的妄念。因为你不能把人生的梦想寄托在不劳而获上。\u003c/p>\u003cp>2、工作或生活中遇到困难和问题，不去思考对策和行动，只是宽慰自己，车到山前必有路，睡一觉过去，明天就会好了，这是积极的乐观主义吗？\u003c/p>\u003cp>不是，这是属于盲目乐观，自我逃避。\u003c/p>\u003cp>3、人生充满迷茫萎靡不振，但想起自己梦想实现的样子，于是精神为之一振，信誓旦旦，告诉自己明天好好开始，但是明日复明日，晚上思索千条路，一觉醒来走老路，这是积极的乐观主义吗，\u003c/p>\u003cp>不是，这是想和做的分离。乐观的想法不能代替真刀真枪的干法。\u003c/p>\u003cp>正\u003c/p>\u003cp>那比方说 在创业中商业模式不能跑通变现，在痛苦中煎熬的人，依然坚信自己总有一日会取得成功，并同时不断迭代自己的产品，寻求正反馈，这是不是积极的乐观主义？当然是。\u003c/p>\u003cp>普通的大众，也像乔布斯一样怀揣改变的世界的梦想，不断努力让自己成长，变得更优秀，这是不是积极的乐观主义，当然也是\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>那么，如何才能成为一个真正的乐观主义者呢，结合文中的含义以及生活的实际，我认为可以分为三个层次\u003c/p>\u003cp>1、困境的支撑力——逆境中永不放弃希望，用信念去穿越至暗时刻——底层求生存\u003c/p>\u003cp>2、现实的行动力——生活中积极面对现实，用行动去努力改变现状——中层求发展\u003c/p>\u003cp>3、梦想的牵引力——无形中探索深层渴望，用奋斗去实现人生梦想——顶层求实现\u003c/p>\u003cp>\u003cstrong>【案例举例】\u003c/strong>\u003c/p>\u003cp>我给大家举一个我身边的真实的例子。\u003c/p>\u003cp>我有个朋友，他的梦想是做一个F1赛车手，体验速度与激情，不断的超越,风驰电掣。还花费几个月工资专程跑到现场去看F1比赛，.当然，这基本是个无法实现的梦想，当然，次之是努力赚钱，买一辆迈凯伦的跑车。\u003c/p>\u003cp>但事与愿违，他几次创业都不成功，但从未放弃对于生活的希望，积极乐观的面对一切。在生计没有着落的时候，最后毅然选择去做了一名的士司机。他这一做就是6年。第一年，十余次交通违规，还被乘客投诉，但五年，没有一次违章。出了一次等红绿灯无辜的被后面的车追尾，没发生一起交通事故。我很好奇，问他是怎么做到的，他说，以前喜欢赛车，以为是喜欢的是速度、激情和超越，等后来才体会到喜欢的是对车辆和生活的掌控感和分寸感。所以后面就要平安且不违规的将乘客送到目的地为目标。我认为他的经历符合一个乐观主义者的这三层特征。\u003c/p>\u003cp>1、困境的支撑力——逆境中永不放弃希望，用信念去穿越至暗时刻——底层求生存\u003c/p>\u003cp>2、现实的行动力——生活中积极面对现实，用行动去努力改变现状——中层求发展\u003c/p>\u003cp>3、梦想的牵引力——无形中探索深层渴望，用奋斗去实现人生梦想——顶层求实现\u003c/p>\u003cp>我这个朋友现在又去创业了，我期待他能成功，圆梦。\u003c/p>","interaction":"\u003cp>今天我们学习了什么是乐观主义，以及如何成为一个乐观主义者，我们可以设想一下，未来的一周里，你在工作或生活中可能面临的需要以乐观主义去积极面对的事项，如如何面对疫情反复冲击和影响下，不堪的2022，或者该如何规划2023年的计划等，请按照我上述给大家总结的三个层次展开阐述，给大家5分钟时间，每个人先编写一个小剧本，然后再组内进行分享，注意剧本要有时间、地点、人物和事件（包括起因、经过、结果）和双方的对话、动作等。稍后我们请小伙伴分享一下他的剧本。\u003c/p>\u003cp>学习者：刘老师 跟孩子沟通梦想\u003c/p>\u003cp>刘老师：你的梦想是什么？\u003c/p>\u003cp>孩子：成为一个美术老师，\u003c/p>\u003cp>刘老师：那你要做什么\u003c/p>\u003cp>孩子：天天坚持练习绘画\u003c/p>\u003cp>刘老师：你可能会遇到那些困难和障碍\u003c/p>\u003cp>孩子：时间忙不过来，或者无法坚持，或者兴趣转移到其他事情上了\u003c/p>\u003cp>刘老师：那你打算怎么办？\u003c/p>\u003cp>孩子：我会安排好写作业和画画的时间，尽量抽时间坚持画画，如果没兴趣了，就换一个老师上课。\u003c/p>\u003cp>刘老师：万一你成不了美术老师怎么办？\u003c/p>\u003cp>孩子：如果我做不了美术老师，我也可以去做其他的事情。人人都要有自己的梦想，我要从基础的开始做起，坚持不放弃……\u003c/p>\u003cp>\u003cstrong>【过渡总结】\u003c/strong>\u003c/p>\u003cp>关于什么是乐观主义，我联想到我最喜欢的一句人生格言，来自于罗曼罗兰\u003c/p>\u003cp>世界上只有一种英雄主义，就是看清生活的真相之后，依然热爱生活。\u003c/p>\u003cp>同理，我可以套用这个句式，来给大家总结一下什么是乐观主义：\u003c/p>\u003cp>世界上只有一种乐观主义，就是对未来有美好的憧憬之后，依然愿意下地干活。\u003c/p>\u003cp>\u003cstrong>【自测量表】\u003c/strong>\u003c/p>\u003cp>我想请问下大家，你是一个积极的乐观主义者吗？请大家先花1-2分钟时间，我们先用一个表格来自测下：\u003c/p>\u003cp>好的，看到大家都已经完成了测评。大家都是多少分呢？\u003c/p>\u003cp>如果你的得分在：\u003c/p>\u003cp>0-10分，说明你是一个高度的积极乐观者\u003c/p>\u003cp>11－20分，你总体是个乐观主义者\u003c/p>\u003cp>21－30分，你可能是个悲观主义者\u003c/p>\u003cp>不管得分高低，也请大家不用过度关心和忧虑，任何事物都有两面，乐观可能让我们充满能量，勇往直前，但悲观能让我们防微杜渐，远离危险。\u003c/p>\u003cp>不过大家注意到没有，刚刚我们讲什么是乐观主义，给出了概念，给出了三个层次的步骤，但没有给出解决具体的做法，依然只是貌似有营养的鸡汤，下面我想给大家带来喝鸡汤的勺子。\u003c/p>\u003cp>请大家先花2分钟时间阅读一下这个片段，看完了的小伙伴请举手示意。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":19814,"quote":"\u003cp> 《woop思维心理学》拆页2---woop思维四步法\u003c/p>\u003cp>\u003cstrong>W、愿望或心事：\u003c/strong>\u003c/p>\u003cp>放松，深呼吸、想一个私人或工作方面的愿来虽然有些手但你觉得能够达成。它可以是你打算在当天根本月本年之内要达成的，只要是你想要WOOP的愿望都可以。\u003c/p>\u003cp>如果你在同一时间段内有好几个愿望，那就选一个对你而言最重要的。然后把这件事放在思考的中心。\u003c/p>\u003cp>\u003cstrong>O、结果。\u003c/strong>\u003c/p>\u003cp>你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象\u003c/p>\u003cp>地想象这件事的相关情况和经历。任思绪驰骋，不要有顾虑。不要着急，慢慢来，要是喜欢的话，可以闭上眼睛。\u003c/p>\u003cp>做好准备之后，睁开眼睛，进入下一个步骤\u003c/p>\u003cp>\u003cstrong>0、障碍。\u003c/strong>\u003c/p>\u003cp>有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的的障碍，这个障碍里最关键的想法和行为是什么？是不是某种习惯或者先入为主的想法？在思索障碍的时候，人们往往会在外部寻找，把“罪名”扣在他们孜然味妨碍了他们的外部条件或人的头上，但是，通过选取一个我们认为可以达成的愿望这种做法，就把外部障碍考虑在内了，这一练习的目的是放置我们在追逐梦想的路上自己绊倒自己。\u003c/p>\u003cp>\u003cstrong>P：计划：\u003c/strong>\u003c/p>\u003cp>要克服或规避这个障碍的话，你能怎么做，想一个最有效的那个想法或行动，将其牢记与心，然后想一想这个障碍下次出现将是何时何地，接着制定一个“如果……那么……”计划，如果障碍X出现了（何时何地），那么我就采取行动Y”,,然后将这个计划重复一遍给自己听。\u003c/p>\u003cp>就这样。完成。是不是很简单？这种练习你想隔多长时间做一次都可以，只要能有个身心清静的地方就行。你可以在公交车上、车上、飞机上闭上眼睛做WOOP,在等待同事或朋友而感到无聊时也可以做。早上醒来、晚上睡前也行。把WOOP养成习惯。当然，在压力大的时候，在事情棘手而解决办法尚不明朗的时候也要用到它\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>我希望大家能完成今天的拆页学习后，并能简单模仿应用woop思维的四步法，去排除工作生活中的障碍，让自己阔步向前，向着梦想进发。\u003c/p>\u003cp>\u003cstrong>I拆书家讲解引导：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>概念讲解：\u003c/strong>\u003c/p>\u003cp>What\u003c/p>\u003cp>这个片段具体讲述了一种乐观主义思维——woop思维的四步法，即愿望、结果、障碍、和计划\u003c/p>\u003cp>Way\u003c/p>\u003cp>为什么这种思维有效呢，因为他是用了一种心理比对的方法，将梦想照进现实，既描绘了愿景和目标，又展现了现实的障碍，针对障碍采取计划和行动，这样就有的放矢，针对性强，解决了乐观主义最主要的一个bug，从想到做的鸿沟。所以非常有效。\u003c/p>\u003cp>Where\u003c/p>\u003cp>那它使用在哪里呢，我们开始探索和启动一件有远大前景和现实困难的事项，能让我们目标明确，动力充沛，勇往直前。\u003c/p>\u003cp>如果你的工作已经在进行中排除了障碍，正处在心流中，就没有必要强行刻意在利用这个woop模型，那就是画蛇添足。\u003c/p>\u003cp>How\u003c/p>\u003cp>那具体我们该怎么做呢，我将这四个步骤给大家讲解一下\u003c/p>\u003cp>1、描述梦想：\u003c/p>\u003cp> 清晰的描绘出你的梦想愿望\u003c/p>\u003cp>2、明晰结果\u003c/p>\u003cp>你实现愿望最佳结果是什么\u003c/p>\u003cp>3、预判障碍\u003c/p>\u003cp> 在开始做之前，设想预判和列举在开展行动过程中可能存在的种种障碍和困难\u003c/p>\u003cp>4、计划行动\u003c/p>\u003cp> 如何克服障碍和困难，我们该怎么计划和行动。重点解决如何排雷。\u003c/p>\u003cp>\u003cstrong>举例说明\u003c/strong>\u003c/p>\u003cp>比方说今年我制定了打造个人IP成长专家的计划\u003c/p>\u003cp>1、描述梦想：\u003c/p>\u003cp> 我要致力于成为成长专家，帮助企业和个人实现成长发展，体现自我的价值\u003c/p>\u003cp>2、明晰结果\u003c/p>\u003cp>实现个人职业转型、价值创造和商业变现，提升个人品牌和影响力，让更多的企业和个人收益\u003c/p>\u003cp>3、预判障碍\u003c/p>\u003cp>在开始做之前，设想预判和列举在开展行动过程中可能存在的种种障碍和困难\u003c/p>\u003cp>A缺少内容输出\u003c/p>\u003cp>B缺少正反馈 \u003c/p>\u003cp>C价值创造和商业变现不及预期。\u003c/p>\u003cp>4、计划行动\u003c/p>\u003cp>A、一起床就开始写，日更2000字,如果延误了，就晚上补完再睡觉\u003c/p>\u003cp>B、内容一生产出来就加入各种社群去链接分享获取反馈，如果得到正反馈，就给自己加个鸡腿\u003c/p>\u003cp>C、以商业咨询案养活自己，个人成长只求价值创造，现阶段不考虑商业变现。如果支撑不下去了，就卖一套房\u003c/p>","interaction":"\u003cp>\u003cstrong>A学习者拆为己用：学习者拆为己用：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】微行动学习\u003c/strong>\u003c/p>\u003cp>在woop思维四步法中，梦想、结果、障碍和行动计划，你认为那个最难、最有价值或最重要，我们可以再深入探讨一下\u003c/p>\u003cp>大家请听从内心的声音，各自发表自己的看法和意见。\u003c/p>\u003cp>我们还是先分成两个小组，每个小组先内部探讨一下，统一拿出一个意见，我依次邀请每一组一个代表发言\u003c/p>\u003cp>刘老师：愿望\u003c/p>\u003cp>王老师：行动计划\u003c/p>\u003cp>苏老师：障碍\u003c/p>\u003cp>李老师：行动计划\u003c/p>\u003cp>\u003cstrong>【1、明确问题】\u003c/strong>\u003c/p>\u003cp>好，根据大家反馈的意见，我们将行动计划作为今天探讨的问题\u003c/p>\u003cp>\u003cstrong>【2、引导分组讨论问题的本质】\u003c/strong>\u003c/p>\u003cp>你认为难的本质根源是什么\u003c/p>\u003cp>我们经常执行力不够，知易行难。愿望不够强烈，对困难和障碍估计不足，预期目标不明显，导致执行力不强，行动力不足，很难实现预期的目标和结果。\u003c/p>\u003cp>woop的行动的逻辑，是专注于解决引发行动障碍和卡点，只要解决了障碍的困扰，那行动力自然就强了。\u003c/p>\u003cp>\u003cstrong>【3、明确问题的本质】\u003c/strong>\u003c/p>\u003cp>那这个问题的本质是什么？\u003c/p>\u003cp>问题本质就是：如何高效行动，拉进现实和期望之间的距离。\u003c/p>\u003cp>\u003cstrong>【4、引导分组讨论解决方案】\u003c/strong>\u003c/p>\u003cp>我们该如何解决这个问题，请大家共创下行动步骤：\u003c/p>\u003cp>如何才能高效行动？\u003c/p>\u003cp>1、制定并分解目标\u003c/p>\u003cp>2、罗列可能遇到的所有障碍\u003c/p>\u003cp>3、分阶段的排除障碍\u003c/p>\u003cp>4、用如果——就的执行意图执行\u003c/p>\u003cp>\u003cstrong>【5、每组学习者代表讲解自己组的讨论成果要点】\u003c/strong>\u003c/p>\u003cp>按照上述步骤，请每组学习者讲述自己组内的探讨成果。\u003c/p>\u003cp>例如：\u003c/p>\u003cp>1、制定并分解目标：\u003c/p>\u003cp>制定了日更2000字的日更计划\u003c/p>\u003cp>2、罗列可能遇到的所有障碍\u003c/p>\u003cp>可能会不知写什么内容\u003c/p>\u003cp>写不出来\u003c/p>\u003cp>时间无法保证\u003c/p>\u003cp>3、分阶段的排除障碍\u003c/p>\u003cp>提前做内容规划\u003c/p>\u003cp>按照提纲，确保2000字\u003c/p>\u003cp>每天早上五点起来写，精力更旺盛\u003c/p>\u003cp>4、用一……就……“如果——就”的执行意图执行\u003c/p>\u003cp>早上五点，一起床做到电脑前，就开始写\u003c/p>\u003cp>如果白天延误了，就晚上补充字数。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>今天我们学习woop的思维模型，光说不练假把式，我们可以设想一下，在未来的1-2周，面临新年愿望，职业发展机遇，人生重大规划等等场景，大家需要应用到woop的思维，大家先考虑一下，给大家3-5分钟的时间，等下我再邀请小伙伴上来分享。\u003c/p>\u003cp>刘老师分享\u003c/p>\u003cp>1、描述梦想：\u003c/p>\u003cp> 做一个5000万以上级别的项目\u003c/p>\u003cp>2、明晰结果\u003c/p>\u003cp>实现财务收入上的极大增长，换个大的房子和汽车，可以去世界各地旅行，让家人过上幸福无忧的生活……\u003c/p>\u003cp>3、预判障碍\u003c/p>\u003cp>处理好商务关系，关键决策人的关系处理，这是关键。\u003c/p>\u003cp>防范竞争对手，预防竞争对手怎么出招，提前规划思考怎么去应对\u003c/p>\u003cp>4、计划行动\u003c/p>\u003cp> 如何克服障碍和困难，我们该怎么计划和行动。重点解决如何排雷。\u003c/p>\u003cp>想尽一切办法搞定甲方关键决策人，处理好商务关系，投标的专业性、实施能力和定价能力。\u003c/p>\u003cp>从内部获取竞争对手的信息，结合自己的预判，预判对手的策略及报价出招，除了价格，再关键条款上有无独特性和排他性。\u003c/p>\u003cp>\u003cstrong>最终总结\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天我给大家分享了两个拆页，第一段内容，给大家分享了什么是积极的乐观主义，分为逆境中求生存的支撑力、现实中求发展的行动力，未来中求实现的梦想力，给大家端上了一碗鸡汤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在第二个拆页，我给大家提供了一个勺子，如何用woop思维的四步法，梦想-结果-障碍--计划四个步骤，解决了从认知到行动的闭环。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>让梦想驱动我们前行，让我们将梦想照进现实，当行动遭遇障碍，梦想无法实现，有时，我们只需要woop一下。就能重新上路，筑梦前行。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我今天的分享到此结束，谢谢大家。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1682326569000,"updated_at":1683470069000,"ria":true},{"id":15513,"topic":"WOOP思维工具，把梦想变成现实","learn_goal":"","remark":"你是不是有很多愿望？比如想要更健康的身体，想要更和谐的人际关系，想在学习/工作中表现得更好……既然是愿望，那就还没实现吧？那么是什么阻碍了你实现梦想？告别心灵鸡汤，与拖延症说拜拜，来拆书现场试一试神奇的WOOP思维工具，让你摇身一变，从“梦想家”变成“行动派”！\n","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"耿耿","city":""},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>[自我介绍]大家好，我是耿耿，一名教育行业的资深课程设计师，热爱阳光和自由，擅长发现生活中的美好。\u003c/p>\u003cp>[分组]在开始之前，我先分个组，目的是为了帮助大家达到更好地学习效果。今天在场有5位学习者，我会分成2个小组，这边2位为一组，对面3位是第二组。待会的讨论环节请大家以小组为单位进行交流分享。\u003c/p>\u003cp> FAB图书介绍\u003c/p>\u003cp>（F）今天我为大家带来的是《WOOP思维心理学》，这是一本关于“愿望”和“实现愿望”的书，作者加布里埃尔·厄廷根教授是全世界研究人类驱动力的心理学家，她基于20多年的科学研究在这本书里提出了WOOP思维工具，可以帮助人们克服障碍，实现愿望和梦想。\u003c/p>\u003cp>（A）厄廷根教授的研究成果目前已经被纽约时报、华尔街日报、华盛顿邮报、今日心理学等多家知名媒体转载，同时也受到包括诺贝尔经济学奖得主詹姆斯、哈佛大型教授卡罗尔在内数十位专家的联袂推荐。相信应该是一本值得阅读的好书。\u003c/p>\u003cp>（B）想想看，截至目前，你最想成为什么样的人？你的愿望是什么？它为什么还没实现？是什么阻碍了你实现梦想？或者近期你有没有想做某件事，可以是非常小的一件事，但就一直拖着没做？如果你想真正地开始改变，开始行动，不再仅仅停留在想的阶段，那么这本书就可以帮助你达成目标。\u003c/p>\u003cp>今天分享的片段来自这本书的第七章，主题是WOOP思维工具。接下来给大家2分钟时间阅读原文，读完请举手示意。\u003c/p>","ratings_count":1,"texts":[{"id":19560,"quote":"\u003cp>WOOP 思维方式，即“心理比对”。WOOP 是“wish”（愿望）、“outcome”（结果）、“obstacle”（障碍）以及“plan”（计划 4 个英文单词的首字母。它可以用于各种可能的愿望上面，不论事大是小，是短期还是长期的愿望都行。如果你是一位教授，你可以用它来达到事业的一个新的里程碑、提高你的专业技能等等；如果你是个学生，你可以用它使自己的学习变得更加高效；如果你身为家长，在处理与孩子有关的棘手问题时，用它可以更有成效……任何人都可以将WOOP用在自己的生活中，任何目标和愿望都适用。\u003c/p>\u003cp>WOOP包含 4 个步骤：\u003c/p>\u003cp>计划名称：\u003c/p>\u003cp>愿望W：\u003c/p>\u003cp>结果O：\u003c/p>\u003cp>障碍O：\u003c/p>\u003cp>计划P：\u003c/p>\u003cp>如果（时间地点障碍X出现了），那么我就（采取行动Y）。\u003c/p>\u003cp>如果（），那么 我就（）。\u003c/p>\u003cp>以制定24小时内的锻炼和健康饮食计划为例：\u003c/p>\u003cp>今天的锻炼愿望：下班后跑步\u003c/p>\u003cp>最佳结果：感觉身心舒畅\u003c/p>\u003cp>障碍：下班回家后很累\u003c/p>\u003cp>计划：如果7点到家时已经很累，那么我就换上跑步鞋走出家门走一走。\u003c/p>\u003cp>今天的健康饮食愿望：吃3份水果\u003c/p>\u003cp>最佳结果：身体健康\u003c/p>\u003cp>障碍：家里没有水果\u003c/p>\u003cp>计划：如果我早上8点出门去上班，那么我就顺路经过便利店买些水果。\u003c/p>","explains":"\u003cp>好，时间到。\u003c/p>\u003cp>想下班后学点技能搞点副业，可是总是觉得下班后太累了，或者经常加班没空。于是日复一日，副业永远没启动。想早起读书或者锻炼，总有起不来的借口，或者顶多三分钟热度就恢复原状。你想做的事看起来遥遥无期，总是有这样那样的障碍，你也一直保持着现状始终没有任何改变。\u003c/p>\u003cp>如果你有同样的问题，今天的拆页就为我们带来了应对这类问题的对策：WOOP思维方式。简单一句话概括，这是一个反惰性的超强行动工具，帮助人们将想法付诸实践。\u003c/p>\u003cp>如何使用这个方法呢？结合一周早起阅读写作的计划为例：\u003c/p>\u003cp>第一步：明确愿望W。这个愿望是你觉得虽然有点挑战但是能够达成的。比如坚持一周每天6点起床进行45分钟的阅读/写作。一个WOOP只专注一个愿望即可。\u003c/p>\u003cp>第二步：想象结果O。\u003c/p>\u003cp>你实现愿望之后的结果、景象是怎样的？尽量生动形象地想象一下这个结果。比如通过持续的知识整理输出，养成写作的习惯，出了自己的书等等。\u003c/p>\u003cp>第三步：预测可能的障碍O。\u003c/p>\u003cp>深挖细剖，找到把你叫停的障碍。比如“早上赖床起不来”、 “醒过来就想先耍会儿手机”等。障碍可以尽量多想几个，多准备一些预案，让行动过程更顺利。\u003c/p>\u003cp>第四步：写出可操作的计划P。\u003c/p>\u003cp>注意，这个计划不是一般所说的目标达成计划，而是针对你预测的障碍制定一套如何克服或者规避障碍的应对方案。具体做法就是“如果……那么……”句子。比如：“如果（某一天中断了），那么我就（第二天再早起一点儿，补上前一天的时间）。\u003c/p>\u003cp>（预防异议）\u003c/p>\u003cp>说到这里，可能会有人说了，如果我在思考障碍的时候，已经发现障碍很大几乎不可能跨越，那该怎么办呀？这个问题非常好，如果障碍实在太大，那你就要重新评估W愿望的合理性了。不行咱就换个愿望呗。\u003cbr> \u003cbr> \u003c/p>\u003cp>（正例）最近两周我试着用这个工具来实现\u003cu>晚上11点前一定要睡觉的目的\u003c/u>\u003cu>【\u003c/u>愿望】：\u003c/p>\u003cp>以前每天晚上上床后，我习惯性地先刷一圈手机再睡，心里想着就刷一会儿而已，但是没有哪一次不超过11点甚至更晚的。\u003c/p>\u003cp>两周前，我按照WOOP的工具设想了一下：如果每天11点前能睡觉的话，我就能去掉讨厌的黑眼圈，皮肤也不像现在这么灰暗，气色看起来会好很多【结果】。\u003c/p>\u003cp>但是，阻碍我准时睡觉最大的【障碍】就是手机在枕边！\u003c/p>\u003cp>所以，（如果）我睡觉前又想把手机拿进卧室，（那么）我就赶紧把手机放到厨房去充电，远离卧室。（如果）我半夜醒来的时候不知道时间，（那么）我就用手环替代手机提示时间。【计划】\u003c/p>\u003cp>现在，我已经坚持了2周能在11点前睡觉。应该还能继续保持下去。\u003c/p>\u003cp>（边界）WOOP可以用在重要的事情上，也可以用在生活中的小事。只要你有意愿完成并且的确是可实现的目标，就可以使用WOOP思维方式。\u003c/p>","interaction":"\u003cp>A2显像提问\u003c/p>\u003cp>(提问)请你想象一下，接下来的一周或者一个月，你有没有想做但一直拖着没做的愿望和想法？可能是想减肥10斤，也可能是想和老板谈加薪，或者是想学习一个新技能，想参加拆书过级，但总是找不到时间。 请大家花2分钟时间在小组里讨论交流，自己近期的一个愿望：什么时候？在哪里？希望达成什么事？待会我会请一位伙伴来分享。\u003c/p>\u003cp>时间到了，有小伙伴自愿分享的吗？好，欢迎丁田勇来分享。\u003c/p>\u003cp>(学习者分享)大家好，我有一个最近想做的事情，就是把小红书账号开起来。\u003c/p>\u003cp>(点评)哇，这个想法真好，谢谢田勇分享他的愿望。那么这样的愿望如何从想到做呢，我们接下来看。\u003c/p>\u003cp>A2分步催化\u003c/p>\u003cp>(发放资料见末尾+提问+小组讨论)\u003c/p>\u003cp>根据今天理解的WOOP思维工具，如果到了下一周或下个月，你要怎么做才可以把你的想法转变成现实呢？给大家一份模版做参考，你可以在这方面写下你的WOOP四步骤，也可以照着这个资料模版口头和同伴们分享，给大家3分钟的时间简单讨论一下。\u003c/p>\u003cp>时间到。 有小伙伴主动分享的吗？好的，田勇还是你来给大家分享你会怎么做吧。\u003c/p>\u003cp>(学习者分享)大家好，我想把小红书账号做起来，这是我的愿望。如果这个愿望实现了，经营得好的话流量过万，会给我带来副业的收入，以及成就感。但是，在这个过程中，最大的障碍可能是我做的事情太多了，精力不够，有时就会懒惰，不想写。针对这个障碍，我觉得可以这样来预设：（如果）我又被其他事情牵扯了太多精力，没有时间和力气来写小红书，（那么）我就删减掉部分目前在做的事情，把精力集中。这就是我的WOOP。谢谢。\u003c/p>\u003cp>(点评)谢谢田勇的分享，请大家掌声鼓励。田勇用四个步骤按照WOOP的方式，找到创建小红书账号的阻碍，也建立了打破阻碍的计划，可以看出，大家对今天所分享的技能掌握得很不错。\u003c/p>\u003cp>收尾\u003c/p>\u003cp>有时愿望就在眼前，却很难实现，现在有了WOOP思维工具，你就不用再和意志力做斗争了，直接全力以赴执行预案就行。祝福大家都能行动力满满，早日实现自己的梦想。我今天的拆书就到这里，我是耿耿，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1680499051000,"updated_at":1680499224000,"ria":true},{"id":11569,"topic":"如何利用WOOP思维实现梦想","learn_goal":"","remark":"这本书的作者是美国的加布里埃尔·厄廷根教授，她是著名心理学家。她20多年来一直在研究内心动力，发现人们普遍赞扬的“乐观心态”有时竟成了实现梦想的阻力。为了解决这一问题，她提出了全新的思维方式“WOOP”，通过“愿望、结果、障碍、计划”4个步骤，帮助人们将乐观的想法落地执行。而且，这个方法已被验证行之有效。那些参加厄廷根教授调查研究的人员利用“WOOP思维”，在戒烟、减肥、提高学习成绩、改善人际关系等方面都有了显著好转。此外，“WOOP思维”不仅仅帮你实现梦想，更能让你清晰内心的真正需求，活出无悔的人生。","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"煦涵","city":"徐州市"},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>\u003cstrong> 【自我介绍】\u003c/strong>\u003c/p>\u003cp> 各位小伙伴们，大家好。我是今天的过级者曹玉姣，字是煦涵。我来自江苏徐州。我的工作标签是医院宣传工作者，家庭标签是二宝妈妈，站在这里的标签是一个崇尚读书引领个人成长的终身学习者，今后期待能和各位在“拆书帮”徐州分舵携手与进，共同成长。\u003c/p>\u003cp> \u003cstrong> 【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>首先，让我来介绍一下拆书和拆书帮。所谓“拆书”是一种阅读学习工具，主要是用于致用类图书，帮助我们深入理解知识点，关联以往经验，并且将知识规划未来行动，落到实处，做到 “知行合一”。这个工具通过三张便签——RIA便签来使用。R便签表示阅读原文；I便签是用自己的话重述知识点；A便签可以分为A1和A2便签。A1便签是回顾和知识点有关联的以往经历；A2便签是利用知识设定一个目标，并规划行动来达成目标。通过这三张便签，不仅可以加深对知识的理解，还能让你规划未来使用的场景。真正做到“知行合一”。\u003c/p>\u003cp> “拆书帮”，是一群爱好“拆书法”的学习社群，是非营利性的自发社群。只要你爱读书、爱学以致用、期待不断提升能力都可以申请加入拆书帮的大家庭。目前，拆书帮在全国各地有50家分舵，有 16家筹备分舵，覆盖全国28个省47座城市。随着时间的推移，社群在一天天壮大，影响身边的人持续精进共同成长。在此呢，热烈欢迎大家进入拆书帮学习。\u003c/p>","ratings_count":1,"texts":[{"id":15496,"quote":"\u003cp> 话不多说，我今天分享的片段来自于《WOOP思维心里学》。这本书的作者是美国的加布里埃尔·厄廷根教授，她是著名心理学家。她20多年来一直在研究内心动力，发现人们普遍赞扬的“乐观心态”有时竟成了实现梦想的阻力。为了解决这一问题，她提出了全新的思维方式“WOOP”，通过“愿望、结果、障碍、计划”4个步骤，帮助人们将乐观的想法落地执行。而且，这个方法已被验证行之有效。那些参加厄廷根教授调查研究的人员利用“WOOP思维”，在戒烟、减肥、提高学习成绩、改善人际关系等方面都有了显著好转。\u003c/p>\u003cp> 所以今天的拆页主题是：如何利用WOOP思维实现梦想。\u003c/p>\u003cp> 首先我们先来阅读原文片段。现在我把原文拆页发给大家，请大家用2分钟时间阅读。拆页内容略微有点长，请大家2分钟时间阅读。读的时候可以在产生思想碰撞的地方划线、做关键词备注等等记录。读完后请大家举手或者看向我并点头示意。\u003c/p>\u003cp> 【R原文片段】\u003c/p>\u003cp>W：愿望或心事。放松，深呼吸，想一个私人或工作方面的愿望或牵挂，虽然有些棘手但你觉得能够达成。它可以是你打算在当天 、本周、本月、本年之内要达成的，只要是你想要woop的愿望都可以。如果同一时间段内有好几个愿望，那就选一个对你而言最重要的，然后把件事放在思考的中心。\u003c/p>\u003cp>O： 结果。你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。任思绪驰聘，不要有顾虑。不要着急，慢慢来，要是喜欢的活，可以闭上眼睛。\u003c/p>\u003cp>做好准备之后，挣开眼晴，进入下一个步骤：\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？是不是某种习惯或先入为主的想法？在思索障碍的时候，人们往往会在外部寻找， 把&quot;罪名“扣在他们自认为妨碍了他们的外部条件或人的头上。但是，通过选取一个我们认为可以达成的愿望这种做法，就把外部障碍考虑在内了 （要是外部障碍过大，我们就不会认为此愿望是&quot;可以达成“ 的了） 这一练习的目的是防止我们在追逐梦想的路上自己绊倒自己。\u003c/p>\u003cp>P：计划。要克服或规避这个障碍的话，你能怎么做?想一个—最有效的那个——想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制订一个&quot;如果……那么…”计划：&quot;如果障碍X出现了 （何时何地），那么我就采取行动Y。”然后将这个计划重复一遍给自己听\u003c/p>","explains":"\u003cp>【过渡语】好的，我看大家已经都阅读完原文片段了。下面由我来带领大家一起看一下原文片段的内容。\u003c/p>\u003cp> 【what】所谓“WOOP”就是“愿望、结果、障碍、计划”四个英文单词的首字母。这四个词也是“WOOP” 工具实现目标的4个步骤。通过这样才能让我们的大脑在潜意识中将“未来”和“现实”联系起来，在憧憬目标实现的喜悦中，强化行动力，克服障碍。\u003c/p>\u003cp> 【why】大家可能会疑问：“为什么这四个步骤会帮助我们实现目标呢？”根据这本书的作者厄廷根教授的研究，盲目的乐观幻想会欺骗大脑。因为乐观的幻想会让我们有种短暂的精神愉悦，会让我们忽视实现梦想的障碍。让我们进入一种平静、昏沉的状态之中，做事的动力反而降低了。我们自然也不会意识到，成功的关键恰恰在于行动。所以，乐观主义加上行动才会让我们的梦想有可能实现。我们要思考的是如何制定出切实可行的计划，克服梦想实现过程中的障碍，让梦想落地生根。\u003c/p>\u003cp> 【how】那我们该具体怎么做呢？\u003c/p>\u003cp>第一步，定愿望。想想你最近想达成的目标。这个目标可大可小，只要你想实现的目标都可以。\u003c/p>\u003cp>第二步，想结果。这个结果就是如果目标大成功会在未来给你带来什么样好的结果。尽量生动地想象，美好的未来会激发你的斗志。\u003c/p>\u003cp>第三步，找障碍。这个步骤很关键。你要追问自己，阻碍自己实现目标的障碍是什么？要向内求，关键是障碍产生的想法和行为是什么？想清楚这些障碍，你才能认清障碍的来源，才能想办法克服它。\u003c/p>\u003cp>第四步，定计划。这里边有个关键的一步，就是当你感觉到障碍出现了，你要定一个“如果……那么…”的计划，也就是“如果障碍X出现了 （何时何地），那么我就采取行动Y。”提前在大脑里演练克服障碍的行动步骤。\u003c/p>\u003cp>【where】由此，我们可以看出，WOOP其实是一个使用非常广泛的实现目标的工具方法，它能够唤起人们的认知、情感和行动，任何人都可以使用这个方法去达成所愿。但是，我们需要将它养成使用习惯才能发挥功效。\u003c/p>","interaction":"\u003cp> 【A1便签】\u003c/p>\u003cp> 【过渡语】下面我讲一下我的切身经历与体会。这让我想起我之前给领导汇报工作时克服紧张情绪的一件事。\u003c/p>\u003cp> 在刚参加工作的前两三年，我一给领导汇报工作就非常紧张，经常因为紧张，不能够清楚表达自己的想法，导致领导的误解，没有达成最初的目的，影响了汇报的效果。又有一次，我要给领导汇报工作的进展情况，需要告知遇到的困难，需要领导指点帮助。我担心自己说不清楚，事先就列出来要说出来的几个要点。但是，一想到汇报，自己紧张的情绪又起来了。我在心里就告诉自己：“不要怕，你是去汇报工作，又不是去接受批评。再说，自己已经尽力把工作做好了，问心无愧。既来之则安之吧。”经过安慰自己之后，我的心定了下来，给领导汇报工作的时候就只想着表达自己想要的表达的要点，顺便提出了要求。汇报很成功，我也达成了我的目标。后来，我就慢慢用这种方法，克服了给领导汇报工作紧张的情绪。\u003c/p>\u003cp> 【过渡语】通过这件事，并结合这个片段，我认识到我可能无意识中用到了WOOP提到的方法，就是提前在大脑中预演遇到的障碍，并想到解决的办法。\u003c/p>\u003cp>1. 事先明确了自己要达到的目标。我在给领导汇报工作前，写下了要汇报的要点，这就是目标，让自己的汇报能清晰地表达这几个点。\u003c/p>\u003cp>2. 期待汇报成功的结果。希望汇报工作进展的同时，向领导寻求帮助，更好地开展以后的工作。\u003c/p>\u003cp>3. 知道了达成目标遇到的障碍。障碍就是紧张，一紧张就会大脑空白，表述不清，还会被自己和领导的情绪影响，影响了汇报的效果。\u003c/p>\u003cp>4. 提前演练了克服紧张的方法。就是给自己放松紧张的压力，汇报工作是为了更好的工作，不要因为自己紧张的情绪影响了最终的目标。因为在汇报时专注于目标，所以我才会不去想紧张的事情，才能安下心来。\u003c/p>\u003cp> 【A2便签】\u003c/p>\u003cp> 【过渡语】你们看，这就是之前我无意识中使用WOOP思维工具的部分方法让我达成了不紧张给领导清晰汇报工作的目标。现在，我们已经学到了WOOP思维工作，知道了它的具体使用方法和步骤，我们就可以更加清晰的列出自己的目标，强化行动力，克服障碍。\u003c/p>\u003cp>通过这个片段，结合我的切身经验，我把这个片段拆为己用，具体我是这么计划的：\u003c/p>\u003cp>1、定目标：早晨5:30分，起床锻炼身体1小时。\u003c/p>\u003cp>2、想结果：提高身体素质，少生病；白天头脑清醒，能完成读书写作的计划。\u003c/p>\u003cp>3、想障碍：我分析出了两个障碍：第一个障碍：因头天晚上熬夜导致早晨起晚了，耽误了锻炼的时间；第二个障碍：懒了，不想起。\u003c/p>\u003cp>4、定计划：针对障碍1：起晚了也要锻炼，哪怕只跑10分钟的步，也不能放弃，养成每天锻炼的习惯。同时，尽量避免熬夜，11点之前睡觉。\u003c/p>\u003cp> 针对障碍2：想想自己生病时受的苦，想想头脑昏沉读不进书写不出东西的难受劲，还是起床吧\u003c/p>\u003cp> 【结束语】 好，今天的拆页学习就到此结束，希望这个方法可以给大家带来启发。\u003c/p>\u003cp> 我是煦涵，感谢各位的聆听，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1621496157000,"updated_at":1621586818000,"ria":true},{"id":11315,"topic":"用WOOP让美梦成真","learn_goal":"","remark":"用WOOP让美梦成真","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"小妖灵灵","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>\u003cstrong>环节1：开场（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>嗨，大家好，我是小妖灵灵，是拆书帮贵阳第二筹备分舵的教育长老。\u003c/p>\u003cp>在开始今天的拆书活动分享之前，为了营造更好的学习氛围，所以我希望今天到场的小伙伴先进行分组。今天到场的有6个人，我们分成2组，每组3个人。\u003c/p>\u003cp>那现在从我右手边开始，依次报数，报单数的伙伴到我的右手边，为第一组；报双数的伙伴在我左手边，为第二组。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>分组完成，请大家就座。今天我分享的片段来自于《WOOP思维心理学》，本书的作者是一位著名的心理学家 加布里埃尔·厄廷根 博士。她通过大量的心理学实验惊讶地发现：在某些情况下，乐观是有害的。\u003c/p>\u003cp>举个例子，你有没有立过flag？比如减肥、健身、戒烟。这些计划最后实现了吗？我猜大多数人都是以失败告终。\u003c/p>\u003cp>为什么会这样呢？作者在书中告诉我们：对于需要行动的事情，乐观幻想就像是精神鸦片，让人沉浸在盲目乐观所带来的愉悦假象之中，从而消耗了自己的干劲，使自己无法全力以赴实现目标。\u003c/p>\u003cp>毕竟想不等于做，只有付出行动，我们才能实现目标。那究竟要怎么行动呢？有什么方法可循吗？答案当然有，就是作者提出的WOOP思维。\u003c/p>","ratings_count":1,"texts":[{"id":15240,"quote":"\u003cp>\u003cstrong>环节2：R阅读原文（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在大家手里的拆页选自这本书的第165页到166页，它详细地介绍了WOOP思维的具体4个行动步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆页内容略微有点长，这里我讲给大家2分钟时间阅读。大家读的时候可以在产生思想碰撞的地方划线、做关键词备注等等记录。4个步骤中，可以重点关注第二个O的内容。\u003c/strong>\u003c/p>\u003cp>W：愿望或心事。放松，深呼吸，想一个私人或工作方面的愿望或牵挂，虽然有些棘手但你觉得能够达成。它可以是你打算在当天 、本周、本月、本年之内要达成的，只要是你想要woop的愿望都可以。如果同一时间段内有好几个愿望，那就选一个对你而言最重要的，然后把件事放在思考的中心。\u003c/p>\u003cp>O： 结果。你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。任思绪驰聘，不要有顾虑。不要着急，慢慢来，要是喜欢的活，可以闭上眼睛。\u003c/p>\u003cp>做好准备之后，挣开眼晴，进入下一个步骤：\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？是不是某种习惯或先入为主的想法？在思索障碍的时候，人们往往会在外部寻找， 把&quot;罪名“扣在他们自认为妨碍了他们的外部条件或人的头上。但是，通过选取一个我们认为可以达成的愿望这种做法，就把外部障碍考虑在内了 （要是外部障碍过大，我们就不会认为此愿望是&quot;可以达成“ 的了） 这一练习的目的是防止我们在追逐梦想的路上自己绊倒自己。\u003c/p>\u003cp>在筛选障碍的时候，有一点很重要，那就是深挖细剖，找到那个对你来说最关键的障碍。根据情况的不同，这个障碍可能是很具体的，如&quot;玩了太长时间电脑&quot;；也可能是很普遍的，如&quot;累&quot;或 者&quot;紧张&quot;；可以是某种行力，某种情绪，某种观念，某种冲动， 某个恶习，某种猜测；也可以是某种愚蠢而无用的作为。有时候， 你需要动脑和耐心才能找到真正的内部障碍，发现自己的行为或反应是毫无建树的。刚开始的时候，可能很难把这一过程坚持下去， 因为人们都不愿真诚地剖析自己；但若是能找到最关键的障碍，就一定会有回报。这件事并不像看上去那么难，并且，很多人都觉得， 在完成这个步骤之后他们会产生满足感，甚至觉得如释重负。有时候，在此过程中你还会发现一些自己从未想过或此前无法理解的东西。 在找出了障碍之后，你就获得了德国人所说的Durchblick，在这里指的是对你的愿望、心事，或生活中的某个方面有了一个新的、更清晰的鸟瞰。把这个障碍放在思考的中心，然后用心思考，尽量生动形象的对其相关情况和经历展开想象。让思想自由驰聘，不要有顾虑，不要拘束思路。如果喜欢的话，可以闭上眼睛。\u003c/p>\u003cp>完成上面的步骤之后，就可以进入第四个步骤了：\u003c/p>\u003cp>P：计划。要克服或规避这个障碍的话，你能怎么做?想一个—最有效的那个——想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制订一个&quot;如果……那么…”计划：&quot;如果障碍X出现了 （何时何地），那么我就采取行动Y。”然后将这个计划重复一遍给自己听\u003c/p>\u003cp>就这样。完成。是不是很简单？这种练习你想隔多长时间做一次都可以，只要能有个身心清净的地方就行，你可以坐在火车上、飞机上闭上眼睛坐woop。在等待同事而感到无聊时也可以做，早晨醒来，晚上睡前也行，把woop养成习惯，当然压力大的时候在解决棘手而解决办法尚不明朗的时候，也要用它。\u003c/p>","explains":"\u003cp>\u003cstrong>环节3：I拆书家讲解引导（5分钟）\u003c/strong>\u003c/p>\u003cp>好了，时间到。阅读完上面的片段，我想大家应该对WOOP思维的4个步骤有了初步认识。这里我再讲解下这4个步骤，也希望大家能跟着我的引导，思考下如果是你会怎么操练WOOP。\u003c/p>\u003cp>\u003cstrong>第1步，确定你的愿望或目标。\u003c/strong>这个目标可以是短期内就能实现的，也可以是需要长期坚持才能实现的。如果目标非常多，建议你选择时间比较短且对你重要的那个愿望作为练习目标。\u003c/p>\u003cp>\u003cstrong>第2步，做最好的打算，幻想美梦成真的状态。\u003c/strong>这句话再说接地气一些就是——尽情地去做你的白日梦吧，幻想你实现这个愿望的场景，越具体越好。\u003c/p>\u003cp>\u003cstrong>第3步，做最坏的打算，找出美梦成真的绊脚石。\u003c/strong>任何事情的发展都不可能是一帆风顺的，好比是在海上远行，出发前，你会充分考虑各种各样的天气状况吗？这一步要你把自己拉回现实，思考在这过程中可能面临的阻碍。\u003c/p>\u003cp>\u003cstrong>第4步，设计应对措施，制定一个“【如果】障碍出现，【那么】我就采取什么行动去克服它或避免它”的计划。\u003c/strong>这个过程有点儿像做风险控制的过程。\u003c/p>\u003cp>以上就是WOOP的4个步骤，是不是很简单？这个练习你可以在任何时间和地点做。下面我举一个我自己应用WOOP的例子：\u003c/p>\u003cp>【\u003cstrong>第1步，确定你的愿望或目标\u003c/strong>】我的目标是“挑战1个月完成拆书家三级升级任务”。\u003c/p>\u003cp>【\u003cstrong>第2步，做最好的打算\u003c/strong>】我做的白日梦是这样子的：1个月后，我真的成为了三级拆书家，获得了我从2017年开始就梦寐以求的身份。我会把我这个月的拆书经历总结出来，分享给分舵的其他拆书家，一方面为大家排雷排坑，一方面激励大家升级。在大家的努力下，分舵终于达到转正条件，成为了贵州省第一个拆书帮分舵。我们开始对外传播拆书法、招募新的志同道合的小伙伴加入分舵，随着人员的不断扩充，我们开始构建以贵阳市为中心，辐射其他地级市的分舵筹备，拆书帮在贵州的影响力越来越大。\u003c/p>\u003cp>【\u003cstrong>第3步，做最坏的打算\u003c/strong>】当我冷静下来，我预测我可能会遇到这些“麻烦”：\u003c/p>\u003cul>\u003cli>首先，贵州没有1位拆书家，更没有正式分舵。这意味着我想1个月成为三级拆书家，必须要亲自摸着石头过河，一路上难免会出现走错路、走偏路等情况。\u003c/li>\u003cli>其次，拆书家的升级之路需要线下参与。这意味着即使我与师父确定好升级材料，也可能因为人数不足，无法开展线下升级实录，导致升级延期。\u003c/li>\u003cli>最后，我的时间和精力可能不够。因为我5月份有两场考试需要准备，加之平时的工作生活安排，1个月完成至少9场升级需要花费很多时间和精力准备，这对我的自控力、专注力、时间管理能力是场极大挑战。\u003c/li>\u003c/ul>\u003cp>【\u003cstrong>第4步，设计应对措施】\u003c/strong>针对上面的阻碍，我的计划是这样子的：\u003c/p>\u003cul>\u003cli>【如果】遇到不明白的升级任务，【那么】我就要多和自己的师父沟通。沟通中不能不懂装懂，要刨根问底地直到自己弄明白才罢休。\u003c/li>\u003cli>【如果】线下升级人数不足，【那么】我可以一方面多和舵长、组织长老沟通，固定安排升级时间，折中选择升级地点；另一方面也多在群中给拆书家们“打鸡血”，主动询问大家遇到的困难，尝试以此提升大家升级的积极性。\u003c/li>\u003cli>【如果】我的时间和精力不足，【那么】我需要重新确定事情的先后顺序及重要程度，以时间管理四象限法则将部分任务分配给其他人完成，减少娱乐时间。\u003c/li>\u003c/ul>","interaction":"\u003cp>\u003cstrong>环节4：A1激活学习者经验（5分钟）\u003c/strong>\u003c/p>\u003cp>经过我上面的拆解，相信大家已经能够明白WOOP究竟怎样运用到自己的愿望或目标中。\u003c/p>\u003cp>那么，现在请大家回想一下自己曾经制定目标的时候，当时的你是怎么做的？是脑袋中想到一个目标就马上行动？还是会制定一个行动计划再去做？制定行动计划的时候，你有考虑过WOOP中的第三步和第四步吗？最后，你的那个目标实现了吗？\u003cstrong>带着这些问题，我给大家每人30秒的时间在组内讨论，一共是1分半钟。\u003c/strong>\u003c/p>\u003cp>好啦，时间到。现在有请一位伙伴分享下自己曾经的相关经历，时间为1分钟。\u003c/p>\u003cp>\u003cstrong>【A1学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴【阿志】分享：\u003c/strong>\u003c/p>\u003cp>一年前，我一直想要练字，但由于自己太懒，始终没有练习。刚才学习了WOOP后，我突然意识到，关于练字这个目标，我从未认真思考过自己可能遇到什么阻碍。\u003c/p>\u003cp>现在我想，除了懒，还有很多工作上的突发事件会耽搁我练字的习惯养成。找到障碍后，我相应的计划是运用刚才另一位伙伴的分享内容，运用时间、地点、地方去刻意养成自己的练字习惯。\u003c/p>\u003cp>——————————————————————————————————\u003cbr>\u003c/p>\u003cp>\u003cstrong>环节5：A2催化学习者应用（1分钟）\u003c/strong>\u003c/p>\u003cp>感谢小伙伴的精彩分享（鼓掌）。\u003c/p>\u003cp>如果曾经的目标没有实现，不要气馁，我们现在有WOOP。如果曾经的目标已经实现，不妨再用WOOP实现下一个目标。（边说边发WOOP卡）\u003c/p>\u003cp>现在大家手里拿到的就是WOOP卡片，请确定一个你的愿望或目标，用前面所学的方法将卡片填写完整。\u003c/p>\u003cp>这里我特别说明一下，因为大家初次练习，我建议先制定一个短期的目标试试看。比如：看看自己要花多少个月升级到二级呀？升级过程中你会遇到什么困难呀？有困难你要怎么应对呢？\u003c/p>\u003cp>【总结】好啦，以上就是今天的全部内容，感谢大家的倾听，祝你在实现梦想的道路上，越走越顺。大家的内容写完后，我会统一来收集哒~谢谢~\u003c/p>\u003cp>\u003cstrong>【A2学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴【十八朵】应用：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴【孙英楠】应用：\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1618125769000,"updated_at":1618159567000,"ria":true},{"id":10666,"topic":"WOOP思维方法","learn_goal":"","remark":"转眼间2020年已到尾声，也许你正在某些重大问题上苦苦挣扎，也许你只是想发掘、利用潜在的可能或机遇，无论你是心怀一个梦想，还是面临一个困境，WOOP这个基于20多年实证研究的思维方法，都能加深你对内心动力的理解，帮助你理清前进的方向，让你开始真正地改变。一起来体验WOOP的神奇吧。","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"付盈盈","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>各位小伙伴儿大家好，我是今天的拆书家付盈盈。\u003c/p>\u003cp>那今天，我要跟大家分享的这个主题呢，听起来话题有点空，是关于如何实现自己的心愿的，但是《WOOP思维心理学》这本书把怎么实现自己的愿望这件事变得非常地科学，非常地落地，具体是什么呢，我们等一下一起来看看。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>开始之前，先跟大家分享一下我自己的一件小事儿。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>前几天断舍离，整理我的卡包，发现我去年办的游泳卡已经过期了，我好惆怅：卡都过期了，我还没有学会游泳！我记得当时请教练的时候，我是满怀信心的：1个月学会游泳。刷卡的时候仿佛已经看到了自己在泳池上下翻飞，那个自由舒展真的是惬意。结果呢，夏天嫌泳池人太多，冬天窝在家里不想出门，总之，一年都过去了，我还没学会换气。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>你们有没有这样的情况，立FLAG的时候好嗨哦，什么1个月瘦10斤啦，一周读完5本书啦，结果呢，刚开始斗志昂扬，遇到一点阻力马上就缩回去了。有这种情况吗？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>定的目标总是完不成，会给我们带来无力感，让我们对自己的能力产生怀疑，这种挫败感不仅影响这个目标，也会波及到我们其他的目标。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那怎么办呢？WOOP思维可以帮到你，它能够帮你识别可实现的目标心愿，无论你是想要更健康的身体、想要更和谐的人际关系，又或者是想在工作中表现更好，WOOP思维都能够帮助你变得目标明确、动力十足，马上开始行动。\u003c/p>","ratings_count":1,"texts":[{"id":14532,"quote":"\u003cp>【拆页1】\u003c/p>\u003cp>20世纪90年代，当我的研究初次证实乐观的幻想无助于实现梦想的时候，我很失望。我之所以要研究人的幻想，并非仅仅出于兴趣而是希望幻想能给那些在实现大大小小的梦想时遇到困难的人以帮助。它若是不会给人们带来改观，那我的研究就没有意义了；所以我开始考虑，是否能在幻想的过程中干预一下，进而扭转局势，使幻想变得有益于实现梦想呢？尤其要指出的是，既然乐观的幻想会令人放松、松弛下来，我是不是能找到一个办法，利用幻想将人“唤醒”。给他们动力促其成功？\u003c/p>\u003cp>我认为，让人行动起来的最好的办法就是让他们心怀梦想，然后立刻将阻碍梦想实现的现实放在他们面前。我将二者的对峙称作“心理比对”。通过“心理比对”，我可以将幻想放在现实的基础之上避开其令人松懈的副作用，将其作为一个工具，唤起人行动的动力。\u003c/p>","explains":"\u003cp>【量表自测】\u003c/p>\u003cp>在正式开始分享之前，我们先花1分钟的时间来做个小测试，来评估自己在实现目标方面的现状。1分是完全不符合，6分是完全符合。大家凭第一感觉打分，不用深度思考。做完的小伙伴示意我一下。\u003c/p>\u003cp> 【学习者测试结果】16、19、22。大家的得分总体比较好。\u003c/p>\u003cp>这个测试是帮助我们看到，我们的目标或者说愿望实现的程度。如果你的分数高于20分，说明你通常能够对影响你目标实现的障碍有觉察，并且制定相应的计划来化解。那一起来看看今天的内容会不会给你一些新的启发，也欢迎你在后面的环节多多分享经验;如果分数在11-20分之间，说明我们在障碍预估或者计划执行方面有改进的空间；如果分数低于10分……呃，那可能就是我们制定目标、实现目标的能力非常地欠缺，不过咱们今天没有这样的伙伴儿，咱们拆书帮的伙伴们非常地优秀。\u003c/p>\u003cp>当然这个只是简易的测试，分数可能比较主观，仅供粗略的自评参考。\u003c/p>\u003cp>接下来我们来学习拆页1，给大家1分钟的时间来阅读一下原文拆页，看完之后示意我一下。P79\u003c/p>\u003cp>\u003cstrong>I促进引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>好，我看到大家都已经看完了拆页，这个拆页中提到了一个新概念叫“心理比对”，那什么是“心理比对”呀？其实在原文中作者已经有提到了。通俗来讲就是先去想愿望实现后的美好场景，然后马上去找到阻碍目标实现的障碍，这两者之间的对峙，就是“心理比对”。\u003c/p>\u003cp>\u003cstrong>【学习目标1】\u003c/strong>\u003c/p>\u003cp>希望通过这个拆页的学习，我们能够运用（行为）心理比对的3步骤（澄清）来制定出你真正想要的目标，强化实现目标的动机，对未来可能遇到的障碍进行预估（界定）。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>其实从刚刚的概念，我们也能大概知道它的运用步骤。先列愿望，再想象结果，最后找出障碍，对吧？那我们现在来对它进行一个细化。\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong> \u003cstrong>列出愿望。\u003c/strong>白日梦类型的，首先要排除掉了，可以想，但是不需要用到woop工具，咱自己随意想一想就行。那我们怎么判断是不是白日梦呢？（停顿，给学习者思考和回应的时间）我觉得有一个很重要的判断标准就是\u003cstrong>：达成愿望的条件是你可控吗？\u003c/strong>\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>l 比如我的心愿是老家的房子拆迁，这个是我可控的还是不可控的？\u003c/p>\u003cp>学习者：不可控\u003c/p>\u003cp>拆书家：对，完全依赖外部环境，属于靠天吃饭，不需要用到这个工具。\u003c/p>\u003cp>l 比如我想学会游泳，这个是我可控的，还是不可控的？\u003c/p>\u003cp>学习者：可控\u003c/p>\u003cp>拆书家：是的，如果需要更多的时间、更多的努力、新的策略、寻求专家的帮助、更强的自制力、更好的规划。那么你可以试试，继续下面的步骤。\u003c/p>\u003cp>\u003cstrong>2、想象结果。想象愿望实现后的美好画面，感受美好的同时，问问自己：这个结果对我而言重要吗？\u003c/strong>\u003c/p>\u003cp>当然了，既然我们把它当成是一个目标，想到它的实现，我们都是会觉得很开心的。但它的实现对你的生活究竟有多大的影响呢，我们可以想象一下，按1-10分，1分最低，10分最高作为评价依据，你对自己当前的整体生活满意度打几分？上述目标实现后，你对生活的满意度又是几分？提升的这个分值，相对于你要投入的时间和精力成本，你觉得是否值得呢？经过这样的追问，可能会再筛掉一部分不重要的“假心愿”。\u003c/p>\u003cp>\u003cstrong>3、找出障碍。结合过往经验，找到妨碍我们达成愿望的关键的障碍是什么？\u003c/strong> \u003c/p>\u003cp>在想象美好结果之后，加入障碍，在大脑中预演未来很可能会遇到的困难，提前做好准备。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>为什么我们要做心理比对呢？\u003c/p>\u003cp>心理比对可以很好地解决我们动力不足的情况，因为它每一步都在筛选，也就相当于是每一步都在强化你的动机。同时，它对未来的障碍有一个预估，这个预估一方面让我们的目标更客观，另一方面，在真的遇到障碍的时候，也不会打我们一个措手不及，因此大大降低我们一遇到障碍就放弃的可能性。\u003c/p>\u003cp>【举例】比如我最近想瘦身，希望自己两个月从105斤降到100斤以下。\u003c/p>\u003cp>第一步，列出愿望。2个月瘦身5斤。这是我可控的，只要我坚持锻炼，健康饮食，是有可能实现的。继续下一步。\u003c/p>\u003cp>第二步，想象结果。想象了自己瘦身成功，衣柜里的T恤衫牛仔裤随便往身上套就很有型，而且锻炼会让我整个人变轻盈。哎呀，想想就很开心。那么，它对我而言重要吗？现在我对生活的整体满意度是7分，瘦身5斤以后，我的整体满意度大概是7.5分吧，分值好像提升的不多，但是相对于我要投入的时间精力而言，每天只需要花20分钟，还是很值得的。\u003c/p>\u003cp>第三步，找出障碍。障碍是我热别喜欢吃碳水，而且习惯晚上吃很多。还有，我不能饿，一饿就不受控制，感觉不幸福，很容易对我女儿发火。所以呢，晚上我可以少吃或不吃碳水，但是可以吃大量蔬菜和一些低脂的肉类，然后早点睡，就不会觉得饿了。\u003c/p>\u003cp>所以，综合来看，用心理比对的3步骤捋一遍之后，我对于这个目标的实现还是很有信心的。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>心理比对这种方法，主要适用于个人的愿望或者目标。如果是工作上需要协同的目标，可能就不太适合，或者是你只能拆分出自己的那一部分来做心理比对。\u003c/p>","interaction":"\u003cp>【小剧场】\u003c/p>\u003cp>刚刚我们一起学习了用心理比对来确定目标的3步骤。如果我们能编个剧本，在大脑中把这个方法演练一遍，就相当于应用了一遍，以后你遇到类似的场景应用的可能性就会大增。\u003c/p>\u003cp>所以，现在请大家编一段剧本，剧本中至少有2个人物，要有情节变化（包括：起因、经过、结果）和当时双方的对话等，其中，剧本的场景，要适合讨论一个如何实现心愿的话题，比如餐桌上和家人讨论你这个月想完成的目标心愿。另外，对话部分要用到心理比对的3步骤。 \u003c/p>\u003cp>给大家5分钟时间，来构思并写下你的剧本。如果大家写完了，可以举手示意我一下。\u003c/p>\u003cp>拆书家：好的，给自己掌声鼓励一下吧，两个人还挺入戏的，我在刚刚的剧本中有听到大家说出愿望，然后想想了一下我们减肥成功这个结果，最后也把障碍找出来。在第二步想象结果的时候，我们刚刚有提到，就是我们怎样去衡量这个东西是不是我们真正想要的呢？我们可以对它进行评分，去评估这个重要性，对吧？为什么说我们是用更科学的方法去执行目标呢，就是体现在一些细节的地方。总之，大家的演练非常好，感谢两位小伙伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":14533,"quote":"\u003cp>【拆页2】\u003c/p>\u003cp>彼得和他的同事维罗妮卡·布兰德斯坦特（ Veronika Brandstatter）发现，一旦下定决心去实现某个目标，为了实现此目标而制订明确的计划将有助于采取行动、克服障碍。在一次以大学生为测试对象的研究中，他们给被测试者布置了一个棘手的任务：圣诞夜过后两天提交一份假期情况的报告。他们要求其中一半学生详细说出自己将在何时何地以何种方式写报告（亦即做出明确的计划而另一半学生则没有这个要求。结果，在将时间地点方式制定了明确计划的被测试者中，有71%的人给研究人员寄回了报告，而没有明确计划的被测试者里，只有32%寄回了报告。“制订计划”这个简简单单的行为，在此过程中充当了自我调控工具。在帮助达成目标这件事上扮演了重要的角色。\u003c/p>\u003cp>随着时间的推移，彼得做了更多试验，并最终意识到：只要满足一个条件，那么，针对如何实现某个目标而制订计划—亦即他所说的“执行意图“的效果将会大大提高；而这个先决条件就是：制订的计划必须是“如果……那么……的形式，即“如果出现了情况X，那么我就做出Y反应”。比如上面的例子，假设吉妈在地区经理到他办公室来的时候感到莫名其妙的紧张，连寒暄、问询都不会了。这种情况下，吉姆的“执行意图”就可以是：“如果我在跟地区经理谈话时感到紧张，那么我就提醒自己——我是公司里在这一地区最好的推销员，我的销售业绩从去年就一直在提高。”或者是：“如果我在跟地区经理交谈的时候感到紧张，那么我就先找个借口离开片刻，深呼吸，静下心来，再回去跟他继续交谈。”\u003c/p>","explains":"\u003cp>【过渡】第一个拆页将未来与障碍联系起来，在愿望行得通的时候，让它快马加鞭，在愿望行不通时，就让它早点抽身而退。理论上来讲，列出了障碍，我们自然就有了行动，也就离目标更近，那怎样才是有效的行动呢？我们来学习下一个拆页。\u003c/p>\u003cp>【学习目标2】通过这个拆页的学习，我们在围绕障碍制定计划时，能够运用（行动）执行意图的4个步骤（澄清），制定出“如果出现情况X，那么我就采取行动Y”这样的行动指令（界定）。\u003c/p>\u003cp>接下来给大家2分钟的时间来阅读拆页二，看完之后示意我一下。\u003c/p>\u003cp>\u003cstrong>I 促进引导\u003c/strong>\u003c/p>\u003cp>前面我们已经知道了要想实现目标，我们需要对未来的障碍有一个预估，光有预估是不够的，还需要针对障碍采取有效的行动。那么如何采取有效的行动呢？拆页2给我们提供了一个方法，也就是原文中所提到的“执行意图”。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>执行意图就是“如果出现了情况X，那么我就做出Y反应”模式。看起来也非常简单，那为什么我们说这种模式有助于我们采取有效的行动呢？\u003c/p>\u003cp>【why】\u003c/p>\u003cp>日常生活中我们改变一个行为习惯或者思维习惯很难，是因为我们总是期望通过自己的意志力去改变，但意志力是个反人性的事情，需要耗用我们很多能量才能够做到，早上看到面包忍住了，意志力血槽空了三分之一，中午看到红烧肉忍住了，意志力血槽见底了，那晚上看到小龙虾你还忍得住吗？所以，如果做什么事情都需要通过意志力去控制和执行，那我们的能量就会很快消耗殆尽，行动力也会随之迅速下降。\u003c/p>\u003cp>而执行意图，相当于在我们的脑中将遇到的障碍预演了一遍，并且提前设置了一条精准的指令。让我们在潜意识能迅速作出“兵来将挡，水来土掩”的反应，根本无需动用意志力来执行，执行的难度就大大降低了。\u003c/p>\u003cp>【概念辨析】\u003c/p>\u003cp>执行意图很有效，但是并不是形式上写成“如果……那么……”就到位了，内核也要到位，我们先来听几个例子感受一下。\u003c/p>\u003cp>比如，影响我想每周输出一篇文章。这个目标的障碍是我不断拖延，完全没办法开始写。那么我制定了如下“执行意图”：\u003c/p>\u003cp>\u003cstrong>例1：\u003c/strong>如果：我周六晚上8点在家，那么：我到书房写作1小时。\u003c/p>\u003cp>这是一个有效的执行意图吗？\u003c/p>\u003cp>（有同学说是，有同学说不是。）\u003c/p>\u003cp>那我再说一个大家对比一下：\u003cstrong>例2\u003c/strong>：如果我听到了周六晚上8点的闹钟，那么我写作1小时。\u003c/p>\u003cp>体会到区别了吗？\u003c/p>\u003cp>对，虽然都是周六晚上8点，但是后面这个例子增加了一个可以觉察到的启动开关。如果没有这个闹钟，虽然定了计划，到时间了你很可能根本没意识到需要启动这个执行意图了。\u003c/p>\u003cp>\u003cstrong>所以，执行意图第一个特点是：X要可感知。\u003c/strong>只有能够感知，才能够触发，要不然这个指令就一直在沉睡中。\u003c/p>\u003cp>\u003cstrong>例3：\u003c/strong>如果：我下周不下雨，那么：我至少晨跑3天。\u003c/p>\u003cp>这是一个有效的执行意图吗？\u003c/p>\u003cp>X是可以感知的，但是Y是不是一定可以执行呢？大家想一想。（停顿）\u003c/p>\u003cp>\u003cstrong>例4：\u003c/strong>如果：我下周不下雨，那么：我一三五起床后跑步半小时。\u003c/p>\u003cp>\u003cstrong>所以，执行意图的第二个特点是：Y要是一个“可执行”的行动，而不是需要继续分解的计划。\u003c/strong>\u003c/p>\u003cp>【how】\u003c/p>\u003cp>现在我们知道有效的“执行意图”需要X可感知，Y可执行，那怎样写出执行意图呢？\u003c/p>\u003cp>不管执行意图有什么样的特点和作用，本质上它就是一个解决方案，所以要写出有效的执行意图，我们还是要围绕着障碍行为、障碍场景，找到解决方案，然后再把它写成执行意图的标准格式。\u003c/p>\u003cp>\u003cstrong>第一步，描述障碍场景、障碍行为。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步，思考如何化解障碍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步，将第二步的解决方案，写成X可感知，Y可执行的“如果……那么……”形式。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四步，张贴在合适的地方，提醒自己。\u003c/strong>\u003c/p>\u003cp>【举例】比如，我想写完一个方案，最大的障碍就是我不停地玩手机。\u003c/p>\u003cp>第一步，这个障碍出现的场景就是我写着写着，一卡壳，就拿起手机开始玩儿。\u003c/p>\u003cp>第二步，要解决这个障碍，我可以让手机不要出现在我的手边。\u003c/p>\u003cp>第三步，写成执行意图就是“如果我准备去书房工作，那么先把手机放在主卧抽屉里。”\u003c/p>\u003cp>第四步，贴在我的书房门口。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>从上面的例子以及原文的例子可以看出，执行意图不仅仅可以帮助我们达成目标，还可以非常广泛地用于改变我们的行为习惯或者思维习惯。它和心理比对一样，是适用于我们个体的自我管理工具，在我们制定团队目标，团队计划的时候，就不太适用了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【微行动学习】\u003c/strong>\u003c/p>\u003cp>OK，刚刚我们一起探讨了执行意图的特征以及如何制定执行意图，那现在我们来运用微行动学习的方法，发挥大家的智慧，深入地探讨大家还有疑虑的地方。\u003c/p>\u003cp>1、明确问题。通过重述并确认，让每位学习者都非常清楚接下来要聚焦讨论的问题。\u003c/p>\u003cp>拆书家：关于刚刚我们一起学习的执行意图，在运用的时候，我们会遇到什么困难呢？大家可以结合一个具体的案例来说明。\u003c/p>\u003cp>学习者1：可能他自己都不知道障碍是什么。\u003c/p>\u003cp>拆书家：我们可以举一个具体的例子来说明，这样更清晰。\u003c/p>\u003cp>学习者2：就拿我刚刚减肥的例子来说，我写了执行意图，但是坚持不下来，比如我计划每天晚上八点钟跳尊巴。\u003c/p>\u003cp>学习者3：坚持一次两次还行，长久下来就比较困难。\u003c/p>\u003cp>学习者2：对，就是难以坚持。\u003c/p>\u003cp>学习者1：在其他事情上也会这样，比如我说要开12次拆书课，刚开始一次两次可以，有激情在，但是后面哎呀不行，这个星期有这个事，下个星期有那个事。也会存在这样的问题。\u003c/p>\u003cp>拆书家:就是我们的计划确实已经很明确，很具体了，但是可能还是没办法坚持。\u003c/p>\u003cp>学习者：嗯，坚持是一个很难的事情。\u003c/p>\u003cp>拆书家明确问题：好的，大家已经共识了我们在应用的时候会遇到的困难：有时候我们做了执行意图，但是坚持还是一件很难的事情。对吧？\u003c/p>\u003cp>学习者：是的。\u003c/p>\u003cp>2、引导分组讨论问题本质。拆书家要提醒大家结合自己的经验。对较为复杂的问题，可以鼓励学习者相互深入追问。\u003c/p>\u003cp>那接下来，我们以减肥为例，我们大家一起讨论一下，为什么会出现不能坚持这种情况，出现这种情况的本质原因是什么？\u003c/p>\u003cp>今天我们人比较少，大家就作为一个大组。\u003c/p>\u003cp>这里大家可以用到5WHY的方法，反复去追问为什么，知道我们挖出一个问题，大家都觉得今天我们只要把这个问题解决了，那么我们不能坚持这件事就可以迎刃而解了。\u003c/p>\u003cp>3、明确问题本质。\u003c/p>\u003cp>讨论结果：不能坚持的本质原因是不相信自己能做到。\u003c/p>\u003cp>拆书家：我们觉得只要解决了“我们相信自己能做到”这个信念，我们就可以做到坚持了，是这样吗？\u003c/p>\u003cp>学习者：对。\u003c/p>\u003cp>4、引导分组讨论解决方案。要求大家把解决方案写在白板上（这里可以再分为两步：先讨论出解决目标是什么，即这个问题解决到什么样子就算满意了。再讨论如何行动就能达到这个目标）\u003c/p>\u003cp>好，那接下来我们就讨论怎样让自己有“我能做到”的信念。给大家5分钟的时间，先发散思维，最后我们再梳理一下大概是从哪几个方向去解决。\u003c/p>\u003cp>5、请每组派代表讲解自己组的成果。\u003c/p>\u003cp>【学习者展示成果】\u003c/p>\u003cp>我们可以从两方面去做：\u003c/p>\u003cp>一是外力，加入小团体；外力监督打卡。\u003c/p>\u003cp>二是对内，找标杆，增加信心；用记录表、成就清单视觉化；加入奖惩；固定的时间做固定的事情，用到我们刚刚学到的执行意图。\u003c/p>\u003cp>拆书家：好的，很完美，刚刚我们一起用执行意图解决了一个实际问题。并且我们解决不能坚持锻炼的方法，也推广到其他的很多方面。当我们没有办法坚持的时候，怎么去做呢？大家分成了对内和对外这两个角度，列了很多方法。并且我看到大家好像把这个讲完之后，都感觉很好是吗？（是的）觉得可以坚持了。这也说明达到了我们今天的学习目标。很好！\u003c/p>\u003cp>\u003cstrong>A2催化应用\u003c/strong>\u003c/p>\u003cp>【布置任务\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>刚刚我们一起用执行意图来解决实际问题。执行意图真的是一个非常好用的工具，我们不仅可以拆为己用，也可以释放更多的能量，分享给自己的家人和朋友。请大家在两天内，跟周围的人分享一下用执行意图来制定计划的4步骤。你想分享给谁呢？打算什么时候，在哪里跟TA分享呢？你大概会分享哪些内容呢？请把你的分享计划写在便签上。给大家1分钟的时间，然后我请1位小伙伴来展示下。\u003c/p>\u003cp>【学习者1分享】\u003c/p>\u003cp>时间： 明天晚饭时间 地点：家里 分享对象：老公\u003c/p>\u003cp>分享内容：我准备减肥了，每天晚上八点钟要跳尊巴，请他配合监督我。\u003c/p>\u003cp>拆书家：你这个分享的是自己的一个计划，那我们这个任务的目的是不仅仅我们自己能用，还可以释放拆书家的能量，教会别人来用。\u003c/p>\u003cp>【学习者2分享】\u003c/p>\u003cp>时间： 明天晚上 地点：线上直播平台 分享对象：拆书家、PET学员\u003c/p>\u003cp>分享内容：我原本是计划分享彭小六的例子。那我想再分享例子之后，我想把今天的内容也分享给他们，包括拆页一心理比对的步骤，愿望实现的场景，找到障碍；还有拆页二这个步骤，找到障碍制定计划；当然我们今天讨论的结果也可以分享给他们。\u003c/p>\u003cp>拆书家：好的，特别好，感觉还是可以帮到很多人的，就很有成就感。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>今天我们学习了WOOP思维的两大内核：心理比对以及执行意图，知道如何筛选出我们真正想要的目标，强化动机后用执行意图的方法去实现它。最后，对大家进行一个灵魂的拷问：你最大的愿望是什么？妨碍你实现愿望的又是什么？ \u003c/p>\u003cp>OK，以上就是我要拆解的全部内容，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1606062322000,"updated_at":1606727228000,"ria":true},{"id":10349,"topic":" 【学习主题】   四步实现心中所愿","learn_goal":"","remark":"【学习目标】   学会使用woop四步法提升行动动力、制定执行意图，从而真正实现梦想。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"猫小杜","city":"哈尔滨市"},"club":{"name":"哈尔滨索菲亚分舵","city":"哈尔滨"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是今天的过级者杜晶晶，昵称猫小杜，先用三个标签介绍自己：医生、二胎妈妈、写作爱好者。今天我要拆解的片段选自这本书《woop思维心理学》\u003c/p>\u003cp>【FAB法介绍书籍】\u003c/p>\u003cp>F 《woop思维心理学》是一本关于“愿望”和“实现愿望”的书，作者是著名心理学家加布里埃尔.厄廷根教授。\u003c/p>\u003cp>A 这本书最大的优势在于，颠覆传统积极思维的方式，心想就能事成，它以20年内心动力学研究为基础，提出一种新的思维模式即woop思维法，最大限度地激发人们内心的动力，让目标更加明确，行动更有干劲，\u003c/p>\u003cp>B1 你最大的愿望是什么？减肥、健康、挣大钱、买大房子、拥有好的工作，亲密的恋人……假设这一切梦想成真，该多么美妙。然而现实如何呢？你可能因此过得并不那么快乐，在某些问题上苦苦挣扎。这本书会从心理学角度给出你答案，帮你厘清前进的方向，直面人生。\u003c/p>\u003cp>B2 今天我选择的woop四步法就是这本书最核心的内容，在跟随我完成本次RIA现场学习后，你将能够应用woop法找到并实现那些真正想做和值得做的事情。\u003c/p>\u003cp> 【分组】\u003c/p>\u003cp>在正式开始之前我们先分一下组，接下来给大家一分半的时间阅读手里的拆页。\u003c/p>","ratings_count":1,"texts":[{"id":14194,"quote":"\u003cp>首先要记住：woop跟你以前做过的那些思维练习不一样，它用到的是无拘束的幻想，而非理智或主观控制的想象。在此过程中你需要集中注意力，这样你的思绪才能自由驰骋。下面开始：\u003c/p>\u003cp>W：愿望或心事。深呼吸，想一个私人或工作方面的愿望或牵挂，虽然有些棘手但你觉得能够达成。\u003c/p>\u003cp>O：结果。你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？\u003c/p>\u003cp>P：计划。要克服或规避这个障碍的话，你能怎么做？想一个——最有效的那个——想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制定一个“如果……那么……”计划“如果障碍X出现了（何时何地），那么我就采取行动Y。”然后将这个计划重复一遍给自己听。\u003c/p>","explains":"\u003cp>【Why】\u003c/p>\u003cp>星爷”曾说过：“人如果没有梦想，和咸鱼有什么区别？”\u003c/p>\u003cp>汪峰很喜欢问别人：“你的梦想是什么？”\u003c/p>\u003cp>刘欢的歌里唱的也是“心若在，梦就在。”\u003c/p>\u003cp>但尴尬的是，“梦想很丰满，现实很骨感”。\u003c/p>\u003cp>有个笑话是这样说的：一个幻想了一年都没有中奖的人在埋冤上帝时，上帝无奈地大喊：“你倒是去买张彩票啊！”\u003c/p>\u003cp>很多时候，我们都是想法太多，行动太少，比如我想变得美美的，什么漂亮衣服都能穿，我想挣更多钱，我想脱单，我要每天读一本书……\u003c/p>\u003cp>但运动嫌累、学习犯困、处对象嫌麻烦、读书还常常坚持不下去……\u003c/p>\u003cp>长期如此，人就很容易沮丧抱怨自责，产生自我怀疑甚至否定，不敢也不愿去实现梦想，要么将其封存，要么选择放弃。\u003c/p>\u003cp>我自己的例子就是减肥，我从上大学开始就发出这样的宏愿，最近也依然在减肥，可是十多年过去了，我依然没有突破过两位数字。\u003c/p>\u003cp>那么有没有什么方法可以应对这样的尴尬呢？\u003c/p>\u003cp>【What】\u003c/p>\u003cp>Woop四步法，就是愿望、结果、障碍、计划四个英文单词的首字母，通过这四步，让你好像拿着放大镜在观察自己，不再被那些虚假的幻想所困扰，浪费时间精力，从而全力以赴实现你的心中所愿。\u003c/p>\u003cp>那么如此神奇的woop法具体该怎么做呢？\u003c/p>\u003cp>【How】\u003c/p>\u003cp>第一步，愿望 写出一个你觉得可能达成的愿望，愿望要切实可行，不能不切实际；\u003c/p>\u003cp>第二步，结果 想象愿望达成之后你的样子，时间允许，你可以陶醉幻想1两个小时；\u003c/p>\u003cp>第三步，障碍 思考你愿望实现过程中最关键的障碍是什么？多问自己几个为什么？反复追问自己，到底什么会阻止自己实现愿望，好比推倒多米诺骨牌的第一块，找到这个关键障碍，让梦想实现更有针对性；\u003c/p>\u003cp>第四步，计划，想想自己的障碍什么时候可能出现，用什么办法解决，然后把它组织成“如果……那么……”计划。\u003c/p>\u003cp>【举例】（纠正自己之前提到的反例）：\u003c/p>\u003cp>1.愿望：我想变瘦（两位数）；\u003c/p>\u003cp>2.结果：轻松驾驭各种衣服，闭眼陶醉想象半小时；\u003c/p>\u003cp>3.障碍：\u003c/p>\u003cp>障碍1:我喜欢美食，也不想放弃美食，\u003c/p>\u003cp>追问自己:为什么想减肥还不想放弃美食？\u003c/p>\u003cp>障碍2:因为大多数时候我自我感觉良好，觉得自己不显胖，衣服穿好还显瘦。\u003c/p>\u003cp>继续追问：那我到底要不要减肥？\u003c/p>\u003cp>答案：健康为前提，运动塑形，有节制的享受美食；\u003c/p>\u003cp>继续追问：那运动塑形最大的障碍是什么？\u003c/p>\u003cp>答案：懒得运动\u003c/p>\u003cp>4.计划：针对懒得运动，我的计划是：如果晚上到家不想运动，那么就打开健身环大冒险（一款游戏健身软件）\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>用来检验梦想，帮助人们明确目标，笃定前行\u003c/p>\u003cp> Woop不适用于没有愿望的人。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>请认真回忆，最近一周或者一月是否有过类似的愿望：我要开始健身、我要早起跑步、我要睡前读书、我要过2-1……哪些愿望没有实现？你有没有因此而抱怨、自责甚至自我否定、放弃，请用两分钟时间写在便签上，待会我会请一位小伙伴分享自己的经历。分享的事情要求有时间、地点、人物、起因、经过、结果。\u003c/p>\u003cp>【案例分享】\u003c/p>\u003cp>因为工作原因，我一直想学软件建模，书也买回来了，浏览之后也确定了有用的内容，打算细细研读，但一个多月了，那本书还在办公桌上放着，页数还在原来的位置没变过。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>假设回到过去，对照你刚才写下的没有实现的愿望，思考一下可能的原因是什么？你觉得可能是哪步出了问题？比如幻想不够真实，没有完全陶醉其中，想象成功之后的样子？或者没有找到最核心的障碍，努力用错了方向？\u003c/p>\u003cp>如果按照今天拆页的内容，你可以如何改正？你最想优化或者改进哪一步？给大家5分钟时间小组内讨论，待会会请1位小伙伴分享。\u003c/p>\u003cp>【案例分享】\u003c/p>\u003cp>对照今天的woop四步法来反思，我觉得我学习软件建模，一直没有行动的最大问题是：我一直没有思考自己的关键障碍是什么？\u003c/p>\u003cp>我觉得我的障碍是：我的时间不太够，我白天的话有很多事，容易被打断，打断后，我就不想再继续看书。\u003c/p>\u003cp>针对障碍我的计划是：如果每天五点下班，我要看半小时的书。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>感谢小伙伴的分享， 今天的过级活动就到这里，接下来，请小伙伴们拿出便签纸，我们一起准备写下自己的A2，期待你们行动之后的反馈。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1598597601000,"updated_at":1600099202000,"ria":true},{"id":10302,"topic":"WOOP四步法则","learn_goal":"","remark":"提升行动力，提前识别障碍并制订行动计划，更好的达成愿望和目标","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"yangzhuanfu","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>大家晚上好，非常荣幸今天能有机会和大家一起学习。首先做个简单的自我介绍，我是杨转福，一个终身学习者，坚持不可一日不读书。\u003c/p>\u003cp>今天我给大家带来的是《WOOP思维心理学》这本书里边的一个片段，希望通过本次现场学习达到以下两个学习目标：1）掌握1个提高行动力的方法；2）现场加工1个自己的克服行动困难症的案例。\u003cstrong>（学习目标）\u003c/strong>\u003c/p>\u003cp>下面介绍一下我今天带来的书籍和片段。\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>《WOOP思维心理学》这本书是一本关于“愿望”和“实现愿望”的书，作者加布里埃尔•厄廷根是世界著名心理学家，他以20年的内心动力研究为基础，在本书中向大家阐述一个核心理念：幻想会降低个人行动力，提前设想实现愿望可能遇到的障碍和制订针对性的计划，更有利于我们实现愿望。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>相比于市面上其它同类书籍，这本书是社会心理学图书中非常畅销的一本，豆瓣评论说它是颠覆传统积极心理学的一本著作。本书最大的特点是它提出的所有观点都是经过严格的科学实验论证的，核心的WOOP思维模型操作非常简单，容易上手，每天都可以用。\u003c/p>\u003cp>\u003cstrong>【B】\u003c/strong>如果你对于实现愿望，习惯于积极的憧憬但缺乏行动力，那么读完本书，你会对积极心理学的弊端有新的认识。如果你经常出现行动困难症，如买了几本书，但放在那里一直没有看；想参加拆书活动，但一直没有写逐字稿；想约一个客户聊保险理财规划，但一直没有打电话。那么阅读本片段，可以给你一些启发。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>那么在正式开始前，我们先来分个组。在座的各位，我们以3个人为一个小组，以方便后续的练习。\u003c/p>\u003cp>下面跟随我一起来学习吧。请大家花2分钟的时间阅读我给大家提前准备的原书拆页。\u003c/p>","ratings_count":1,"texts":[{"id":14141,"quote":"\u003cp>\u003cstrong>W：愿望或心事。\u003c/strong>放松，深呼吸，想一个私人或工作方面的愿望或牵挂，虽然有些棘手但你觉得能够达成。它可以是你打算在当天、本周、本月、本年之内要达成的，只要是你想要WOOP的愿望都可以。如果你在同一时间段内有好几个愿望，那就选一个对你而言最重要的。然后把这件事放在思考的中心。\u003c/p>\u003cp>\u003cstrong>O：结果。\u003c/strong>你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。任思绪驰骋，不要有顾虑。不要着急，慢慢来，要是喜欢的话，可以闭上眼睛。\u003c/p>\u003cp>做好准备之后，睁开眼睛，进入下一个步骤：\u003c/p>\u003cp>\u003cstrong>O：障碍。\u003c/strong>有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、\u003cstrong>内心的障碍\u003c/strong>。这个障碍里最关键的想法和行为是什么？是不是某种习惯或先入为主的想法？\u003c/p>\u003cp>\u003cstrong>P：计划。\u003c/strong>要克服或规避这个障碍的话，你能怎么做？想一个——最有效的那个——想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制订一个“如果……那么……”计划：“如果障碍X出现了（何时何地），那么我就采取行动Y。”\u003c/p>\u003cp>然后将这个计划重复一遍给自己听。\u003c/p>","explains":"\u003cp>\u003cstrong>【I：用自己的话重述原文】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>WOOP是愿望、结果、障碍和方法四个词汇的简称，它是一个系统化的实现愿望的方法，可以帮助我们提高行动力，克服行动困难症。\u003c/p>\u003cp>\u003cstrong>【Why Not】\u003c/strong>对于我们内心的一些愿望，我们常见的做法是脑子经常想着这件事，沉浸在实现愿望和目标的喜悦中。最典型的例子，男生找对象，特别想约自己心仪的女生出来约会，每天想啊想，但就是没有行动。这样的幻想，短期可以带给我们满足和希望，但长期并不能让我们行动起来。幻想的频率越高，行动的阻力越大。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>WOOP思维告诉我们在憧憬愿望实现的同时，也要分析我们内心有哪些障碍在阻止我们去实现这些梦想，并制订相应的行动计划来克服内心的障碍。那我们怎么应用WOOP思维呢？\u003c/p>\u003cp>\u003cstrong>1.明确愿望。\u003c/strong>选定一个既有\u003cstrong>挑战性\u003c/strong>，又有\u003cstrong>可行性\u003c/strong>的愿望。这个愿望是你内心真正渴望和对你来说重要的，如每天早起晨读，下了班去健身，每周参加拆书活动等，可以是任何对你来说重要的事。\u003c/p>\u003cp>\u003cstrong>2.确定结果。\u003c/strong>完成这个愿望最好的结果，或者能够发生\u003cstrong>最好的事情\u003c/strong>是什么？找到这个最佳结果。如每周参加拆书活动，最好的结果就是拿到三级拆书家证书。\u003c/p>\u003cp>\u003cstrong>3.找出障碍。\u003c/strong>这是WOOP思维最核心的一步，我们要花费较多的精力，来挖掘出这个内心的障碍。为了实现这个愿望，你内心有什么东西会阻碍你？它可以是一种\u003cstrong>情绪\u003c/strong>，一个并非合理的\u003cstrong>想法\u003c/strong>，或者一个\u003cstrong>坏习惯\u003c/strong>。找到这个\u003cstrong>内心的障碍\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>4.制定“如果-就”计划去克服这个障碍。\u003c/strong>设想这个障碍下次出现的时间、地点，最后写出“如果……那么……”计划，即 “如果障碍X出现了，那么我就采取行动Y”。行动Y应当是自己（希望）可以掌控、采取的行为，而不是臆想。\u003c/p>\u003cp>举个我自己的例子：\u003c/p>\u003cp>我以前多次尝试想养成早起的习惯，都因为各种原因没能坚持下来。\u003c/p>\u003cp>学习了WOOP思维之后，我是这样做的：\u003c/p>\u003cp>第一步，明确愿望。利用早起的时间锻炼学习对我来说特别重要，我给自己制定的一个早起的愿望，归纳起来就是【每天早上6:20前起床】。\u003c/p>\u003cp>第二步，确定结果。完成这个愿望，最好的结果是：\u003cstrong>晨读或晨练1小时。\u003c/strong>\u003c/p>\u003cp>第三步，找出障碍。对我来说，我觉得较大的一个内心障碍，是有时候会\u003cstrong>找借口不早起\u003c/strong>，比下雨了、头天晚上没睡好等，就不想早起。\u003c/p>\u003cp>第四步，制定“如果-就”计划去克服这个障碍。我给自己定的计划是：“如果内心出现找借口不想早起的声音，就马上起床上厕所并洗一个冷水脸”\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>很多小伙伴可能会问，对于第三步找出障碍，为什么要找内心的障碍而不是外部障碍？其实，我们大多数的行动困难症和拖延症，都是我们内心的障碍造成的。当我们找到内在的障碍时，我们就能够更好地控制和克服它们。还有，大多数时候，我们改变外在环境的能力有限，但我们可以改变的是我们应对外在环境的想法、情绪和行为习惯。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>WOOP适用于实现工作和生活方方面面的长短期目标，但不适用于具有重大的内心障碍的目标。对于初学者，可以从实现未来1-2天的愿望开始实践。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2：分步催化】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【确定场景】\u003c/strong>\u003c/p>\u003cp>设想一下，在未来1-2天，你最想达成的一个愿望是什么？这个愿望是你真正想实现的，且具有可行性。如阅读一本你一直想阅读但没读的书，打电话给一个你一直想联系但没联系的朋友，去半年没去的健身房游一次泳，和上司沟通你对于未来工作的想法，或任何其他对你来说重要的事。\u003c/p>\u003cp>找到这个明确的愿望，用三到六个字概括它，在便签上写下关于这个愿望相关的时间、地点、人物等信息，在小组内分享，时间为2分钟。如果你有好几个愿望，选择一个你认为对你最重要的。\u003c/p>\u003cp>学习者A分享：我想到的一个愿望是下周去拆TF2-1。涉及到的时间地点是下周四重庆山城分舵拆书现场。希望最好的结果是拆过2-1。\u003c/p>\u003cp>【应用方法】\u003c/p>\u003cp>好，回到刚刚大家设想的想要达成的愿望，请用到今天学到的WOOP思维：明确愿望-确定结果-找出障碍-制定“如果-就”计划去克服这个障碍，现场加工一个你自己的克服行动困难症案例，时间为3分钟，我会请1位小伙伴分享。\u003c/p>\u003cp>学习者B分享：\u003c/p>\u003cp>W：下周五前完成月度汇报准备\u003c/p>\u003cp>O：完成汇报PPT制作\u003c/p>\u003cp>O：拖延到下周五才开始写导致完不成\u003c/p>\u003cp>P：如果我内心出现了拖延的想法，我就马上行动开始写PPT汇报材料 。\u003c/p>\u003cp>【小结】最后，做一个简单的总结，回到我们今天的学习目标：\u003c/p>\u003cp>\u003cstrong>第一，\u003c/strong>掌握1个提高行动力的方法，这个方法就是WOOP思维四步法，对于我们想要实现的愿望，当我们设想出最想要的结果后，我们可以通过提前设想可能会遇到的内心障碍，并制订相应的行动计划，来提高行动力，克服行动困难症。你掌握了吗？\u003cstrong>第二，\u003c/strong>现场加工1个自己的克服行动困难症的案例。我相信每个人都现场加工好了未来1-2天你们自己将要行动的案例，如果还没有做完，下来可以继续完善。我的分享完毕，谢谢大家的时间。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1597803579000,"updated_at":1599827605000,"ria":true},{"id":9585,"topic":"WOOP思维方法","learn_goal":"能够复述WOOP四步骤，运用WOOP解决问题，实现目标。","remark":"2019年转眼就要过去了，也许你正在某些重大问题上苦苦挣扎，也许你只是想发掘、利用潜在的可能或机遇，无论你是心怀一个梦想，还是面临一个困境，WOOP这个基于20多年实证研究的思维方法，都能加深你对内心动力的理解，帮助你理清前进的方向，让你在2020年开始真正地改变。一起来体验WOOP的神奇吧。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"付盈盈","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>各位小伙伴儿大家好，我是今天的拆书家付盈盈。今天我要拆解的片段选自《WOOP思维心理学》这本书。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>现在已经是12月中旬了，又到了我们盘点的时候了。我年初也定了几个小目标，比如说学会游泳，当时写下这个目标的时候，我仿佛已经看到了自己在泳池上下翻飞，那个自由舒展真的是惬意。结果呢，夏天嫌泳池人太多，冬天窝在家里不想出门，春秋风和日丽适合郊外活动，白天有事，晚上要带娃，总之，一年都过完了，我还没学会换气。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>你们有没有这样的情况，立FLAG的时候好嗨哦，什么1个月瘦10斤啦，一周读完5本书啦，都不在话下的，“Flag在手，天下我有”，结果呢，执行过程中，不断受挫，然后就没有然后了。有这种情况吗？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>定的目标总是达不成，会给我们带来无力感，轻则怀疑自己，重则怀疑人生。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那怎么办呢？WOOP可以帮到你，它能够帮你识别可实现的目标心愿，教会你怎样将梦想变成现实。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>在学完今天的内容后，我们能够使用（行动）WOOP四步法（澄清），来达成目标和解决难题（界定）。\u003c/p>\u003cp>\u003cstrong>【量表自测】\u003c/strong>\u003c/p>\u003cp>现在，我们先来做一个小测试，来评估自己在实现目标方面的现状。给大家1分钟。\u003c/p>\u003cp>小伙伴的分数：20分、20分、24分、16分、18分。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp; 看到大家都非常的优秀啊，好几位20分以上的，这个测试的目的是帮助我们看到，我们的目标或者说愿望实现的程度。如果你的分数高于20分，说明你现在很接近目标，那一起来看看今天的内容能否帮助你做得更好;如果分数在10-20分之间，说明我们在目标制定或者计划执行方面有改进的空间；如果分数低于10分，我看了一下我们现场没有，那么低于这个分数的就不用多说啦，要赶紧来学一学WOOP思维。\u003c/p>","ratings_count":1,"texts":[{"id":13419,"quote":"\u003cp>小组里还有一位女士，她名叫莱斯利，她的未来24小时里的愿望跟塔米的不太一样。她的宠物狗“臭臭”要睡在自己的板条箱里，如果不然，它就整夜不停地叫唤，这样莱斯利就很难睡得安稳。而这也不全是“臭臭”的错，白天它的活动时间非常少，于是一到晚上，它就焦躁不安，不愿到窝里去睡觉。如果说莱斯利的愿望是“好好睡一觉”的话，那么此愿望的最佳结果就是“第二天工作时沉着坚定精力充沛”。而莱斯利发现，实现这个愿望的障碍，就是她觉得自己太忙了，没有时间带“臭臭”出去散步。于是她的计划就是这样的如果我觉得很忙，不愿出去遛狗，那么我就提醒自己，散步会给“臭臭”带来什么好处，那么我就会带它出去散步了。\u003c/p>\u003cp>第二天，莱斯利向我回馈了一个好消息：她带“臭臭”出去散步了，回来后它就心满意足地到窝里去睡觉了，而莱斯利也美美地睡够了八个小时，比这一周里沉睡时间加起来都多。\u003c/p>","explains":"\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>这是一个关于实现愿望的案例，看起来，莱斯利好像并没有做什么特别的事情。那我们可以先回想一下，我们自己面对同样的情形是怎么做的呢？可能我们也会想“太困了，真想好好地睡一觉”，但是马上又想到臭臭整夜不停地叫唤，根本没办法睡安稳，最近又这么忙，没有时间去遛它。这样一想觉得很头疼，算了算了先不想了，把手头的工作先干完吧。然后，晚上回到家继续昨天的遭遇。那怎么来打破这个恶性循环呢？我们一起来看看莱斯利是怎么做的？\u003c/p>\u003cp>\u003cstrong>【what＆how】\u003c/strong>\u003c/p>\u003cp>【互动提炼步骤，引出概念】\u003c/p>\u003cp>\u003cstrong>首先，她确定了一个愿望\u003c/strong>：好好睡一觉。\u003c/p>\u003cp>提问：然后呢？她做了什么动作？ \u003c/p>\u003cp>学习者：去找实现愿望的障碍。。。找结果的障碍。。。\u003c/p>\u003cp>回应：有小伙伴已经发现了，她先想到实现愿望的结果，然后找出了障碍。看看原文，她想到了这个愿望的最佳结果是第二天工作的时候沉着坚定，精力充沛，这就是我们的\u003cstrong>第二步：描述愿望实现后的结果\u003c/strong>。\u003c/p>\u003cp>提问：接下来呢？又做了什么？\u003c/p>\u003cp>学习者：实现愿望的障碍。\u003c/p>\u003cp>回应：对，接下来她发现实现这个愿望的障碍是她觉得自己太忙了，没有时间带臭臭出去散步。\u003cstrong>这是第三步，找出实现愿望的障碍\u003c/strong>。\u003c/p>\u003cp>提问：那么接下来呢？他又做了什么？\u003c/p>\u003cp>引导：“他的计划就是这样：如果我觉得很忙不愿意遛狗，那么我就提醒自己散步会给臭臭带来什么好处。”这是在做什么？有没有小伙伴可以提炼一下？\u003c/p>\u003cp>学习者：心理暗示。\u003c/p>\u003cp>回应：相当于是他用心理暗示这种方法去把障碍解决掉是不是？其实这一步就是我们的\u003cstrong>第四步，制定一个解决障碍的计划\u003c/strong>。\u003c/p>\u003cp>愿望、结果、障碍、计划，这正是我们WOOP思维的四个步骤，它是一个个人管理工具，帮助我们向好的方向调控我们的人生。咱们为了在短时间内让大家理解这个思维方式，案例和举例都选择了生活中简单的小愿望，实际上我们的愿望可大可小，可以是短期的小目标，也可以是你人生最大的心愿。\u003c/p>\u003cp>\u003cstrong>【细化步骤】\u003c/strong>\u003c/p>\u003cp>接下来，我们来看一下每一个步骤包含哪些动作。\u003c/p>\u003cp>1、 \u003cstrong>确定愿望。\u003c/strong>想一个虽然有些棘手但是你觉得能够达成的愿望。这个过程也是筛选的过程，一些外部阻力过大、完全不以你的意志为转移的愿望就可以放弃了。（板书关键词：有难度、可实现的愿望）\u003c/p>\u003cp>2、 \u003cstrong>想象结果。\u003c/strong>想象一下愿望实现后的美好场景，越具体鲜活越好。这是一个筛选＋确认的过程。如果你联想不到场景，或者你看到那个场景觉得JUST SO SO，那你可能要重新审视一下这真的是你的愿望吗？如果你很受鼓舞，那显然你实现愿望的动力更强一些了。（板书关键词：具体、鲜活）\u003c/p>\u003cp>3、 \u003cstrong>找出障碍。\u003c/strong>找到妨碍你达成愿望的最严重的障碍，这个障碍里的关键想法和行为是什么？什么时间和地点会出现？（板书关键词：障碍是什么？关键想法和行为是什么？什么时间和地点会出现？）\u003c/p>\u003cp>我们一开始想到的障碍很可能是浮于表面的，这个时候，我们可以尝试在前面加上一个“我以为”或者“为什么”，比如我觉得障碍是因为没时间，那这个障碍可能是“我以为没时间”，是在找借口，或者问一下“为什么没时间”之后，发现我真正的障碍可能是时间安排不合理。\u003c/p>\u003cp>4、 \u003cstrong>制定计划。\u003c/strong>要克服或者规避障碍，你能怎么做？制定一个“如果……那么……”计划：如果障碍X出现了，那么我就采取行动Y。每一个障碍可以对应多个“如果……那么……”计划。制定计划的两个方向：一是计划障碍出现时如何克服或躲开，二是制定计划来预防障碍出现。（板书关键词：两个方向：克服、预防。如果障碍X出现了，那么我就采取行动Y）\u003c/p>\u003cp>【举例】比如，我达成某个心愿的障碍是“我以为我没时间”，那么我可以制定计划：\u003c/p>\u003cp>计划1：如果我认为我没有时间，那么我告诉自己这很可能是个借口，我要用10分钟来思考如何合理安排时间。这是障碍出现了我的克服计划。\u003c/p>\u003cp>计划2：如果我认为我没有时间，那么我现在开始学习时间管理，提高自己对时间的利用率。这是预防障碍出现的计划。\u003c/p>\u003cp>这里的计划大家可以把它想象成在我们大脑中植入了一个小程序，如果X出现，那么我们就执行Y指令。\u003c/p>\u003cp>需要补充1点：如果你要运用WOOP，请不要跳过步骤，也不要打乱步骤，步骤出现的顺序不一样，效果很可能打折扣。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>我在上面讲解和举例的时候，都是用于实现心愿或者目标的，其实WOOP也可以用于解决心事或者难题的。在运用的时候，我们第一步就是想一件棘手但能够解决的心事，第二步是想象心事解决后的美好场景。其实这两者本身就是可以相互转化的，有时候我们的心愿可能就是解决某个难题对吧？总之，无论是实现心愿还是解决难题，都是让我们每一个人向好的方向调控自己的人生。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3促动参与\u003c/strong>\u003c/p>\u003cp>【引导场景\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>OK，现在我们来进行一个现场演练，来加深对这4个步骤的理解。小明2020年想去北疆自驾游，他想了好几年了，但是想想自己没有那么长的假期，也没有合拍的旅伴，一直就是对着别人发的图片舔舔屏就算了。\u003c/p>\u003cp>【指令\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>假设你是小明的朋友，请你运用WOOP的四步骤来介入，帮助他实现心愿。我们可以2人一组讨论一下，5分钟之后我们请小伙伴来展示，如果时间不够，我们可以只写关键词。\u003c/p>\u003cp>\u003cem>学习者叶莹的分享：\u003c/em>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>W愿望\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cem>\u003cstrong>北疆自驾游\u003c/strong>\u003c/em>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>O结果\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>\u003cem>1、放松心情 &nbsp; &nbsp;2、释放压力&nbsp; 3、结交朋友 4、增加阅历\u003c/em>\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>O障碍\u003c/p>\u003c/td>\u003ctd>\u003cp>Tips:1、在最初想到的障碍前加上“我以为”或者“为什么”，可以帮助我们挖掘真正的障碍。2、何时、何地可能会出现。\u003c/p>\u003cp>\u003cstrong>\u003cem>1、没有时间 &nbsp; &nbsp;2、没有合拍的旅伴\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>还可能有些隐含的原因：3、经济问题；4、家人的陪伴\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>（回应：我们选取其中一个障碍来做计划。）\u003c/em>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>P计划\u003c/p>\u003c/td>\u003ctd>\u003cp>Tips：1、预防障碍出现；2、障碍出现时如何克服\u003c/p>\u003cp>如果：\u003cstrong>\u003cem>觉得时间不够，\u003c/em>\u003c/strong>那么：\u003cstrong>\u003cem>首先确定去北疆自驾游需要多长时间，结合自己的工作，我这个岗位可以最多支撑我请假多久，再去跟领导沟通时间安排。\u003c/em>\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>回应：谢谢叶莹的分享，在这么短的时间内，可以想出这么多的好处以及障碍，包括一些潜在的障碍。针对时间不够这个具体的障碍，也给出了具体的计划。非常好！补充一点，我让叶莹选择其中一个障碍，并不是说我们只能针对其中一个障碍做计划。只是时间关系，我们只选择了这一个，现场掌握了这种方法，下去以后我们可以再把针对其他障碍的计划进行完善。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A2催化应用\u003c/strong>\u003c/p>\u003cp>【布置任务】通过刚才的情景演练，我们对WOOP有了更深的理解，为了学以致用，给大家布置一个任务：运用WOOP去解决你最近比较棘手的一件事情。请大家在便签上写下你的计划（是一件什么事情，你准备什么时间、什么地点运用WOOP介入，注意这里的时间地点不是指你实现目标的时间地点，是指你运用WOOP思维来梳理的时间地点）给大家1分钟的时间写下你的计划并跟我们分享一下，回去之后再把你的WOOP梳理过程微信分享给我。\u003c/p>\u003cp>\u003cem>学习者刘秋芳现场分享：\u003c/em>\u003c/p>\u003cp>\u003cem>比较棘手的事情：健身计划&nbsp;&nbsp;&nbsp; 执行WOOP的时间：现在 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;执行WOOP的地点：练级场\u003c/em>\u003c/p>\u003cp>\u003cem>回家后补充：\u003c/em>\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>希望通过今天的学习，我们前行路上的障碍都能变成我们实现梦想的台阶，我们在一天天的WOOP中一步一步靠近我们的梦想。最后，我想用两个至关重要的问题来结束本次的拆解：你最大的愿望是什么？妨碍你实现愿望的又是什么？\u003c/p>\u003cp>OK，以上就是我要拆解的全部内容，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1578048643000,"updated_at":1578050809000,"ria":true},{"id":8027,"topic":"WOOP思维的四个步骤","learn_goal":"WOOP思维的四个步骤","remark":"","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"佐江","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，大家能够学会使用WOOP思维法，针对愿望制定出有效的行动计划。\r\n大家好，我是佐江，是一名一级拆书家。我今天要给大家拆解的片段是来自这本《WOOP思维心理学》。\r\n【F】它的作者是加布里埃尔•厄廷根，是一位著名的心理学家。这本书主要介绍了传统积极心理学的一些不足之处，同时教大家学会使用WOOP思维来客服这些不足，提升你达成愿望的能力。\r\n【A】 这本书是社会心理学图书中非常畅销的一本，当当好评率99.7%。与其他同类的心理学书籍相比，它讲解的内容更有实用性，用大量的科学研究成果和试验案例来教会我们如何增强实现愿望的能力。而且它提供的方法，简单好学，学了马上就能用，用能很快就见效。\r\n【B】 那么它对你有什么用呢？\r\n你有没有面对意外状况束手无策的经历？这本书能够教你提前预判风险，顺利解决困难。\r\n你有没有在拖延中苦苦挣扎的经历？这本书能帮你发现拖延的真正障碍，快速完成任务。\r\n你有没有制定目标却无法实现实现的经历？这本书中的WOOP思维法能够让你更轻松地实现目标。\r\n如果你想改善人际关系、养成好习惯、保持身体健康，都可以从书中得到一些启发……","ratings_count":1,"texts":[{"id":11609,"quote":"\u003cp>我今天给大家拆解的片段就是WOOP思维法。本次拆书的目标是：希望大家在跟随我完成本次RIA现场学习后，能够学会使用WOOP思维法，针对愿望制定出有效的行动计划。\u003c/p>\u003cp>下面请大家阅读片段，时间两分钟，读完请举手示意。谢谢！\u003c/p>\u003cp>片段：\u003c/p>\u003cp>生活中的各个方面都可以使用WOOP,而不仅局限于觉得纠结或觉得需要做出改善的时候。 比如说,一份好工作的候选人或学校的优等生,他们都可以使用WOOP,不仅可以用来克服害怕失败的恐惧心理,克服任何可能妨碍他们发挥全部潜力的心理障碍,还可以使自己变得更有创造力、更有成效。同时,在WOOP过程中,人们还能对各自的愿望进行调整。在做WOOP时,也许你会发现某个你原以为虽然棘手但可以达成的愿望其实是根本无法实现的,在你与障碍“面对面”时才发现,它比你原先想象的难度更大、代价更高。通过这种方式,WOOP同样是在帮助你做出最佳表现,因为它是帮助你从不能达成的愿望上面抽身而出,转而把注意力放在那些能够实现的愿望上面。\u003c/p>\u003cp>在做WOOP的时候,你永远都不知道最后会有什么发现。 由于人们极少会正面看待各种障碍,所以,做WOOP的过程往往会激起人的情感反应。在本章开头时我曾提到,我曾与一组明尼苏达州的学校辅导员共事,大家还记得吗?其中有位辅导员名叫科林,他当时30岁,他对我说,他的愿望是在一年半的时间里跟爱人大卫一起买栋房子。“我想最终有一个自己的家庭,还有孩子。”科林如此说道。在我让他想象一下这个愿望的最佳结果时,他说是跟大卫有一个健康快乐的孩子,像个正常家庭一样生活在一起。\u003c/p>\u003cp>在寻找障碍这一环节,科林遇到了不小的难度。 他的脸色变得凝重起来,他转头看着远处,很长一段时间之后才开口说道: “我想,我的问题是不想再跟我长大的那个家再有联系了,一想到自己的身份(同性恋)不被家人接受,我就很难受。我正打算买一栋房子,拥有自己的家庭生活。我觉得,我会选择一种热爱的生活方式。我想在明尼苏达生活,在这里终老。我真是这么想的。”我让科林选择一个关键的障碍,他选的是,因为生活在明尼苏达而不是像芝加哥那种精彩的大城市所带来的焦虑感。他的“如果.那么......”计划是这样的:“如果我因为在明尼苏达定居这件事而感到焦虑或紧张了,我就提醒自己——我跟大卫结成的是一个健康的新家庭,并且,我在这里有自己的人际圈子,他们都很关心我,我从中获益良多。”\u003c/p>\u003cp>写作本书时,我不知道科林的愿望是否已经实现了,但我知道,当初在他离开时,他对自己的情况有了更清晰的理解。 他原先的矛盾心理已经消失了,而且他有了一个克服内心障碍的计划。除此之外,他还有了一个简单易用的工具,他可以每天用一次,甚至一天之内用好几次; 在它的推动下,他就离那个棘手但可达成的愿望越来越近。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>读完这个片段，我们知道生活中的很多方面都可以使用WOOP思维法，他能帮我们找到并克服愿望达成过程中的障碍，从而更好的实现愿望。\u003c/p>\u003cp>可是片段中只告诉我们WOOP思维法的关键是找出实现愿望的关键障碍并想办法克服，就没有更详细的讲解了。\u003c/p>\u003cp>那么\u003cstrong>WOOP\u003c/strong>\u003cstrong>思维法\u003c/strong>具体要怎么做呢？\u003c/p>\u003cp>【\u003cstrong>细化行动步骤\u003c/strong>】\u003c/p>\u003cp>我从片段中案例的发展脉络帮助大家细化出了如下四个步骤：\u003c/p>\u003cp>\u003cstrong>第一步，确定愿望。\u003c/strong>确定一个你想实现的愿望。片段中作者就先问科林有什么愿望，科林的愿望是“拥有一个自己的家庭，还有孩子。”\u003c/p>\u003cp>\u003cstrong>第二步，确定标准。\u003c/strong>确定做到哪些标准，才算是实现愿望了。当科林说出愿望后，作者让科林，想下一下这个愿望的结果。科林回答说是“和大卫在一起、在明尼苏达州、有一个健康快乐的孩子、像正常的家庭一样生活”，有四个标准。\u003c/p>\u003cp>\u003cstrong>第三步，找出障碍。\u003c/strong>锁定愿望达成中，最有可能遇到的关键障碍，如果有多个关键障碍，就把它们按照影响程度排序。比如片段中，科林选择的关键障碍是，因为生活在明尼苏达没有芝加哥这样的大城市精彩可能会产生焦虑或紧张。\u003c/p>\u003cp>\u003cstrong>第四步，设计“如果，那么”方案。\u003c/strong>提前设计出遇到关键障碍时的有效应对方案，并且牢记。这样子当关键障碍发生时，你就能够从容应对。片段中，科林设计的方案是：如果因定居明尼苏达而焦虑，那么提醒自己和大卫结成的是一个健康的家庭，且这里有关心自己的人际圈子，可以获益良多。从而缓解紧张，更容易实现定居愿望。\u003c/p>\u003cp>通过以上的WOOP思维法，我们就能够从容地应对关键障碍，更轻松地达成愿望。\u003c/p>\u003cp>在现实生活中如何具体使用WOOP思维法呢？\u003c/p>\u003cp>\u003cstrong>给大家举个我自己的例子：\u003c/strong>\u003c/p>\u003cp>我很希望能够每天下班回家就去锻炼身体，可是常常做不了几天就中断了，尝试了很多方法都没有效果。\u003c/p>\u003cp>学习了WOOP思维法之后，我是这样做的：\u003c/p>\u003cp>\u003cstrong>第一步，确定愿望。\u003c/strong>我明确自己的愿望是，每天下班回家后去健身房锻炼身体、增强体质。\u003c/p>\u003cp>\u003cstrong>第二步，确定标准。\u003c/strong>我觉得达到以下3个标准，就算实现冤枉了：1、每周去健身房锻炼3次以上；2、每次锻炼1小时以上；3、3个月后体重减10斤以上。\u003c/p>\u003cp>\u003cstrong>第三步，找出障碍。\u003c/strong>我发现自己每次遇到的关键障碍都是“回家感觉很累，一躺在沙发上九不想动了”。\u003c/p>\u003cp>\u003cstrong>第四步，设计“如果，那么”方案。\u003c/strong>经过思考，我给自己设计的“如果，那么”方案是，如果我下班回家感到累想躺在沙发上，那么我就把健身装备放在门口的鞋柜上，一回家就拿上装备去健身房，根本不给自己躺在沙发上的机会。\u003c/p>\u003cp>自从使用了这个方法我已经连续2个月都实现了下班后健身的目标，体重也降了12斤，真得很棒。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>A3：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）：我们刚刚学习了使用WOOP思维法针对愿望制定出有效的行动计划。现在请大家一起来做一个演练。请认真听我讲述的演练场景：小王是一个常常定目标却很少达成的人，每次定下目标他都热血沸腾，一遇到问题他就逃避或拖延，转向一个新的目标。因为这个毛病，他工作3年了也没有大的成绩。小王听说新来的同事小李是一个心理学达人，能够用WOOP法帮人提高目标达成的几率。\u003c/p>\u003cp>现在，请每两人一组，进行演练。一个人扮演小王，你主动找小李述说你的苦恼，请小李引导你梳理出新目标的WOOP方案（这个目标得是你最近这几天最想实现的一个短期愿望，可以是工作方面的、学习方面的、家庭方面的、节日安排方面的）。另一个人扮演小李，你要用WOOP法的话术向小王提问，引导他使用WOOP思维法制定出实现愿望的有效计划。\u003c/p>\u003cp>演练时间8分钟，现在开始。8分钟后，我会选一位“小王”和“小李”起来表演对话的场景或者展示他们的WOOP行动计划。\u003c/p>\u003cp>\u003cstrong>结束后，请\u003c/strong>\u003cstrong>2~3\u003c/strong>\u003cstrong>组人当众表达自己的案例。\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录：\u003c/p>\u003cp>小王（张鹏扮演）：小李呀听说你很厉害，可以用什么WOOP法把人战胜拖延，达成愿望。是真的吗？你可以帮帮我吗？\u003c/p>\u003cp>小李（艳艳扮演）：我试试吧。你有什么想要实现的愿望呢？\u003c/p>\u003cp>小王：我一直想去办理首套房的个人所得税退税，但是拖了一年多了一直没有办到，我也不知道为什么这样简单的问题却一拖再拖。\u003c/p>\u003cp>小李：好的。那请你想一想，这样愿望事项的标准有哪些呢？达成了可以给你带来哪些好的结果呢？\u003c/p>\u003cp>小王：标准就一个，把材料交到房管局去，审核员说我的资料没有问题就行了。好的结果，就是可以增加一笔收入吧，还可以让我感觉自己不再是一个拖延的人了。\u003c/p>\u003cp>小李：好的。既然你拖延了这么久，你认为什么是阻止你实现愿望的最大障碍呢？\u003c/p>\u003cp>小王：我觉得主要是需要到工商银行的分行去打流水很麻烦，需要请半天假，我工作一直都挺忙很难抽出时间，请假老板可能不批。\u003c/p>\u003cp>小李：如果下次真得遇到这个问题，你能不能想办法克服这个障碍呢？\u003c/p>\u003cp>小王：我知道了，如果我决定了下周三要去打印流水，那么我就在周一、周二的时候提前加班把周三的工作完成，这样我就可以找老板批到假去打流水了，打完了流水顺道就把材料拿到房管局去提交了。搞定。\u003c/p>\u003cp>小李：哈哈，你真棒！\u003c/p>\u003cp>小王：原来这么简单就可以解决我的拖延问题呀，这个方法真厉害。它具体是怎么做的呢？\u003c/p>\u003cp>小李：是的。这就是WOOP思维法：分为四步：1、确定愿望；2、确定标准；3、找出障碍；4、设计“如果，那么”解决方案。你回去可以经常使用，相信它可以帮你达成更多的愿望。\u003c/p>\u003cp>小王：好的，非常感谢你的帮助，小李。\u003c/p>\u003cp>小王：不客气。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1559134436000,"updated_at":1559134436000,"ria":true},{"id":7891,"topic":"压力过大时如何缓解？","learn_goal":"压力过大时如何缓解？","remark":"","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"刘小七","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;首先给大家分组，4人为一组，为便于讨论，小组围圈做，每组一个拆书家。\r\n好，分组完毕。大家好，我是小七。下面用三个标签介绍一下我自己。\u003c/p>\u003col>\u003cli>\u003cp>五常大米：产自我的家乡黑龙江哈尔滨五常。\u003c/p>\u003c/li>\u003cli>\u003cp>会员长老：这是我在咱们智荟分舵的头衔，主要负责会员的引入、会员管理、会员退出等工作。\u003c/p>\u003c/li>\u003cli>\u003cp>拆书家：一名正在升级打怪的拆书家。\u003c/p>\u003c/li>\u003c/ol>\u003cp>今天我拆解的书籍是《WOOP思维心理学》，作者是加布里埃尔•厄廷根。世界著名心理学家、美国纽约大学及德国汉堡大学心理学教授&nbsp;\u003cbr>\u003c/p>\u003cp>F：这是一本关于“愿望”和“实现愿望”的书，它以20年的内心动力研究为基础，向大家阐述了一个简单而令人惊讶的理念：追梦路上的障碍，其实是实现梦想的台阶。\u003c/p>\u003cp>A：这本书被诺贝尔经济学奖（2000年）得主詹姆斯•赫克曼、哈佛大学心理学教授丹尼尔·吉尔伯特等数十位权威专家联袂推荐。同时，它与其他同类心理学书籍相比，研究内容更生活化，研究范围更具广度，而且方法实用、也具有实操性。\u003c/p>\u003cp>B1：通过阅读这本书，可以让你告别“积极思维”的心灵鸡汤，用科学的思维训练方法让人兼顾“想”与“做”，开始真正地改变。在实现愿望的过程中减少不必要的阻力，为实现梦想助力。&nbsp;\u003c/p>\u003cp>B2：通过今天拆页的学习，大家至少可以掌握在紧张有压力的场景下如何用WOOP思维帮助摆脱无畏遐想，专注实现愿望的行动。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11439,"quote":"\u003cp>\u003cstrong>压力过大时用WOOP\u003c/strong>\u003c/p>\u003cp>另一个能证明WOOP的益处的地方，是在处理紧急事务或持续的压力时。比如你即将要做的商务演讲，需要乘坐某次航班，对你苛刻却不得不与之共事的上司等。偶尔使用WOOP的人往往不会将其用在紧迫的情况下，他们只知道围绕着刺激的来源团团转。然而，如果你把WOOP养成了习惯，在紧急时刻你就会暂停，对自己说等一下——用WOOP。\u003c/p>\u003cp>比如说，你要在200个人面前主持商品发布会，于是你用了3分钟时间做了WOOP。你的\u003cstrong>愿望\u003c/strong>是什么？把发布会做好。最佳\u003cstrong>结果\u003c/strong>是什么？把发布会的内容传播出去，与听众产生共鸣。你的内心的\u003cstrong>障碍\u003c/strong>是什么？也许是一种普通的紧张感。如“搞不好会丢人”，或某个技术上的障碍，如“我的语速太快了”或“有时候会忘记发言的要点”。这样你的\u003cstrong>计划\u003c/strong>很容易就能成形了：“如果我感到紧张了，那么我就提醒自己：我以前做的商品发布会都很成功。”“如果我发现自己语速过快了，我就慢下来。”“如果我发现自己忘了发言要点了，我就先把这件事记在心上，发布会最后再补充一下。”有了这样一个计划，潜意识又有了“未来”、“障碍”“有益的行为”之间的认知关联，你就能从容应对障碍，在紧迫情况下自信行事。&nbsp;\u003c/p>","explains":"\u003cp>通过这个拆页大家可以了解到实现愿望的WOOP思维，如果将这个方法养成习惯，可以大大增加我们实现愿望的概率。WOOP思维源于“心理比对”的名字，大家看全书会了更深入解到。WOOP是由四个首字母构成的，实际操作时可以拆分为四个步骤：\u003c/p>\u003cp>步骤1：（W）你的愿望或心事是什么？（这个愿望有些棘手但你觉得能够达成）\u003c/p>\u003cp>步骤2：（O）实现愿望或解决心事的最佳结果是什么？\u003c/p>\u003cp>步骤3：（O）妨碍愿望达成的内心障碍是什么？\u003c/p>\u003cp>步骤4：（P）克服障碍最有效的计划或行动是什么？计划的格式：如果xx障碍（包含时间地点），那么xx（行动）。\u003c/p>\u003cp>在压力过大时，事情棘手而解决办法尚不明确时时都可以用WOOP。使用WOOP可以教我们既不会好高骛远，也不会低估自己。\u003c/p>\u003cp>举个自己的例子：\u003c/p>\u003cp>自己最近特别忙，除了工作以外，拆书帮中需要去想和做的也比较多，压力特别大，内心非常焦虑，做事效率也非常低。于是周日晚上下班回来，我便给自己做了一个WOOP。\u003c/p>\u003cp>1、写下自己的愿望：周三晚上可以完成两场拆书准备。\u003c/p>\u003cp>2、实现愿望的最佳结果是不会影响周四、周五的拆书活动。\u003c/p>\u003cp>3、妨碍愿望达成的内心障碍是无法静下心来专注去思考做事。\u003c/p>\u003cp>4、克服障碍最有效的行动是：如果我每天晚上9点在家里发现自己看书走神了，我就告诉自己：没有人能帮你，只有你自己变得强大。\u003c/p>\u003cp>于是我就静下心来分析拆页，看技能点，写预备提示表，两篇逐字稿就这样在每天加班的情况下也最终完成了。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：激活经验\u003c/strong>\u003c/p>\u003cp>现在咱们已经知道了在压力过大、遇到困难等情境下可以用WOOP来解决。那么请各位想想自己没有经历过压力大、感到紧张焦虑的而不知所措的情形？\u003c/p>\u003cp>比如接到一个相对艰难、不太熟悉的工作任务或者上台演讲等。\u003c/p>\u003cp>在小组内分享自己失败的经验，时间3分钟。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>Linda：\u003c/p>\u003cp>我在读书时兼职工作的经历，做市场调查员，给自己的目标是一天在路上拉10个人去做调查，当时自己的障碍是总是怕对方拒绝自己，不愿意跟自己一起上去，结果导致经常不达标。\u003c/p>\u003cp>\u003cstrong>A2：催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>接下来请各位在便签上做一个未来的行动计划，目标要具体、有明确的时限、有可衡量或可观测的预期结果，行动计划的实施要用WOOP来做。大家按照拆页背面的模板来写。\u003cbr>\u003c/p>\u003cp>1分钟后，我请一位伙伴分享自己的行动计划。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>艳雯：\u003c/p>\u003cp>背景：本周六要去参加一个读书分享。\u003c/p>\u003cp>1、 W：写下自己的愿望：周六在读书分享会时自然一点\u003c/p>\u003cp>2、 O：实现愿望的最佳结果：分享得有逻辑一点，不会乱七八糟\u003c/p>\u003cp>3、 O:妨碍愿望达成的内心障碍是对准备不下去稿件，对稿件不熟悉\u003c/p>\u003cp>&nbsp; 4、 P:如果在家准备不下去，那么我就冥想。\u003c/p>\u003cp>\u003cstrong>一句话总结：\u003c/strong>\u003c/p>\u003cp>今天我们一起学习了压力过大时用WOOP实现愿望，期待大家能将WOOP养成习惯，随时随地用WOOP，达成的愿望会越来越多！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1557832683000,"updated_at":1557833059000,"ria":true},{"id":7686,"topic":"能够采用心理对照的方式解决做事情过于理想化的情况","learn_goal":"见开场部分","remark":"","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"赵自力","city":""},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是Jack，稍后会有小组讨论，我们先分一下组。 \u003c/p>\u003cp>【学习目标】学习者通过本次学习，可以在制定目标时（where），使用心理比对的方法（澄清），列举出（行为）目标实现的障碍（界定），并制定（行为）应对计划（界定）。\u003c/p>\u003cp>【场景法图书介绍】\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>大家有没有这样的一些体验？年初为定好的新年目标兴奋不已摩拳擦掌，想到目标实现的样子还禁不住偷着乐，不自觉得就翘起了二郎腿。然后呢随着时间的推移就没有然后了……直至年终唉声叹气责怪自己。接触到强意向客户，想着搞定他就能带来不菲奖金，禁不住哼起了小曲，开始筹划来一场说走就走的旅行，结果掉以轻心，忽视了沟通细节，遗漏了客户关键需求，客户“说走就走”了还被领导一顿臭骂。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>工作生活中经常发生类似的场景，你尝试过什么样的方法呢？一次又一次老样子，还是觉着应该在某些环节能施加影响？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>面对目标我们满是憧憬，“哎呀想想太美了”忽视了实现过程，导致结果不及预期。落差很大、挫败，自我埋怨，个人颓废挣扎生活一团麻，领导看不上工作不如意，自怨自艾，自我价值感和自尊心饱受折磨。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>今天给大家带来的这本《WOOP思维心理学》能帮到大家，打破传统“积极思维”的心灵鸡汤，通过WOOP思维方式，从目标、结果、障碍、计划4个维度，帮你将目标愿景与现实链接在一起，感受行动必要性和紧迫性。今天的片段来自本书的79页，大家可以学到心理比对的概念，建立设想障碍的意识，针对障碍制定应对计划。在认知层面上做好实现目标的准备，在行动上制定相应策略。\u003c/p>\u003cp>在开始学习之前，我们先做一个小测试，有5个题目，请按照1-6分的标准给自己打分，1分代表完全不符合，6分代表非常符合。仔细阅读，根据自己的实际情况为自己打分，并在最后计算总分，时间为1分钟。\u003c/p>\u003cp>通过这个测试可以观察到目标愿景与现实障碍的链接程度。大家有超过25分的吗？（无人举手）这个高分区间代表链接程度非常高，能够感受到很强的行动必要性和紧迫性，具备非常强的行动力；10-20分是中间区间，看一下有哪些小伙伴（2位举手）不错，有两位小伙伴。这个区间代表有一定链接，但也有很大提升空间；5-10是低分区间属于乐观幻想派，容易轻视目标实现的过程，会有行动瘫痪哦。不管哪个区间，今天的片段学习都可以给大家一些帮助和收获。接下来请大家用1分钟时间来阅读原文。\u003c/p>","ratings_count":1,"texts":[{"id":11179,"quote":"\u003cp>20世纪90年代，当我的研究初次证实乐观的幻想无助于实现梦想的时候，我很失望。我之所以要研究人的幻想，并非仅仅出于兴趣，而是希望幻想能给那些在实现大大小小的梦想时遇到困难的人以帮助。它若是不会给人们带来改观，那我的研究就没有意义了；所以我开始考虑，是否能在幻想的过程中干预一下，进而扭转局势，使幻想变得有益于实现梦想呢？尤其要指出的是，既然乐观的幻想会令人放松、松弛下来，我是不是能找到一个办法，利用幻想将人“唤醒”，给他们动力促其成功？我认为，让人行动起来的最好的办法是让他们心怀梦想，然后立刻将阻碍梦想实现的现实放在他们前面。我将二者的对峙称作“心理比对”。通过“心理比对”，我可以将幻想放在现实的基础之上，避开其令人松懈的副作用，将其作为一个工具，唤起人行动的动力。\u003c/p>","explains":"\u003cp>【WHY】\u003c/p>\u003cp>就像开场制定年度目标时的兴奋不已、想着搞定客户哼起的小曲。制定目标时我们一开始很容易对结果保持过于乐观的态度，这让我们处于一种愉悦轻松的状态，在这种状态里，不自觉地放松下来。大脑也被迷惑，感觉目标实现并不难，“哎呀，一切尽在掌握，早晚的事”。它扭曲了我们对周围世界的信息搜集和判断，无法对客观情况进行审视。感受不到行动的必要性和紧迫性。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>好在作者通过实验研究，提出了片段中的概念方法叫心理比对。【简短互动】请问大家片段中时如何定义这个概念的？（将目标愿景与现实障碍对峙）对，直中标吧，非常赞。我做一个具象的解读：它是指个体首先想象目标实现的愿景，比如超额完成年度业绩指标带全家老小马尔代夫游，然后思考现实过程中阻碍目标实现的因素，比如客户量小、转化率低等。通过对比目标实现的愿景和现实障碍，链接未来和现实，进一步将障碍和克服障碍的行动之间建立联系。接下来我们通过例子来看一下。\u003c/p>\u003cp>【简短互动】\u003c/p>\u003cp>1、宅男小明今年目标完成全马，到时同事夸赞还能博女神关注想想就美，大家来看，关于心理比对，小明哪方面做到了？哪方面没做到？\u003c/p>\u003cp>学习者：有目标有愿景，没有预想现实中的障碍。\u003c/p>\u003cp>非常赞，大家理解的很到位，想想就美肯定有动力，小明需要进一步感受到规律训练的必要性。\u003c/p>\u003cp>2、 我有位工作非常努力的朋友目标是再升一职，这样可以带团队、薪资增长还可以买车。他也想到了最坏的结果不升职被外派到子公司。大家注意这个是心理比对吗？\u003c/p>\u003cp>学习者：摇头，有的点头说是。\u003c/p>\u003cp>这里大家注意一下，这不是心理比对。这有一个非常容易混淆的概念叫“防御性悲观”个体在面临新的类似成功情境时反复思考事情的各种可能结果放低期望值。两者最大的区别是防御性悲观偏重对结果的低预期设想，心理比对强调过程实现中的障碍。如果我那位朋友想到了工作业绩还不太够份量，团队影响力小等阻碍因素，这就进入心理比对的轨道，进而针对障碍因素采取相应的行动。\u003c/p>\u003cp>【HOW】刚才通过例子对比，我们更好理解了心理比对的概念，那么具体如何做呢？我细化到四个步骤分享给大家：\u003c/p>\u003cp>1、确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、描述愿景。描述出目标达成之后的结果、价值和意义，思想自由驰骋尽量生动形象，来激发自己的行动力和积极性。\u003c/p>\u003cp>3、设想障碍。对相关情况和经历展开想象，外部探寻，内部深挖，设想关键障碍。\u003c/p>\u003cp>4、执行意图。要克服或规避障碍的话，你能怎么做？想象障碍可能出现的时间地点和可能情况，制定出一个“如果……那么……”的计划。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>简单介绍背景：11月初正式加入拆书帮开始拆书升级，当时希望能在19年5月份荣膺三级拆书家“哎呀想想就美”。结果拆书的难度超出预期，找拆页，被打回，重找。写预备表，被打回，重写。早起写周末写下班回家写，花费了大量时间，我还有工作加班还有老婆要陪，这种冲突很容易让人放弃，之所以能坚持下来得益于这个方法。我是怎么做的呢？\u003c/p>\u003cp>1、写下目标。19年5月份成为三级拆书家。\u003c/p>\u003cp>2、描述愿景。为工作赋能逐步接触到培训这样我就覆盖到了人力的全模块，为HRD更进一步；打开了弱联系圈层，开拓视野格局等等。\u003c/p>\u003cp>3、设想障碍。1）经常加班时间紧张；2）反复不过要面子不去了。\u003c/p>\u003cp>4、执行意图。如果碰上项目加班期，那么要打提前量，一方面利用好早起的通勤时间另一方面抓住每次空余线下分享的机会，错过一次就是错过一周；如果碰到问题要面子那么就转换为成长型思维，突破了舒适区，是一个很好的学习机会。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个方法适用于较为明确的可执行的目标，同时也要有一定的挑战性和复杂性，对于几乎没有挑战性的目标可以用但意义不大。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>你可能会说有些目标是第一次设立和执行，对障碍是缺乏预见性的，也就没办法针对障碍制定应对计划，这个方法有BUG啊。\u003c/p>\u003cp>首先我们必须要承认的是：无论做到什么程度障碍因素是无法穷尽的，穷尽障碍因素不是心理比对的目的，目的是什么？是给梦中的你浇一浇冷水，凡事没那么容易，感受到行动必要性和紧迫性。换一个角度“障碍缺乏预见性” “没经验、不知道坑在哪” 也是你设想的一个障碍呀，针对这种情况你同样可以建立执行意图，如果碰到预料之外的障碍，那么我就……请教领导问导师等等。\u003c/p>","interaction":"\u003cp>以上是我们对概念和步骤的学习，咱们拆书帮讲求拆为己用，要用，接下来为了更好理解加深印象，我们现场演练一下。\u003c/p>\u003cp>【背景】小明是一位体重达200斤的“重量级选手”，在身体指标亮起红灯时，作为单身肥宅的他终于下定决心减肥。19年的目标是减重20斤，他对此很有信心，“管住嘴迈开腿，我可以的！”。 \u003c/p>\u003cp>【指令】听到这个数字，相信大家肯定会为他捏一把汗。请大家根据Jack细化的行动步骤，给小明一个应对方案。\u003c/p>\u003cp>方案中请体现出我们按照细化步骤一步步形成方案的过程，方便小明理解。\u003c/p>\u003cp>学习者玉钦：利用心理比对和细化步骤形成方案是\u003c/p>\u003cp>1、确认目标：2019年减重20斤；\u003c/p>\u003cp>2、描述愿景：1）能穿喜欢的衣服；2）喜欢的姑娘的关注等。\u003c/p>\u003cp>3、设想障碍：1）不知道怎么减肥（不知道方法）2）中途放弃，意志力不坚定；3）美食的诱惑，管不住嘴。\u003c/p>\u003cp>4、执行意图：关于管不住嘴，比如如果想吃一碗米饭那么就改吃半碗（换一个小点的碗）。\u003cbr>\u003c/p>\u003cp>【布置任务】（特定任务）\u003c/p>\u003cp>感谢大家这么热烈的讨论，相信大家较好的掌握了这个方法。不过话又说回来，即便你认同了心理比对这个概念，并掌握了方法。但由于这并不是你的习惯，很有可能在制定目标时放置一边。我们需要刻意练习，逐步化为己用。给大家布置一个课后作业（特定任务）：写出下周的一个关键目标，然后套用今天学习的心理比对四个步骤，把它们记录下来。周日我会微信大家跟进一下任务完成情况。\u003c/p>\u003cp>现场请大家规划一下落实“写下周关键目标”这个特定任务的场景，是在什么时间、地点、用什么形式。1分钟找一个小伙伴做个分享。\u003c/p>\u003cp>现场学习者peri：今晚睡前在家中卧室写在手机上。感谢peri的分享，脑中有规划落地更易实施。\u003c/p>\u003cp>后续跟踪特定任务完成情况。学习者穆穆：\u003c/p>\u003cp>下周的1个关键目标：周六前完成妇科医院的行业研究报告（主动学习）\u003c/p>\u003cp>使用心理比对的概念方法：\u003c/p>\u003cp>1、确认目标：周六前完成妇科医院的行业研究报告\u003cbr>\u003c/p>\u003cp>2、描述愿景：1）对妇科专科医院有大框架认识，能做院长访谈时可以更好同频对话；2）提升专业深入，和公司业务导向保持一致，更多发展空间\u003c/p>\u003cp>3、设想障碍：1）平时加班比较多，没时间；2）市面上的相关医院数据较少；3）不知道从哪方面切入。\u003c/p>\u003cp>4、执行意图：1）如果晚上加班那么在地铁上用手机收集信息，后期集中整理；2）如果医院数据较少那么查看是否有付费解读或者找行业人士做访谈（平时能介绍大量医院人士）；3）如果把握不好切入点那么和资深同事请教，也可以查看专业券商研究报告视角。\u003c/p>\u003cp>最后我们回顾一下：今天我们的学习目标是：可以在制定目标时，使用心理比对的方法，列举出目标实现的障碍，并制定应对计划。我们学习了心理比对的概念和衍生步骤，然后我们进行了催化应用。以上是我今天的分享，期待大家能有收获和行动，谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1555901670000,"updated_at":1555902115000,"ria":true},{"id":7328,"topic":"目标实现！","learn_goal":"能够采用心理对照的方式解决做事情过于理想化的情况","remark":"","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"赵自力","city":""},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是Jack，稍后会有小组讨论，我们先分一下组。 \u003c/p>\u003cp>【学习目标】学习者在制定目标时，能够列举出目标实现的障碍，针对障碍做出应对计划。\u003c/p>\u003cp>【场景法图书介绍】\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>大家有没有这样的一些体验？看到别人和老外无缝交流羡慕不已，用三个月的工资报了“死贵”的英语学习班，现在捶死自己的心都有；接触到一个能带来不菲奖金的潜在客户就开始筹划来一场说走就走的旅行，结果客户“说走就走”了；年初为定好的新年目标兴奋不已摩拳擦掌，年终唉声叹气责怪自己；5年前就想学的吉他现在还是不会，偶尔还会想起2年前脑袋一热办的3年期健身卡。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>有没有太扎心了？有没有想过，都说心想事成，目标明明是自己的渴求况且并非不可实现，为什么到现在还未曾拥有？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>我们对目标实现的状态满是憧憬，这可以给我们带来十足的动力和干劲，但过于乐观觉着早晚会实现，就会感受不到行动的必要性和紧迫性，成为“思想上的巨人，行动上的矮子”。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>今天给大家带来的这本《WOOP思维心理学》能帮到大家，书中提出了心理比对和执行意图，从目标、结果、障碍、计划4个维度，帮你将目标与现实链接在一起，在认知层面上做好实现目标的准备，在行动上制定相应策略，最终实现切实可行的目标。\u003c/p>\u003cp>\u003cstrong>【自测题】\u003c/strong>\u003cbr>\u003c/p>\u003cp>在开始之前我们先做一个小测试，有5个题目，请按照1-6分的标准给自己打分，1分代表完全不符合，6分代表非常符合。仔细阅读，根据自己的实际情况为自己打分，并在最后计算总分，时间为1分钟。\u003c/p>\u003cp>通过这个测试可以观察到未来目标与现实障碍的链接程度。大家有超过25分的吗？（无人示意）这个高分区间代表链接程度非常高，具备非常强的行动力；10-20分是中间区间，有哪些小伙伴？（哦，不错1位小伙伴）这个区间代表有一定链接，但也有很大提升空间；（看来大部分属于）5-10是低分区间属于乐观幻想派，很容易行动瘫痪哦。不管哪个区间，今天的片段学习可以在这方面帮到你，好就加强，不足就提升。接下来请大家用1分钟时间来阅读原文。\u003c/p>","ratings_count":1,"texts":[{"id":10771,"quote":"\u003cp>20世纪90年代，当我的研究初次证实乐观的幻想无助于实现梦想的时候，我很失望。我之所以要研究人的幻想，并非仅仅出于兴趣，而是希望幻想能给那些在实现大大小小的梦想时遇到困难的人以帮助。它若是不会给人们带来改观，那我的研究就没有意义了；所以我开始考虑，是否能在幻想的过程中干预一下，进而扭转局势，使幻想变得有益于实现梦想呢？尤其要指出的是，既然乐观的幻想会令人放松、松弛下来，我是不是能找到一个办法，利用幻想将人“唤醒”，给他们动力促其成功？我认为，让人行动起来的最好的办法是让他们心怀梦想，然后立刻将阻碍梦想实现的现实放在他们前面。我将二者的对峙称作“心理比对”。通过“心理比对”，我可以将幻想放在现实的基础之上，避开其令人松懈的副作用，将其作为一个工具，唤起人行动的动力。\u003c/p>","explains":"\u003cp>【WHAT】【简短互动】\u003c/p>\u003cp>1、大家有没有发现片段中有一个概念，它是什么？（心理比对）直中标靶，非常赞。\u003c/p>\u003cp>2、作者是发现什么的问题，才提出的这个概念方法呢？（乐观幻想让人松弛无助于梦想实现）重复学习者发言，并进行积极认可。对的，很好。\u003c/p>\u003cp>3、针对这种问题，作者提出的最好方法是什么？（将心怀梦想和现实阻碍对峙）是。以上是整个片段的核心，我稍微做个具象的解读，它是指个体首先想象目标实现的愿景，比如超额完成年度业绩指标带全家老小马尔代夫游，然后思考现实过程中阻碍目标实现的因素，比如客户量小、转化率低等。通过对比目标实现的愿景和现实障碍，链接未来和现实，进一步将障碍和克服障碍的行动之间建立联系。接下来我们通过例子来看一下：\u003c/p>\u003cp>小明去年跑半程马拉松今年目标完成全马，到时同事夸赞还能博女神关注想想就美，有目标有愿景，请问大家这算是心理比对吗？（不是），对，不是，没有预想现实中的障碍。\u003c/p>\u003cp>我有位工作非常努力的朋友目标是再升一职，这样可以带团队、薪资增长还可以买车。他也想到了最坏的结果不升职被外派到子公司。大家注意这个是心理比对吗？（有的点头，有的不是）不是。这有一个非常容易混淆的概念叫“防御性悲观”个体在面临新的类似成功情境时反复思考事情的各种可能结果放低期望值。两者最大的区别是防御性悲观偏重对结果的低预期设想，心理比对强调过程实现中的障碍。如果我那位朋友想到了工作业绩还不太够份量，团队影响力小等阻碍因素，这就进入心理比对的轨道，进而针对列举的障碍因素采取应对计划。\u003c/p>\u003cp>【HOW】我将心理比对细化到四个步骤总结为WOOP分享给大家：\u003c/p>\u003cp>1、W：确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、O：描述愿景。描述出目标达成之后的结果、价值和意义，思想自由驰骋尽量生动形象，来激发自己的行动力和积极性。\u003c/p>\u003cp>3、O：设想障碍。对相关情况和经历展开想象，外部探寻，内部深挖。\u003c/p>\u003cp>4、P：执行意图。要克服或规避障碍的话，你能怎么做？想象障碍可能出现的时间地点和可能情况，制定出一个“如果……那么……”的计划。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个方法适用于较为明确的可执行的目标，同时也要有一定的挑战性，对于几乎没有挑战性的目标意义不大。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>简单介绍背景：11月初正式加入拆书帮开始拆书升级，当时希望能在19年5月份成为三级拆书家，觉着难度不大。结果拆书的难度超出预期，找拆页，被打回，重找。写预备表，被打回，重写。早起写周末写下班回家写，花费了大量时间，我还有工作加班还有老婆要陪，这种冲突是不是觉着让人无所适从，很容易放弃？之所以能坚持下来得益于心理比对和衍生的四个步骤。我是怎么做的呢？\u003c/p>\u003cp>1、W：写下目标。19年5月份成为三级拆书家。\u003c/p>\u003cp>2、O：描述愿景。逐步接触到培训这样我就覆盖到了人力的全模块为工作赋能，为HRD更进一步；小成本尝试自己各种可能性，发现人生志趣；打开了弱联系圈层，开拓视野格局等等。\u003c/p>\u003cp>3、O：设想障碍。1）经常加班时间紧张；2）反复不过要面子不去了。\u003c/p>\u003cp>4、P：执行意图。如果晚上加班那么明天早起写，早出发1小时避免拥挤利用好通勤时间；如果碰到问题要面子那么就转换为成长型思维，突破了舒适区，是一个很好的学习机会。\u003c/p>","interaction":"\u003cp>【场景演练】\u003cbr>\u003c/p>\u003cp>接下来为了更好理解加深印象，我们进行一个场景演练。\u003c/p>\u003cp>【背景】是这样：小明是一位体重达200斤的“重量级选手”，在身体指标亮起红灯时，作为单身肥宅的他终于下定决心减肥。19年的目标是减重20斤，他对此很有信心，“管住嘴迈开腿，我可以的！”。 \u003c/p>\u003cp>【指令】听到这个数字，相信大家肯定会为他捏一把汗。请大家根据Jack细化的行动步骤，给小明一个应对方案。\u003c/p>\u003cp>方案中请体现出我们按照细化步骤一步步形成方案的过程，方便小明理解。\u003c/p>\u003cp>【学习者分享】蒋老师：\u003c/p>\u003cp>1、确定目标：2019年减重20斤\u003c/p>\u003cp>2、描述愿景：1、身体健康程度有很大提升；2、达成后肯定会得到周边人的点赞，心理上很大的满足；3、自信度也有很大提升。\u003c/p>\u003cp>4、设想障碍：1、贪吃，美食诱惑控制不住；2、懒，比较困难受到朋友聚会等影响；3、动力不足，就不想锻炼\u003c/p>\u003cp>5、执行意图：针对动力不足，如果出现动力不足不想锻炼的情况就再强化愿景实现的情景，增强动力，提升执行力度。\u003cbr>\u003c/p>\u003cp>【布置任务】（事后复盘）\u003c/p>\u003cp>即便你认同了心理比对这个概念，并掌握了方法。但由于这并不是你的习惯，你还是会忍不住做出过于乐观的判断。不过有一种方法叫“事后复盘”可以帮助你更好地把这个片段拆为己用。给大家布置一个课后作业：接下来两三周里，请你刻意留意自己对待目标的过程和结果，把它们记录下来，观察woop四个步骤的使用情况，哪一个环节做的好，哪个环节可以改进。后面我会通过微信追踪大家的作业情况。\u003c/p>\u003cp>现在请现场30秒规划一下：在什么时间、地点以什么样的方式来做这个事后复盘的作业？\u003c/p>\u003cp>学习着卢燕：周末在家里用书面的形式对一周的目标进行回顾，复盘思考woop的使用情况。\u003cbr>\u003c/p>\u003cp>【总结】\u003cbr>\u003c/p>\u003cp>接下来我们回顾一下：今天我们的学习目标是：学习者在对完成目标表示乐观时，能够列举出目标实现的障碍，针对障碍做出应对计划。我们学习了心理比对的概念和衍生步骤，然后我们进行了催化应用。以上是我今天的分享，期待大家能有收获和行动，谢谢大家。\u003c/p>\u003cp>【作业追踪】学习者穆穆\u003cbr>\u003c/p>\u003cp>微信信息反馈：\u003c/p>\u003cp>学习了心理比对，我用它的四个维度制定了2个周目标，周六进行的复盘\u003cbr>目标：\u003cbr>1、通过岗位晋级评审；\u003cbr>2、看完《财务分析》教材。\u003cbr>复盘：\u003cbr>苹果：整体完成不错，制定的时候4个步骤都有想到，非常有仪式感，认真对待和执行；\u003cbr>洋葱：第一个目标对障碍设想的还是不充分，这方面不仅限于个人思考，也可以征求过来人的意见信息，这样更充分。我以为评审不会问太多问题，但现场问的很犀利也有些准备不足；第二个目标总体执行不错但对进步把握不好，如果在一开始想到“对进度预估不足”这个“障碍”，重要的是心理有个准备预期，不至于太过死磕自己，其实完成的还不错但没看完就觉着还欠缺的。\u003cbr>除此之外，有些事情发生还是woop思维意识不够\u003cbr>周三同事让我帮忙处理个事情，我觉着应该没多大问题就随口答应了，结果做起来消耗了自己很多的时间，特别懊悔。如果我当时想象做这个事情的障碍（自己的时间安排，事情的内容难度等）我可能就不会答应，至少不会这么爽快，也不至于懊悔。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1551710928000,"updated_at":1552188237000,"ria":true},{"id":7159,"topic":"自我管理＆沟通表达","learn_goal":"见实录","remark":"厄廷根教授提出了一种全新的思维方式“WOOP”即希望-结果-障碍-计划。在戒烟、减肥、提高学习成绩、培养良好的人际关系、提高商业经营效率等方面都对学习着产生深远影响。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"赵自力","city":""},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"大家好，我是Jack，稍后会有小组讨论，我们先分一下组。 \r\n【学习目标】学习者在对完成目标表示乐观时，能够列举出目标实现的障碍，针对障碍做出应对计划。\r\n【场景法图书介绍】\r\n【事件场景】大家有没有这样的一些体验？看到别人和老外无缝交流羡慕不已，用三个月的工资报了“死贵”的英语学习班，现在捶死自己的心都有；接触到一个能带来不菲奖金的潜在客户就开始筹划来一场说走就走的旅行，结果客户“说走就走”了；年初为定好的新年目标兴奋不已摩拳擦掌，年终唉声叹气责怪自己；5年前就想学的吉他现在还是不会，偶尔还会想起2年前脑袋一热办的3年期健身卡。\r\n【提问】有没有太扎心了？有没有想过，都说心想事成，目标明明是自己的渴求况且并非不可实现，为什么到现在还未曾拥有？\r\n【影响】我们对目标实现的状态满是憧憬，这可以给我们带来十足的动力和干劲，但过于乐观觉着早晚会实现，就会感受不到行动的必要性和紧迫性，成为“思想上的巨人，行动上的矮子”。\r\n【解决】今天给大家带来的这本《WOOP思维心理学》能帮到大家，书中提出了心理比对和执行意图，从目标、结果、障碍、计划4个维度，帮你将目标与现实链接在一起，在认知层面上做好实现目标的准备，在行动上制定相应策略，最终实现切实可行的目标。","ratings_count":1,"texts":[{"id":10566,"quote":"\u003cp>20世纪90年代，当我的研究初次证实乐观的幻想无助于实现梦想的时候，我很失望。我之所以要研究人的幻想，并非仅仅出于兴趣，而是希望幻想能给那些在实现大大小小的梦想时遇到困难的人以帮助。它若是不会给人们带来改观，那我的研究就没有意义了；所以我开始考虑，是否能在幻想的过程中干预一下，进而扭转局势，使幻想变得有益于实现梦想呢？尤其要指出的是，既然乐观的幻想会令人放松、松弛下来，我是不是能找到一个办法，利用幻想将人“唤醒”，给他们动力促其成功？我认为，让人行动起来的最好的办法是让他们心怀梦想，然后立刻将阻碍梦想实现的现实放在他们前面。我将二者的对峙称作“心理比对”。通过“心理比对”，我可以将幻想放在现实的基础之上，避开其令人松懈的副作用，将其作为一个工具，唤起人行动的动力。\u003c/p>","explains":"\u003cp>【WHAT】【明确核心概念】\u003cbr>\u003c/p>\u003cp>片段中有个概念叫“心理比对”稍微做个解读：它是指个体首先想象目标实现的愿景，比如超额完成年度业绩指标带全家老小马尔代夫游，然后思考现实过程中阻碍目标实现的因素，比如客户量小、转化率低等。通过对比目标实现的愿景和现实障碍，链接未来和现实，进一步将障碍和克服障碍的行动之间建立联系。\u003c/p>\u003cp>【概念举例往返】我们边看例子边学习一下。\u003c/p>\u003cp>员工被洗脑边挥拳头边跺脚扯着嗓子喊“相信自己我可以！我可以！！可以…”这种口号式目标能做出心理比对吗？不能，\u003cstrong>目标不具象，愿景也无从谈起\u003c/strong>。\u003c/p>\u003cp>我毕业刚到北京工作心气很高就定下目标买房，有了房就在北京扎了根，给老婆一个安稳的家，以后孩子上学也有着落，也不用搬来搬去。\u003cstrong>心怀梦想有目标有愿景，\u003c/strong>但这算是心理比对吗？不完全是，\u003cstrong>没有预想现实中的障碍\u003c/strong>。\u003c/p>\u003cp>我有位工作非常努力的朋友目标是再升一职，这样可以带团队、薪资增长还可以买车。他也想到了最坏的结果不升职被外派到子公司。大家注意这个是心理比对吗？不是。【概念比对】\u003cstrong>这有一个非常容易混淆的概念叫“防御性悲观”\u003c/strong>个体在面临新的类似成功情境时反复思考事情的各种可能结果放低期望值。两者\u003cstrong>最大的区别是\u003c/strong>防御性悲观偏重对结果的低预期设想，心理比对强调过程实现中的障碍。如果我那位朋友想到了工作业绩还不太够份量，团队影响力小等阻碍因素，\u003cstrong>这就进入心理比对的轨道，\u003c/strong>进而可以在障碍和克服障碍的行动之间建立联系。\u003c/p>\u003cp>【HOW】【引出行动建议】\u003c/p>\u003cp>那我们如何来做好心理比对呢？和大家分享四个步骤总结为WOOP：\u003c/p>\u003cp>1、W：确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、O：描述愿景。描述出目标达成之后的结果，思想自由驰骋尽量生动形象。\u003c/p>\u003cp>3、O：设想障碍。对相关情况和经历展开想象，外部探寻，内部深挖。\u003c/p>\u003cp>4、P：执行意图。要克服或规避障碍的话，你能怎么做？想象障碍可能出现的时间地点和可能情况，制定出一个“如果……那么……”的计划。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>简单介绍背景：11月初正式加入拆书帮开始拆书升级，当时希望能在19年5月份成为三级拆书家。拆书的难度超出预期，找拆页，被打回，重找。写预备表，被打回，重写。早起写周末写下班回家写，花费了大量时间，我还有工作加班还有老婆要陪，这种冲突是不是觉着让人无所适从，很容易放弃？之所以能坚持下来得益于心理比对和衍生的四个步骤。我是怎么做的呢？\u003c/p>\u003cp>1、W：写下目标。19年5月份成为三级拆书家。\u003c/p>\u003cp>2、O：描述愿景。逐步接触到培训这样我就覆盖到了人力的全模块为工作赋能，为HRD更进一步；小成本尝试自己各种可能性，发现人生志趣；打开了弱联系圈层，开拓视野格局。\u003c/p>\u003cp>3、O：设想障碍。1）经常加班时间紧张；2）反复不过要面子不去了。\u003c/p>\u003cp>4、P：执行意图。如果晚上加班那么明天早起写，早出发1小时避免拥挤利用好通勤时间；如果碰到问题要面子那么就转换为成长型思维，突破了舒适区，是一个很好的学习机会。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个方法适用于较为明确的可执行的目标，同时也要有一定的挑战性，对于几乎没有挑战性的目标意义不大。\u003c/p>","interaction":"\u003cp>【学习者编剧本】\u003c/p>\u003cp>在拆书帮我们提倡是学以致用，研究成果也表明在大脑中过一遍等于实际应用了一遍。现在请大家按照发给模板编一段发生于未来的小故事，设计出时间、地点、人物、情节（包括：起因、经过、结果）和双方的对话、动作等，其中部分对话使用心理比对四个步骤，时间5分钟，请讨论稍后我们请人分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>未来时间：19年2月14号\u003c/p>\u003cp>发生地点：海路轮朴味纯香\u003c/p>\u003cp>发生场景：yamy第二次2-1拆书升级，像今天的活动现场\u003c/p>\u003cp>任务角色：角色A是内心天使，角色B是yamy自身\u003c/p>\u003cp>事件内容：yamy对2-1既渴望通过后师父的夸赞又纠结现场的不确定性，内心在做思想斗争，通过应用片段内容方法，助力顺利完成升级。\u003c/p>\u003cp>动作说明：微笑，表情（傻笑）等\u003c/p>\u003cp>对白：\u003cbr>\u003c/p>\u003cp>A：来都来了肯定要拆的，通过后能得到师父的夸赞（愿景，目标时间的最佳结果状态）\u003cbr>\u003c/p>\u003cp>B：都是陌生人，坚持不下去了，手都不知道往哪放（障碍，预想现场可能的情况）\u003c/p>\u003cp>A：就当一次尝试，可以再试一次，已经和师父演练过了，肯定没问题的。\u003c/p>\u003cp>B：我已经演练过好多次，还记住词怎么办？（思考对策）\u003c/p>\u003cp>A：如果记不住词，就照着稿子念也可以（执行意图）\u003cbr>\u003c/p>\u003cp>给予学习者大拇指夸赞，带领鼓掌。\u003cbr>\u003c/p>\u003cp>【总结】\u003cbr>\u003c/p>\u003cp>接下来我们回顾一下：今天我们的学习目标是：学习者在对完成目标表示乐观时，能够列举出目标实现的障碍，针对障碍做出应对计划。我们学习了心理比对的概念和衍生步骤，然后我们进行了剧本的编写。以上是我今天的分享，期待大家能有收获和行动，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1548657179000,"updated_at":1548657179000,"ria":true},{"id":6406,"topic":"如何用woop实现那些有难度，但是可以达成的事情。","learn_goal":"能够运用woop方法，达成生活中那些略有难度但能够达成的任务","remark":"帮助梦想实现的woop方法大名鼎鼎，但是市面很多转介绍的文章或者书籍都或多或少存在语焉不详，甚至存在错误，今天正本清源，给大家带来设计者厄廷根的原著，与大家一起共同学习如果用woop的方法简单有效的达成愿望。","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"清心悦行","city":"哈尔滨市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍】字数： &nbsp; &nbsp; \r\n大家好，我是清心悦行，这名字的意思是知则心智清明，行则怀抱喜悦。接下来，我给大家带来的拆页就是一个帮助你知行合一的片段。\r\n结束时间：\r\n【图书介绍】字数： 408字 &nbsp; &nbsp;\r\n【F】今天给大家带来的是心理学家厄廷根——《woop思维心理学》，里面专门讲解了帮助目标达成的心理技术woop。这个方法大名鼎鼎，很多小伙伴可能都听说过，甚至操作过。不要听到心理技术就被吓到，以为只有专业人士才能操作，实际上这就是为我们普通人设计的，里面的解决的问题诸如减肥之类都是大家关心的实际生活问题。&nbsp;\u003c/p>\u003cp>【A】它有名的一个很重要的原因就是简单却很有效果，也许是感觉太简单了，有不少转介绍的文章或者书籍常常语焉不详，甚至存在错误。而误用会直接导致woop方法完全失效。&nbsp;\u003c/p>\u003cp>【B】厄廷根的实验表明一次正确的woop，带来的自我改变，在两年之后仍然可以显示影响力。人最难的事情是自我改变，过去在心理学领域有各种方法来实现自我改变，但是无论何种方法，始终强调你要改变自己的认知方式。如果你经历过这样过程，就知道改变自我认识是一件很痛苦的事情，这需要你进行严厉的自我剖析，以及艰难的自我说服。而woop无疑是一个救星，它帮助我们直接绕过这个过程，直达潜意识的影响行动，透过行动反过来影响我们的显意识，相互促进，达成愿望。\r\n听起来这么厉害的方法，操作起来却比很多速成教程更为简单易用，大家有没有点急不可耐想要阅读原文呢？\r\n结束时间：\r\n【学习目标】字数：73字 \r\n先别着急，阅读之前，先讲几点注意事项，\r\n第一项，woop的方法有很多用法，今天我们学习的目标是使用woop的方法，来达成生活中的略有困难，但是却能够完成的任务。\r\n用时：3′19″\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":9707,"quote":"\u003cp>R 字数：158字（预计总时长：3分钟）\u003c/p>\u003cp>第二项，这段拆页略微有点长，但是步骤简单清晰，大家读的时候，可以用笔标注你关注的地方，还可以在旁边写上简单的词来记录当时读的时候的感受，不要写大段的话，用几个词助记就可以。\u003c/p>\u003cp>最后，有没有小伙伴以前运用过woop的方法，或者在其他地方读过woop方法，请举手。好的，建议你们重点关注一下第二个O障碍部分，比较一下这里面有哪些特别点。\u003c/p>\u003cp>W：愿望或心事。放松，深呼吸，想一个私人或工作方面的愿望或牵挂，虽然有些棘手但你觉得能够达成。它可以是你打算在当天 、本周、本月、本年之内要达成的，只要是你想要woop的愿望都可以。如果同一时间段内有好几个愿望，那就选一个对你而言最重要的，然后把件事放在思考的中心。\u003c/p>\u003cp>O： 结果。你实现愿望或解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。任思绪驰聘，不要有顾虑。不要着急，慢慢来，要是喜欢的活，可以闭上眼睛。\u003c/p>\u003cp>做好准备之后，挣开眼晴，进入下一个步骤：\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？是不是某种习惯或先入为主的想法？在思索障碍的时候，人们往往会在外部寻找， 把&quot;罪名“扣在他们自认为妨碍了他们的外部条件或人的头上。但是，通过选取一个我们认为可以达成的愿望这种做法，就把外部障碍考虑在内了 （要是外部障碍过大，我们就不会认为此愿望是&quot;可以达成“ 的了） 这一练习的目的是防止我们在追逐梦想的路上自己绊倒自己。\u003c/p>\u003cp>在筛选障碍的时候，有一点很重要，那就是深挖细剖，找到那个对你来说最关键的障碍。根据情况的不同，这个障碍可能是很具体的，如&quot;玩了太长时间电脑&quot;；也可能是很普遍的，如&quot;累&quot;或 者&quot;紧张&quot;；可以是某种行力，某种情绪，某种观念，某种冲动， 某个恶习，某种猜测；也可以是某种愚蠢而无用的作为。有时候， 你需要动脑和耐心才能找到真正的内部障碍，发现自己的行为或反应是毫无建树的。刚开始的时候，可能很难把这一过程坚持下去， 因为人们都不愿真诚地剖析自己；但若是能找到最关键的障碍，就一定会有回报。这件事并不像看上去那么难，并且，很多人都觉得， 在完成这个步骤之后他们会产生满足感，甚至觉得如释重负。有时候，在此过程中你还会发现一些自己从未想过或此前无法理解的东西。 在找出了障碍之后，你就获得了德国人所说的Durchblick，在这里指的是对你的愿望、心事，或生活中的某个方面有了一个新的、更清晰的鸟瞰。把这个障碍放在思考的中心，然后用心思考，尽量生动形象的对其相关情况和经历展开想象。让思想自由驰聘，不要有顾虑，不要拘束思路。如果喜欢的话，可以闭上眼睛。\u003c/p>\u003cp>完成上面的步骤之后，就可以进入第四个步骤了：\u003c/p>\u003cp>P：计划。要克服或规避这个障碍的话，你能怎么做?想一个—最有效的那个——想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制订一个&quot;如果……那么…”计划：&quot;如果障碍X出现了 （何时何地），那么我就采取行动Y。”然后将这个计划重复一遍给自己听\u003c/p>\u003cp>就这样。完成。是不是很简单？这种练习你想隔多长时间做一次都可以，只要能有个身心清净的地方就行，你可以坐在火车上、飞机上闭上眼睛坐woop。在等待同事而感到无聊时也可以做，早晨醒来，晚上睡前也行，把woop养成习惯，当然压力大的时候在解决棘手而解决办法尚不明朗的时候，也要用它。\u003c/p>\u003cp>用时：2′56″\u003c/p>","explains":"\u003cp>I 字数： &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>【Why-不这么做的坏处】\u003c/p>\u003cp>【反例】大家生活里面有没有过这样的经历，喜欢一个人，每天都幻想和他在一起的美好画面，然后就是迟迟没有表白，最后不了了之？你不是一个人，厄廷根的实验发现，单纯的乐观幻想，会让我们误以为梦想实现了，就不去做了。她后来的调查分析，发现在生活中自然运用woop的人，按照正确的顺序进行的人只有16%，而40%的人只进行了乐观幻想。而她过去的研究证明，如果顺序错误或者没有进行完整，都无法实现woop的直达潜意识，引发自动化行动的效果。\u003c/p>\u003cp>【how】为了按照四个步骤的正确顺序完整的进行，我们需要首先找到一个安静的，相对不会被打扰的环境。\u003c/p>\u003cp>第一步，找到一个愿望或者心事。【what-适用边界】这个愿望要求首先不超过一年。其次有点难度，但是你觉得自己可以达成的。\u003c/p>\u003cp>举个自己的例子，我要坚持做一年的断舍离笔记。这个肯定可以做，但是这个对于长期处于混乱生活的我，是有点小困难的。这就是一个符合要求的目标。\u003c/p>\u003cp>第二步，想象美好的未来。继续刚才的例子，我会想象经过断舍离之后，家务更好做了，生活变得简单干脆，我的内心慢慢的发生了变化，不再将就不好的生活。诸如此类，可以任意想象，不需要限制时间和内容。\u003c/p>\u003cp>第三步，找出关键障碍。这是被误用最多的woop步骤。这一步可以细分为两小步，第一步要尽可能想象可能的障碍，内外部都可以，没有限制。第二步要找出最麻烦的，最严重的，并且这个障碍是一个你内心的障碍，不是外部世界的障碍。很多误用的人都不做第二小步，找出关键的内心障碍。\u003c/p>\u003cp>那么我的内心障碍有什么呢？诸如没时间，精力不足，不爱做家务等等，这里面最严重的是什么呢？最严重的是自我苛责的恶性循环，一旦感觉疲倦乏力，不想进行，休息一会儿，就陷入到了责备自己无能中，情绪变得更糟糕，更不想行动的恶性循环。\u003c/p>\u003cp>第四步，针对关键障碍设计一个“如果那么”执行意图。\u003c/p>\u003cp>上面的例子中，我会建立这样一个执行意图“如果我再次感到疲倦或者无力感，做不下去事情，那么我要对自己说，太好了，我又有一个机会休息一下，整理思路，不断改进自己了。”\u003c/p>\u003cp>I用时：3′38″\u003c/p>","interaction":"\u003cp>A1&nbsp; 字数\u003c/p>\u003cp>【指令】woop步骤就讲完了，到底学没有学会，我们来用一下看看。刚刚过完十一假期，我想请假期计划全部完成的小伙伴举手？看来大家都没有完成，那么小伙伴们，请回忆下都有哪些计划没有完成呢？跟大家分享一下。\u003c/p>\u003cp>【学员分享】\u003c/p>\u003cp>谢莹：我陪着孩子好几天，休息下来，打开电脑准备写论文。坐下来就想这两天光陪她了累死我了，我还是看会儿小说吧，结果看了一天什么也没做。\u003c/p>\u003cp>&nbsp;A1+ 字数：\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>好的，现在我们学习了woop方法，假如穿越回十一之前，你们做计划的时候，你会怎么办呢？你打算如何运用woop的方法帮你达成计划呢？\u003c/p>\u003cp>【讨论环节】\u003c/p>\u003cp>【案例分享】\u003c/p>\u003cp>谢莹：如果回到十一前，我打算写这个论文。我会首先确定一下我的目标是写论文，然后想一下写这个论文的好处是我能提前开始，会比较有成就感；然后我会想面对的问题可能就是比较懒惰，比较容易分散注意力。这里面的关键的问题是还是不着急，懒惰的问题。最后，定如果那么的话，我会定如果我要是做到电脑前，那么我就开始写论文，不做其他的事情。\u003c/p>\u003cp>结束时间：\u003cbr> 【结束语】字数 &nbsp;\u003c/p>\u003cp>感谢各位小伙伴今天的支持，相信通过今天的学习，如果大家再遇到这样的有点难度，但是却可以达成的小愿望，就可以用woop的方法来进行了。大家回去，可以尝试用书中介绍的方法，去找一个愿望或者心事，如果有很多选一个最想要实现的，严格按照woop步骤去做一下，有什么收获或者困扰，欢迎和我联系。\u003c/p>\u003cp>结束时间：9′43″\u003c/p>\u003cp>总用时：19′43″\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1541489689000,"updated_at":1542789101000,"ria":true},{"id":6016,"topic":"如何分析自己失败的原因","learn_goal":"让学习者能够用这思维方法分析自己在实现小目标所遇到的问题","remark":"是否常常制定了各种计划都没有实现，也找不到自己失败的原因，更无法得到好的结果，在今天我将带领大家学习由加布里埃尔•厄廷根写的《WOOP思维心理学 》，学习一种能够增加执行力的思维方式，让学习者用思维去行动。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"方凯","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;自我介绍：各位伙伴们，大家好，我叫方凯。大家可以叫我小方，现在我是一名准医生，在医院开始我的实习生涯，我的三个标签：准医生，志愿者，拆书小白，准医生是自己对自己的大学生涯的总结；志愿者是自己在大学时光中一直扮演的角色，也是以后自己想要成为的人；拆书小白是自己现阶段的状态。通过这三个标签来提醒自己现在和未来将要做的事情，让自己成为更好的人。我的爱好广泛，平时读读书、打打球、跑跑步。喜欢交友，我的理想状态是：有三两好友，拼搏奋斗。一生足以。现目前最大的愿望是在不久的将来通过自己的努力成为一名三级拆书家。\r\n片段介绍：是否常常制定了各种计划都没有实现，也找不到自己失败的原因，更无法得到好的结果，在今天我将带领大家学习由加布里埃尔•厄廷根写的《WOOP思维心理学》，学习一种能够增加执行力的思维方式，让学习者用思维去行动。&nbsp;\u003c/p>\u003cp>分组：为了更好的学习本片段，要对大家分个组，每三人为一组，接下来会有组内讨论。\u003c/p>\u003cp>闲话不多说，马上开始正文的阅读，请大家花两分钟的时间阅读本章节，读完的小伙伴举手示意下我。\r\n学习目标：让学习者在制定计划遇到障碍的时候能够运用这种方法来分析，解决学习者的障碍。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":9257,"quote":"\u003cp>心理学家加布里埃尔·厄廷根发明了一套能够增加执行力的思维方式，叫做WOOP思维，完成一次WOOP思维只需要十几分钟的时间，却能带来意想不到的收益。过程如下：\u003c/p>\u003cp>\u003cstrong>W：（Wish）愿望。\u003c/strong>放松，深呼吸，想一个你打算在当天、当周、当月或本年之内完成的愿望，并帮他写下来\u003c/p>\u003cp>\u003cstrong>O：（Outcome）结果。\u003c/strong>想象实现愿望之后的最佳结果是什么。尽量生动地想象达到这个愿望以后的经历和感受。\u003c/p>\u003cp>\u003cstrong>O：（Obstacle）障碍。\u003c/strong>有时候，事情并非如你想象的那么顺利，找到那个妨碍你达到愿望的最严重的心理障碍。这个障碍可以是某种行为，某种情绪，某种观点或习惯。重要的是，这个障碍必须是阻碍你行动的真正原因，而不是表面现象，这需要你对自己的行为有深入的了解和剖析。\u003c/p>\u003cp>\u003cstrong>P：（Plan）计划。\u003c/strong>要克服或规避障碍的话，想一个最有效的方法，并把它熟记于心，想想这个障碍出现在何时何地。制定一个“如果……那么……”的计划，如果障碍X出现了（何时何地），那么我就采取计划Y。把这个计划重复一遍给自己听。\u003c/p>\u003cp>WOOP思维被诸多心理学实验证明是切实有效的思维方式。\u003c/p>","explains":"\u003cp>WOOP思维又叫“心理比对”，它以20年的内心动力研究为基础，讲述了一个简单而令人惊讶的理论：我们成长路上的障碍，其实是实现梦想的台阶。使用这种思维模式的时候，我们能够把梦想变成现实，克服在实现梦想道路上所遇到的困难，一路向着梦想飞奔。\u003c/p>\u003cp>第一步，确定愿望。寻找一个你最想实现的愿望。你可以这样问自己：“我内心最想实现的愿望是什么？”如果同时有几个就写下那个对你而言最重要的一个。\u003c/p>\u003cp>第二步，确定结果。问自己，“如果这个愿望实现了，最好的结果是什么？”——尽情畅想愿望达成过后的收获。将这些结果写下来，并给这个结果打分，0~10分，0分不满意，10分特别满意， 8分以上的愿望才是能够激发我们内在动力的愿望，如果不到8分这个愿望可能就需要调整，或者你能想出更好的结果让这个打分超过8分。\u003c/p>\u003cp>第三步，找出障碍。问自己，“是什么妨碍了我们实现愿望？最大的障碍是什么，最本质的障碍是什么？”把他们写下来。本质的意思是什么呢？就是找出障碍之后再多问一下为什么？比如你发现早起的障碍是早上太困起不来，再问一下为什么，就发现本质的障碍可能是你睡得太晚了。我们要把晚睡作为真正的障碍。建议障碍只写1~2个，如果你发现障碍过多或者这个障碍对于你目前的条件来说过大，可能你就需要降低你的愿望，或者延长愿望的达成期限。\u003c/p>\u003cp>第四步，使用“如果，那么”做风险防范计划。问自己，“要克服或者避免这个障碍的话，我该怎么做？”找到最有效的那个方法，制定一个“如果障碍出现，我就采取XX行动去克服\\避免它”的计划。写下来，牢记这个计划。\u003c/p>\u003cp>举个我自己的例子：\u003c/p>\u003cp>我以前回家就想葛优躺，不想运动。\u003c/p>\u003cp>学习了WOOP思维之后，我是这样分析的：\u003c/p>\u003cp>第一步，确定愿望。问自己，“我内心最想实现的愿望是什么？”。我的愿望是，每周花三天晚上去跑步五公里。\u003c/p>\u003cp>第二步，确定结果。问自己，“如果这个愿望实现了，最好的结果是什么？”最好的结果是有一个健康的身体，我给这些结果的满意度打10分。\u003c/p>\u003cp>第三步，找出障碍。问自己，“是什么妨碍了我们实现愿望？最大的障碍是什么，最本质的障碍是什么？”我最大的障碍是“自己觉得很累而不想动”。\u003c/p>\u003cp>第四步，使用“如果，那么”做风险防范计划。问自己，“要克服或者避免这个障碍的话，我该怎么做？”我的计划是“如果那一天很忙，那么我下班后直接就去跑步。”\u003c/p>\u003cp>适用边界：特别强调，WOOP法虽然可以帮我们制定很多愿望的行动计划，但是初学者最好从短期的、更具实质性的、更让你有行动力的愿望开始，等你熟练掌握后再将其应用到更长期、更大的愿望上。\u003c/p>","interaction":"\u003cp>［A1］激活经验\u003c/p>\u003cp>各位小伙伴在以往的经验中是否有过许下的愿望未实现的情形，例如想减肥办了健身卡却没有去过几次健身房。制定了每天打卡学习英语的计划，却做不到。如果有，请与和你一组的小伙伴一起分享下。注意：要有具体的时间，地点，人物，事情，感受。限时3分钟。\u003cbr>\u003c/p>\u003cp>现场伙伴的分享：在去年的时候报名了马拉松半马，制定了每天晚上跑步的计划，遇到的障碍是上班太累太忙，回到家就不想动了，只坚持跑了一个星期就再也没坚持了。感受：我很伤心。\u003c/p>\u003cp>［A2］催化应用\u003c/p>\u003cp>听到各位小伙伴的精彩分享，发现我们还有很多的愿望等待着实现，那今天通过学习这个片段之后。请各位小伙伴用这个思维方法来确定你在未来一周或者一个月的时间内想要实现的愿望，并用上述的方法来分析你在实现愿意的路上如何克服障碍，并且在纸上用“如果，那么”来分析你在实现愿望的过程中对障碍的应对方式。分析的时候注意：要有明确的时间节点、行动步骤。\u003c/p>\u003cp>现场伙伴的分享：\u003c/p>\u003cp>第一步：确定愿望——马拉松全马\u003cbr>\u003c/p>\u003cp>第二步：确定结果——自我成就感\u003c/p>\u003cp>第三步：找出障碍——没时间，上班太累\u003c/p>\u003cp>第四步：使用“如果，那么”做风险防范计划，如果觉得上班太累，没时间跑步，那么就早起三十分钟跑步。\u003c/p>\u003cp>感谢大家的倾听，今天的拆书到此就结束了，希望各位小伙伴都能有所收获。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536327449000,"updated_at":1539058354000,"ria":true},{"id":5969,"topic":"梦想难以实现吗？woop一下","learn_goal":"带领学习者养成woop习惯开始真正的改变","remark":"你最近的计划是什么？你对未来的期待是什么？你想成为什么样的人？想做什么样的工作？想象一下自己梦想成真，达成目标是多么美妙，多么心满意足。那么是什么阻碍你实现了梦想？在你内心深处，是什么绊住了你，使你无法迈开步子？跟随马彬一起，woop一下，养成WOOP的习惯，开始真正的改变。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"miranda","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1、 自我介绍 &nbsp; \r\n大家好，我叫马彬，用一句话希望大家能记住我的名字：马行千里，彬立百川。用一串词形容我自己：互联网产品的拆书家宝妈。 这里含我的三个标签：产品经理，宝妈，拆书家，前两个已为既成事实，我现在是一名互联网公司做运输产品的产品经理，去年刚升级做了宝妈，最后一个也是我现在正在争取的一个标签。\r\n2、 拆书帮介绍 &nbsp;\r\n下面介绍一下拆书帮，首先说拆书，不是把书撕烂，拆书核心就在于是学习者为中心，通过联系自己经验，规划应用，把书上的方法拆为己用。-----【技能点：介绍拆书是什么】\r\n再说帮，帮派，就像天龙八部里的丐帮，其实我们拆书帮的组织架构也跟丐帮比较像，我们的这个组织也有帮主，也有长老，也有小兵，我现就是小兵，一个已入帮很久的小兵。\r\n拆书帮的三个秘密武器就是：----【技能点：介绍拆书帮是什么，让没听过拆书的人也能理解什么是拆书和拆书帮】\r\n1）、个人学习：便签读书法，简称RIA，R就是阅读原文；I就是用自己的语言重述知识；A1：联系自己的相关经验；A2：以后我如何应用；\r\n2）、组织学习： 一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用，我们叫演武场。这个时间可能是2－3小时，也可能是一天的联合拆书形式。\r\n3）、社群学习：就是我们的拆书帮俱乐部，我们拆书帮在全国有很多70多个分舵，通过申请入会的形式，升级打怪成为拆书家。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":9200,"quote":"\u003cp>主题：WOOP工具\u003c/p>\u003cp>书名：《WOOP思维心理学-开启梦想与成功的秘密》\u003c/p>\u003cp>作者：加布里埃尔[美]\u003c/p>\u003cp>在一次研究中，WOOP这个词（即愿望、结果、障碍、计划）四个英文单词的首字母突然蹦了出来，我们喜欢这个词，因为它易于理解，也非常贴合MCII的四个步骤。任何人都可以将WOOP用于自己的生活中，任何目标或者愿望都适用-比如与别人拉近关系，改善健康状况等等。\u003c/p>\u003cp>W:愿望或心事。放松，深呼吸。想一个私人或者工作方面的愿望或者牵挂，虽然有些棘手但你觉得你能够完成。它可以是你打算在当天、本周、本月、本年之内要达成的，只要是你想要WOOP的愿望都可以。\u003c/p>\u003cp>O：结果。你实现愿望或者解决心事之后的最佳结果是什么？想象一下这个结果，将它放在思考的中心。用心去思考，尽量生动形象地想象这件事的相关情况和经历。\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利。你自身的阻力是什么？找到那个妨碍你达成愿望、解决麻烦最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？\u003c/p>\u003cp>P：计划。要克服或者规避这个障碍的话，你能怎么做？想一个最有效的那个-想法或行动，将其牢记于心，然后想一想这个障碍下次出现将是在何时何地。接着制订一下“如果…….那么….”计划：“如果障碍X出现了（何时何地），那么我就采取行动Y。”然后把这个计划重复一遍给自己听。\u003c/p>\u003cp>就这样。完成。是不是很简单？上面介绍的WOOP是在想象中进行的，你也可以用书写的方式来做WOOP。\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>R】阅读原文拆页\u003c/strong>\u003c/p>\u003cp>这个片段其实在教我们一个方法：当我们的梦想\\目标\\愿望无法实现时，WOOP一下。WOOP是（Wish, Outcome, Obstacle，Plan首字母的缩写）那么这四个单词的含义也是这个小工具的四个步骤：----【技能点：I便签中用自己的话重述了原文知识点，清晰易懂】\u003c/p>\u003cp>1）、列出自己一个愿望或者目标；\u003c/p>\u003cp>2）、详细生动形象地想象如果达成这个目标后最理想的结果是什么；\u003c/p>\u003cp>3）、列出实现这个目标的最关键的障碍是什么？\u003c/p>\u003cp>4）、思考要克服这个关键障碍的计划，使用如果遇到了关键障碍….那么我就采取XXX计划...句式警示自己。\u003c/p>","interaction":"\u003cp>\u003cstrong>分享A1便签\u003c/strong>\u003c/p>\u003cp>当我看到这个片段的时候，我想到我最近想要达成的一个愿望：工作的时候少被一些无关思绪带偏，专注于眼前的工作，每天加班时间缩短半小时。\u003c/p>\u003cp>-----【技能点：A1便签中给到了至少一个自己的具体经历，可以是佐证知识点有用的正面实例，也可以是自己之前没能做到所以效果不好的例子。】\u003c/p>\u003cp>先讲一下我的背景：现在工作是在一个创新型部门，去年12月才成立的，公司最近组织结构调整，我从原来的系统规划岗调成运配产品经理岗，因为至少在这一年之内，部门的战略仍然是在仓储产品这块，所以我们运配组所做的产品基本属于前瞻性和创新型的产品建设，正因为是新的东西，没有更多可以参考和借鉴的东西，需要更多专注的时候去深度思考。\u003c/p>\u003cp>以我上周的一天的工作来说，本来早上给自己定了当天的一个任务是：要完成一个重要模块的PRD（产品需求说明书）编写，至少到60%，结果正整理好思路，深入思考的时候，脑子里就想到，早上走的时候，阿妈特意提醒我，娃的尿布湿要没了，赶紧上京东买；正在画流程图的时候，又突然想到有个重要项目还需要研发侧今天必须提交一个东西给我；办完这些事以后，再开始集中画流程，有时不时企业的咚咚又弹出来别人咨询我之前我负责的项目，现在到运维了遇到了问题，然后又帮着她出解决方案；所以到下班的时候，那个模块也只画一个思维导图，整理了一下思路，然后利用下班后自己再加班；一天集中精力的时候非常有限。好像自己本来想干的活反倒没有输出什么实质性的东西，感到比较沮丧。\u003c/p>\u003cp>\u003cstrong>分享A2便签\u003c/strong>\u003c/p>\u003cp>好，那么现在我就WOOP一下。---【A2便签规划了对知识的具体运用，听起来够清晰，能执行】\u003c/p>\u003cp>首先，wish，我的目标是：工作的时候少被一些无关思绪带偏，专注于眼前的工作，提高工作效率，少加班。\u003c/p>\u003cp>其次，outcome想要达成的结果：工作的时候达到一种心流的状态，非常专注。\u003c/p>\u003cp>再次，obstacle最关键的障碍，这里障碍有外界的，也有自己的，但是最关键的障碍还是来自于自身，就是总会被自己的其他思绪带偏；\u003c/p>\u003cp>最后，plan如果遇到正在处理某项需要深度思考的工作被其他思绪带偏的情况下，那么我就采取以下计划：如果我要进入工作，先给自己定25分钟集中精力时间，其他思绪进来的时候，在纸上写上画正字的方式，跑偏一次画一笔。\u003c/p>\u003cp>25分钟结束后，处理思绪中想要做的事。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>总结\u003c/strong>\u003cstrong>&nbsp; &nbsp;\u003c/strong>\u003c/p>\u003cp>最后做一下总结，梦想达不到，目标达不到,WOOP一下，把这种全新的思维方式WOOP养成习惯，开始真正的改变。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1535898519000,"updated_at":1535898636000,"ria":true},{"id":4366,"topic":"WOOP思维，开启你成功的秘密","learn_goal":"学习WOOP步骤，告别积极思维的心灵鸡汤","remark":"我们渴望实现自己的愿望，过上自己想要的生活。但是现实生活中，我们的愿望往往很难实现。为什么呢？因为在愿望面前，我们很容易陷入乐观幻想却不行动的问题中，然后愿望停留在脑海，无法落地。\r\n那么如何才能增加愿望实现的可能呢？本周日馒头带你一起学习WOOP思维，帮你告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变。","level":"TF3-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"馒头","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是拆书家馒头。近期在专注于WOOP思维练习，在自媒体上发布了2篇关于woop思维的文章，累计阅读量上万+。下面给大家分一下组，对面2人为一组。\r\n图书介绍（1.5min）\r\n【事件】\r\n2017年新年的钟声敲响，伴随着新年的钟声，我们闭上眼睛，许下新年的愿望。我要升职加薪，然后去国外旅游；我要找到理想伴侣，谈一场甜蜜的恋爱；我要健身减肥，拥有迷人的身材等等。在幻想新年愿望的过程中，我们陶醉其中，脸上挂着幸福的表情，整个人都飘飘然。然而半年过去了，年初的愿望依旧停留在闹海中，没有落地。\r\n【提问】\r\n是什么阻碍了你实现愿望呢？除了乐观幻想外，你是不是没有想过实现愿望的障碍和计划呢？\r\n【影响】\r\n可能有很多小伙伴的愿望还只是停留在幻想中，并没有落地。想并意味着做。在愿望面前，我们很容易陷入乐观幻想却不行动的问题中。这会导致我们无法实现梦想，不能过上自己想要的生活，从而影响我们的幸福程度。\r\n【解决】\r\n《WOOP思维心理学》，这本书提出科学的WOOP思维训练法，愿望-结果-障碍-计划，\r\n能够帮你告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变。","ratings_count":0,"texts":[{"id":7369,"quote":null,"explains":"\u003cp>原文中向我们介绍了一个思维工具WOOP。我们先来解释下，什么是WOOP思维。WOOP思维是帮助我们实现目标和愿望的工具，它包括愿望、结果、障碍、计划4步。WOOP思维跟目标导向不一样。目标导向是实现这个目标，我们需要做哪些实际工作，没有包括找到实现目标的内心障碍及如何克服障碍。而WOOP思维需要我们找到实现目标的内心障碍，并根据障碍，提前制定一个“如果……那么……”的预演计划。\u003c/p>\u003cp>比如，为了实现拆书过级的目标，woop思维要求我们找到内心拆书过级的障碍，比如不自信、紧张、担心招到质疑等，然后制定出如果紧张，那么我就喝口水、深呼吸的计划。而目标导向则是实现拆书过级的目标，我们需要认真看拆书手册、准备拆书预备表等。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>拿我自己来说，在拆2-3时，我失败了2次，在第3次才顺利通过。\u003c/p>\u003cp>第1次拆2-3时，想当然认为自己能够表现不错，1次性通过2-3。根据WOOP思维工具来对比，表现不错是我想要的愿望，顺利通过2-3是我想要的结果。有了愿望和结果，但是却没有考虑自己内心的障碍。其实对于拆书，我内心一直是不自信的。因为在拆1-1时，就准备了2次预备表。那时我就觉得拆书对于自己是一个非常难的事情。\u003c/p>\u003cp>第2次拆2-3，意识到了内心对于拆书不自信的障碍。根据WOOP思维工具对比，我有了愿望、结果，也考虑到了障碍，但是并没有根据障碍制定出计划。如果拆书时我不自信，那么该怎么克服呢？我没有一个“如果……那么……”的克服障碍计划。\u003c/p>\u003cp>第3次拆2-3，根据书中WOOP思维的4个步骤来准备拆书，最后顺利通过了2-3。我是这么来做的。\u003c/p>\u003cp>【细分步骤】\u003c/p>\u003cp>a/明确自己的愿望\u003c/p>\u003cp>先放松自己，想象拆2-3的愿望。我希望在拆书现场，能够自信、流畅的表达出自己对书中知识的理解，不仅让学习者听明白，还能展现出自信、阳光的自己。\u003c/p>\u003cp>b/思考实现愿望后的最佳结果\u003c/p>\u003cp>实现愿望后的最佳结果是什么呢？想象拆2-3的过程和结果。我希望学习者能够掌握分享的知识点，同时自己也能顺利通过2-3。\u003c/p>\u003cp>c/找到实现愿望的内心障碍\u003c/p>\u003cp>这一步，需要开始理性分析。我内心最大的障碍就是不自信，1-1的打击再加上2-3失败2次，让自己觉得拆书好难，怀疑自己不擅长拆书，没有拆书的天分。\u003c/p>\u003cp>d/根据障碍，制定一个“如果……那么……”计划\u003c/p>\u003cp>如何解决不自信的障碍呢？从TED演讲上找到了一个有效的方法。如果在拆书时不自信，那么我就给自己进行心理暗示。我想顺利通过2-3，我已经通过了2-3，我正在通过2-3。这样心理暗示后，让自己快速进入已经通过2-3的状态，从而拥有自信。\u003c/p>\u003cp>从我刚才列举的拆书案例中，可以发现WOOP思维的4个步骤（愿望、结果、障碍、计划）有明确的先后逻辑顺序，我们需要根据顺序来练习。\u003c/p>\u003cp>【适用范围】\u003c/p>\u003cp>经过自己多次练习后，发现 WOOP思维工具更适合有挑战的目标和愿望，而对于自己力所能及的目标就不需要使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>催化应用（7.5min+4min）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>下面我们进入催化应用环节。\u003c/p>\u003cp>刚刚跟大家分享了如何运用WOOP思维的4个步骤，制定出解决愿望障碍的计划。\u003c/p>\u003cp>为了帮助大家更好地掌握和运用WOOP思维，接下来在请大家编一个剧本。当你身边的小伙伴，在实现愿望的过程中，出现乐观幻想却行动失败时，你会如何运用今天学习的WOOP思维，帮助他制定出克服内心障碍的计划呢？\u003c/p>\u003cp>要有具体的时间，地点，人物，起因经过结果的小故事，并且要有对话，给大家7分钟的时间讨论。3个人为一组，其中1个小伙伴是当事人，1个小伙伴为咨询师运用WOOP思维给他出谋划策，另1位小伙伴监督这个故事是否包含时间、地点、人物起因经过结果和对话。\u003c/p>\u003cp>编剧本的过程，WOOP思维的4个步骤会在你大脑中过1遍，就相当于你在实际中运用了一遍哦。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>【给予分享者反馈】\u003c/p>\u003cp>非常感谢学习者的精彩分享，通过运用WOOP思维的4个步骤，帮助**制定了克服内心障碍的计划。\u003c/p>\u003cp>\u003cstrong>7\u003c/strong>\u003cstrong>、结语（0.5min）\u003c/strong>\u003c/p>\u003cp>最后，希望今天分享的WOOP思维，能够帮助大家更好的实现愿望，获得成功。我是今天的拆书家馒头，谢谢大家的聆听和陪伴。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514893708000,"updated_at":1514893734000},{"id":4365,"topic":"WOOP思维，开启你成功的秘密！","learn_goal":"告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变","remark":"我们渴望实现自己的愿望，过上自己想要的生活。但是现实生活中，我们的愿望往往很难实现。为什么呢？因为在愿望面前，我们很容易陷入乐观幻想却不行动的问题中，然后愿望停留在脑海，无法落地。\r\n那么如何才能增加愿望实现的可能呢？本周日馒头带你一起学习WOOP思维，帮你告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"馒头","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是拆书家馒头。近期在专注于WOOP思维练习，在自媒体上发布了2篇关于woop思维的文章，累计阅读量上万+。下面给大家分一下组，对面2人为一组。\r\n图书介绍（1.5min）\r\n【事件】\r\n2017年新年的钟声敲响，伴随着新年的钟声，我们闭上眼睛，许下新年的愿望。我要升职加薪，然后去国外旅游；我要找到理想伴侣，谈一场甜蜜的恋爱；我要健身减肥，拥有迷人的身材等等。在幻想新年愿望的过程中，我们陶醉其中，脸上挂着幸福的表情，整个人都飘飘然。然而半年过去了，年初的愿望依旧停留在闹海中，没有落地。\r\n【提问】\r\n是什么阻碍了你实现愿望呢？除了乐观幻想外，你是不是没有想过实现愿望的障碍和计划呢？\r\n【影响】\r\n可能有很多小伙伴的愿望还只是停留在幻想中，并没有落地。想并意味着做。在愿望面前，我们很容易陷入乐观幻想却不行动的问题中。这会导致我们无法实现梦想，不能过上自己想要的生活，从而影响我们的幸福程度。\r\n【解决】\r\n《WOOP思维心理学》，这本书提出科学的WOOP思维训练法，愿望-结果-障碍-计划，\r\n能够帮你告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变。","ratings_count":0,"texts":[{"id":7368,"quote":null,"explains":"\u003cp>原文中向我们介绍了一个思维工具WOOP。我们先来解释下，什么是WOOP思维。WOOP思维是帮助我们实现目标和愿望的工具，它包括愿望、结果、障碍、计划4步。WOOP思维跟目标导向不一样。目标导向是实现这个目标，我们需要做哪些实际工作，没有包括找到实现目标的内心障碍及如何克服障碍。而WOOP思维需要我们找到实现目标的内心障碍，并根据障碍，提前制定一个“如果……那么……”的预演计划。\u003c/p>\u003cp>比如，为了实现拆书过级的目标，woop思维要求我们找到内心拆书过级的障碍，比如不自信、紧张、担心招到质疑等，然后制定出如果紧张，那么我就喝口水、深呼吸的计划。而目标导向则是实现拆书过级的目标，我们需要认真看拆书手册、准备拆书预备表等。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>拿我自己来说，在拆2-3时，我失败了2次，在第3次才顺利通过。\u003c/p>\u003cp>第1次拆2-3时，想当然认为自己能够表现不错，1次性通过2-3。根据WOOP思维工具来对比，表现不错是我想要的愿望，顺利通过2-3是我想要的结果。有了愿望和结果，但是却没有考虑自己内心的障碍。其实对于拆书，我内心一直是不自信的。因为在拆1-1时，就准备了2次预备表。那时我就觉得拆书对于自己是一个非常难的事情。\u003c/p>\u003cp>第2次拆2-3，意识到了内心对于拆书不自信的障碍。根据WOOP思维工具对比，我有了愿望、结果，也考虑到了障碍，但是并没有根据障碍制定出计划。如果拆书时我不自信，那么该怎么克服呢？我没有一个“如果……那么……”的克服障碍计划。\u003c/p>\u003cp>第3次拆2-3，根据书中WOOP思维的4个步骤来准备拆书，最后顺利通过了2-3。我是这么来做的。\u003c/p>\u003cp>【细分步骤】\u003c/p>\u003cp>a/明确自己的愿望\u003c/p>\u003cp>先放松自己，想象拆2-3的愿望。我希望在拆书现场，能够自信、流畅的表达出自己对书中知识的理解，不仅让学习者听明白，还能展现出自信、阳光的自己。\u003c/p>\u003cp>b/思考实现愿望后的最佳结果\u003c/p>\u003cp>实现愿望后的最佳结果是什么呢？想象拆2-3的过程和结果。我希望学习者能够掌握分享的知识点，同时自己也能顺利通过2-3。\u003c/p>\u003cp>c/找到实现愿望的内心障碍\u003c/p>\u003cp>这一步，需要开始理性分析。我内心最大的障碍就是不自信，1-1的打击再加上2-3失败2次，让自己觉得拆书好难，怀疑自己不擅长拆书，没有拆书的天分。\u003c/p>\u003cp>d/根据障碍，制定一个“如果……那么……”计划\u003c/p>\u003cp>如何解决不自信的障碍呢？从TED演讲上找到了一个有效的方法。如果在拆书时不自信，那么我就给自己进行心理暗示。我想顺利通过2-3，我已经通过了2-3，我正在通过2-3。这样心理暗示后，让自己快速进入已经通过2-3的状态，从而拥有自信。\u003c/p>\u003cp>从我刚才列举的拆书案例中，可以发现WOOP思维的4个步骤（愿望、结果、障碍、计划）有明确的先后逻辑顺序，我们需要根据顺序来练习。\u003c/p>\u003cp>【适用范围】\u003c/p>\u003cp>经过自己多次练习后，发现 WOOP思维工具更适合有挑战的目标和愿望，而对于自己力所能及的目标就不需要使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>催化应用（7.5min+4min）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>下面我们进入催化应用环节。\u003c/p>\u003cp>刚刚跟大家分享了如何运用WOOP思维的4个步骤，制定出解决愿望障碍的计划。\u003c/p>\u003cp>为了帮助大家更好地掌握和运用WOOP思维，接下来在请大家编一个剧本。当你身边的小伙伴，在实现愿望的过程中，出现乐观幻想却行动失败时，你会如何运用今天学习的WOOP思维，帮助他制定出克服内心障碍的计划呢？\u003c/p>\u003cp>要有具体的时间，地点，人物，起因经过结果的小故事，并且要有对话，给大家7分钟的时间讨论。3个人为一组，其中1个小伙伴是当事人，1个小伙伴为咨询师运用WOOP思维给他出谋划策，另1位小伙伴监督这个故事是否包含时间、地点、人物起因经过结果和对话。\u003c/p>\u003cp>编剧本的过程，WOOP思维的4个步骤会在你大脑中过1遍，就相当于你在实际中运用了一遍哦。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>【给予分享者反馈】\u003c/p>\u003cp>非常感谢学习者的精彩分享，通过运用WOOP思维的4个步骤，帮助**制定了克服内心障碍的计划。\u003c/p>\u003cp>\u003cstrong>结语（0.5min）\u003c/strong>\u003c/p>\u003cp>最后，希望今天分享的WOOP思维，能够帮助大家更好的实现愿望，获得成功。我是今天的拆书家馒头，谢谢大家的聆听和陪伴。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514893590000,"updated_at":1514893590000},{"id":3029,"topic":"WOOP思维，开启你成功的秘密！","learn_goal":"学习WOOP思维，告别积极思维的心灵鸡汤，开启梦想与成功","remark":"我们渴望实现自己的愿望，过上自己想要的生活。但是现实生活中，我们的愿望往往很难实现。为什么呢？因为在愿望面前，我们很容易陷入乐观幻想却不行动的问题中，然后愿望停留在脑海，无法落地。\r\n那么如何才能增加愿望实现的可能呢？本周日馒头带你一起学习WOOP思维，帮你告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变。","level":"TF3-1","duration":25,"status":29,"type":0,"chaishujia":{"username":"馒头","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者能够使用（行为）WOOP思维的4个步骤（澄清），制定出“如果……那么……”的解决愿望障碍计划（界定）。 \u003c/p>\u003cp>a/明确自己的愿望\u003c/p>\u003cp>b/思考实现愿望后的最佳结果\u003c/p>\u003cp>c/找到实现愿望的内心障碍\u003c/p>\u003cp>d/根据障碍，制定一个“如果……那么……”计划\u003c/p>\u003cp>开场：\u003c/p>\u003cp>大家好，我是拆书家馒头。近期在专注于WOOP思维练习，在自媒体上发布了2篇关于woop思维的文章，累计阅读量上万+。下面给大家分一下组，对面2人为一组。\r\n图书介绍（1.5min）\r\n【事件】\r\n2017年新年的钟声敲响，伴随着新年的钟声，我们闭上眼睛，许下新年的愿望。我要升职加薪，然后去国外旅游；我要找到理想伴侣，谈一场甜蜜的恋爱；我要健身减肥，拥有迷人的身材等等。在幻想新年愿望的过程中，我们陶醉其中，脸上挂着幸福的表情，整个人都飘飘然。然而半年过去了，年初的愿望依旧停留在闹海中，没有落地。\r\n【提问】\r\n是什么阻碍了你实现愿望呢？除了乐观幻想外，你是不是没有想过实现愿望的障碍和计划呢？\r\n【影响】\r\n可能有很多小伙伴的愿望还只是停留在幻想中，并没有落地。想并意味着做。在愿望面前，我们很容易陷入乐观幻想却不行动的问题中。这会导致我们无法实现梦想，不能过上自己想要的生活，从而影响我们的幸福程度。\r\n【解决】\r\n《WOOP思维心理学》，这本书提出科学的WOOP思维训练法，愿望-结果-障碍-计划，\r\n能够帮你告别积极思维的心灵鸡汤，开启梦想与成功的秘密，实现真正的改变。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":5828,"quote":null,"explains":"\u003cp>原文中向我们介绍了一个思维工具WOOP。我们先来解释下，什么是WOOP思维。WOOP思维是帮助我们实现目标和愿望的工具，它包括愿望、结果、障碍、计划4步。\u003c/p>\u003cp>【概念对比】\u003c/p>\u003cp>WOOP思维跟目标导向不一样。目标导向是实现这个目标，我们需要做哪些实际工作，没有包括找到实现目标的内心障碍及如何克服障碍。而WOOP思维需要我们找到实现目标的内心障碍，并根据障碍，提前制定一个“如果……那么……”的预演计划。\u003c/p>\u003cp>比如，为了实现拆书过级的目标，woop思维要求我们找到内心拆书过级的障碍，比如不自信、紧张、担心招到质疑等，然后制定出如果紧张，那么我就喝口水、深呼吸的计划。而目标导向则是实现拆书过级的目标，我们需要认真看拆书手册、准备拆书预备表等。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>拿我自己来说，在拆2-3时，我失败了2次，在第3次才顺利通过。\u003c/p>\u003cp>第1次拆2-3时，想当然认为自己能够表现不错，1次性通过2-3。根据WOOP思维工具来对比，表现不错是我想要的愿望，顺利通过2-3是我想要的结果。有了愿望和结果，但是却没有考虑自己内心的障碍。其实对于拆书，我内心一直是不自信的。因为在拆1-1时，就准备了2次预备表。那时我就觉得拆书对于自己是一个非常难的事情。\u003c/p>\u003cp>第2次拆2-3，意识到了内心对于拆书不自信的障碍。根据WOOP思维工具对比，我有了愿望、结果，也考虑到了障碍，但是并没有根据障碍制定出计划。如果拆书时我不自信，那么该怎么克服呢？我没有一个“如果……那么……”的克服障碍计划。\u003c/p>\u003cp>第3次拆2-3，根据书中WOOP思维的4个步骤来准备拆书，最后顺利通过了2-3。我是这么来做的。\u003c/p>\u003cp>【细分步骤】\u003c/p>\u003cp>a/明确自己的愿望\u003c/p>\u003cp>先放松自己，想象拆2-3的愿望。我希望在拆书现场，能够自信、流畅的表达出自己对书中知识的理解，不仅让学习者听明白，还能展现出自信、阳光的自己。\u003c/p>\u003cp>b/思考实现愿望后的最佳结果\u003c/p>\u003cp>实现愿望后的最佳结果是什么呢？想象拆2-3的过程和结果。我希望学习者能够掌握分享的知识点，同时自己也能顺利通过2-3。\u003c/p>\u003cp>c/找到实现愿望的内心障碍\u003c/p>\u003cp>这一步，需要开始理性分析。我内心最大的障碍就是不自信，1-1的打击再加上2-3失败2次，让自己觉得拆书好难，怀疑自己不擅长拆书，没有拆书的天分。\u003c/p>\u003cp>d/根据障碍，制定一个“如果……那么……”计划\u003c/p>\u003cp>如何解决不自信的障碍呢？从TED演讲上找到了一个有效的方法。如果在拆书时不自信，那么我就给自己进行心理暗示。我想顺利通过2-3，我已经通过了2-3，我正在通过2-3。这样心理暗示后，让自己快速进入已经通过2-3的状态，从而拥有自信。\u003c/p>\u003cp>从我刚才列举的拆书案例中，可以发现WOOP思维的4个步骤（愿望、结果、障碍、计划）有明确的先后逻辑顺序，我们需要根据顺序来练习。\u003c/p>\u003cp>【适用范围】\u003c/p>\u003cp>经过自己多次练习后，发现 WOOP思维工具更适合有挑战的目标和愿望，而对于自己力所能及的目标就不需要使用。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】\u003c/p>\u003cp>下面我们进入催化应用环节。\u003c/p>\u003cp>刚刚跟大家分享了如何运用WOOP思维的4个步骤，制定出解决愿望障碍的计划。\u003c/p>\u003cp>为了帮助大家更好地掌握和运用WOOP思维，接下来在请大家编一个剧本。当你身边的小伙伴，在实现愿望的过程中，出现乐观幻想却行动失败时，你会如何运用今天学习的WOOP思维，帮助他制定出克服内心障碍的计划呢？\u003c/p>\u003cp>要有具体的时间，地点，人物，起因经过结果的小故事，并且要有对话，给大家7分钟的时间讨论。编剧本的过程，WOOP思维的4个步骤会在你大脑中过1遍，就相当于你在实际中运用了一遍哦。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者鼓有想减肥的愿望，希望实现减肥愿望后的最佳结果是一年减掉20斤。但是面对减肥的愿望，她怀疑自己不可能做到，对减肥成功没信心。因为减掉20斤太难了，需要克服各种美食诱惑。针对减肥畏难、不自信的内心障碍，鼓制定出了一个计划。如果怀疑自己减肥20斤不成功、对自己减肥没信心，那么就暗示自己只要坚持运动就会有效果。\u003c/p>\u003cp>【给予分享者反馈】\u003c/p>\u003cp>非常感谢学习者的精彩分享，通过运用WOOP思维的4个步骤，制定了克服内心减肥的障碍计划。\u003c/p>\u003cp>最后，希望今天分享的WOOP思维，能够帮助大家更好的实现愿望，获得成功。我是今天的拆书家馒头，谢谢大家的聆听和陪伴。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1498400418000,"updated_at":1526181410000},{"id":2079,"topic":"WOOP四步法则","learn_goal":"学会应用woop思维四步法制定计划","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"意为安","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"大家好，我是拆书家意为安。通常，我给自己的三个标签是演说教练、拆书家和家庭系统成长教练。而针对今天，我想给自己一个标签：收获。希望今天能有所收获，也希望各位能从我的分享中有所收获。我今天要完成的目标是TF1-2。是一级拆书家的第二个项目。待会在我的分享过程中会有小组讨论的环节，所以呢我们现在先来分组，为了尽可能让大家都有时间有机会分享，我们三个人一组。\r\n今天我带来的这本书是《WOOP思维心理学》该书的作者加布里埃尔•厄廷根教授用了20多年时间研究我们完成目标或愿望的内心动力，提出了一种全新的思维方式，这种思维方式他将其命名为“WOOP”，这是四个英文单词的首字母缩写。该书对我们如何在日常生活中使用这种思维方式提供了具体建议和练习方法。\r\n通过这种思维方式，人们在戒烟、减肥、提高学习成绩、培养良好的人际关系等等方面都有了显著转变。\r\n所以不论你是正在应对棘手的问题，还是只是想有所改善、有所发现，本书都将会加深你对人类内心动力的理解，帮助你无所畏惧地绘制出你的前进路线。","ratings_count":0,"texts":[{"id":4715,"quote":"\u003cp>今天我要跟大家分享的片段是“WOOP步骤”。希望我们今天学习了这个“WOOP步骤”以后都能绘制出我们自己的向愿望达成而前进的路线。我已经把这个片段发在了学习群里，1分钟之内应该可以读完，完成的请示意我。\u003c/p>","explains":"\u003cp>好，大部分伙伴已经读完了。没有读完也不要紧。我来给大家介绍一下。“WOOP”，这是四个英文单词的首字母缩写。\u003c/p>\u003cp>W，wish，是指愿望；第一个O，Outcome，指愿望实现后的结果；第二个O是Obstacle，实现愿望的障碍；最后的P，Plan，是指我们克服障碍的计划。它能够帮助你梳理你的愿望及愿望对你的重要性，帮助你预想障碍并制定克服计划。最终帮助我们达成愿望。\u003c/p>\u003cp>首先是W，第一步确定愿望。这个愿望和目标不要太宏大，比如你希望世界和平，那在今天的学习中我可帮不了你。你的愿望和目标要具体，并且在客观上来说是能达成的。比如，可以是每个月读完一本书；或者是每周坚持一次有氧运动；\u003c/p>\u003cp>然后第二步O，评估结果。我们可以对愿望实现后的结果做一个量化评分。1-10分，1分代表其实不完成也无所谓，10分代表完成后会非常高兴，非常兴奋，非常重要，非常有成就感。你可以根据自己的情况对你的愿望或目标做一个想象评分，一般来说7分以上我们可以视为有足够的动机来行动；\u003c/p>\u003cp>第三步O，设想障碍。设想我们在实现愿望完成目标的过程中有可能遭遇的关键障碍，设想1-3个就好。\u003c/p>\u003cp>第四步P，制定计划。对于第三步设想的障碍，我们要制定一个“如果出现障碍X，那么我就采取行动Y”的计划。\u003c/p>\u003cp>我相信通过这四个步骤可以帮助我们绘制达成愿望的前进路线。我自己之前有一个愿望没有达成，那就是英语口语100天提升的愿望。然后我学了这个WOOP四步骤以后，根据这四个步骤我反思了一下。第一步，确定愿望。我是很明确的，具体的，客观可达成的100天英语口语提升；而第二步，评估结果。我当时是没有评估的，只是隐约觉得自己会很满意，对此的重要程度价值程度没有直观显性的认识；第三步，设想障碍。我没有去预想可能会遇到了障碍，事实上正是这些障碍使得我的愿望没有达成，比如时间冲突，没有同伴等。我没有设想障碍就更谈不上第四步为克服障碍制定计划，因此，100天早就过去了，我的愿望没有达成。\u003c/p>","interaction":"\u003cp>\u003cbr>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】激活经验\u003c/strong>\u003c/p>\u003cp>那么这是我使用WOOP步骤来反思自己愿望没有达成的例子。我想大家都有过一些经历，比如一直在制定目标的路上，仿佛从来也无法确认它达成它。发生这种情况的原因有很多，当然你也会有一些成功达成愿望的经验。下面就请各位想一想在过去，你有没有什么想要实现达成的愿望或目标，然后我们根据WOOP四个步骤来进行反思，我们的愿望没有实现是哪一步做得不够，而达成了目标又是怎么做到的呢？能否在我们的这个WOOP中找到对应的经验？请大家按照我们刚才分组的情况，在小组内和小伙伴分享你过往的经验或者经历。\u003c/p>\u003cp>讨论时间到，下面我们请一个小伙伴来分享一下她的经验或经历。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者A：\u003c/strong>愿望成功达成。确定愿望是到云南旅游；评估结果是9分；障碍是1可能没有时间,2可能找不到同伴，同时担心云南的天气；最后是找了一个工作不太忙的时间向领导请假，然后同时找了一个同样时间比较有空的同伴一起前往，提前咨询了云南当地伙伴天气情况。\u003c/p>\u003cp>\u003cstrong>学习者B：\u003c/strong>愿望成功达成。确定愿望是减肥；觉得对自己很重要；障碍是怕自己无法坚持节食，后来发现比想象中容易，晚饭可以坚持不吃或只吃素菜，坚持了两个月就瘦下来了。\u003c/p>\u003cp>\u003cstrong>学习者C：\u003c/strong>愿望没有达成。确定愿望是坚持写书；评估结果是很重要；没有设想障碍，只坚持了半年就坚持不下去了。\u003c/p>\u003cp>\u003cstrong>学习者D：\u003c/strong>愿望没有达成。确定愿望是完成TF3-3；评估结果是非常重要；障碍就是学习者的水平层次不同，有的拆页内容学习者会觉得简单，有的又会觉得很难，很难把握；没有明确的计划。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】催化应用\u003c/strong>\u003c/p>\u003cp>感谢刘华的分享。下面请大家试着来运用一下WOOP这四个步骤，用1分钟的时间写一下你在接下来的一段时间想要达成的愿望，评估一下愿望完成后的结果，设想一下可能会遇到的关键障碍，1-3个即可；并且制定克服这些障碍的计划。比如你的愿望可以是半年内练成马甲线又或者是今年内出去旅游一次，等等。我把四个步骤和建议的书写模板已经发到了学习群里，大家可以参考。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者A：\u003c/strong>愿望：每周锻炼3小时，每周有3次锻炼，每次1小时；结果：7分；障碍：加班；计划：如果加班，我就在马路上跑；如果加班，我就在周末白天跑。\u003c/p>\u003cp>\u003cstrong>学习者B：\u003c/strong>愿望：赋能班；结果：10分；障碍：能力不足以吸收学员；计划：提升自己的能力。\u003c/p>\u003cp>\u003cstrong>学习者C：\u003c/strong>愿望：100天练成三级拆书家；结果：10分；障碍：1、时间冲突，2、找不到合适的拆页，3、技能要点不能及时掌握；计划：1、如果时间冲突，那么优先选择拆书；2、如果找不到合适的拆页，那么就选择其他同伴的合适拆页来拆解；3、如果技能要点不能及时掌握，那么就重复拆解直到掌握，愿望实现时间可以延长一个月。\u003c/p>\u003cp>\u003cstrong>学习者D：\u003c/strong>愿望：坚持写作；结果：9分；障碍：下班太晚太累就不想写了；计划：如果下班太晚太累，无论如何也要写完才睡觉。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488684759000,"updated_at":1488685955000,"ria":true},{"id":1514,"topic":"如何用WOOP思维工具实现一个小目标","learn_goal":"通过练习WOOP思维工具的4个小步骤，规划一周内要达成小目标","remark":"在10-15分钟内讲解WOOP思维的四个关键步骤：愿望、结果、障碍、计划，通过练习这个工具的方法，规划实现一周内达成一个小目标的行动计划。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"夏彼得","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是夏彼得，今天是我第二次拆书，第一次手里什么也没拿（脱稿）。我要给大家报告一个好消息，我已经把今天定为家庭的成长日。因为上午我老婆用4个小时画了2幅油画，我女儿下午在幼儿园做了她人生中第一次画展的ppt演讲，此时此刻我在这里进行1-2的拆书，我已经用实际行动影响了我的家庭，希望在翰林分舵成长为一名更有影响力的学习促进者，影响更多人。\r\n今天我带来的书籍是《WOOP思维心理学》，作者厄廷根是美国著名的心理学家，她通过大量的实验，帮我们找到一个实现梦想的思维工具——WOOP。今天我们将学习和练习这个方法来帮助我们实现一个小目标。请大家阅读一下拆页横线以上的文字，阅读完以后可以抬头示意我。","ratings_count":0,"texts":[{"id":4043,"quote":"\u003cp>WOOP是：愿望（Wish）、结果（Outcome）、障碍(Obstacle)、计划(Plan)四个英文单词的首字母，任何人都可以将WOOP用在自己的生活中，任何目标和愿望都适用。现在，我先带领大家做一个详尽的练习。\u003c/p>\u003cp>W：愿望或心思。想一个私人或工作方面的愿望或者牵挂，虽然有些棘手但你觉得能够达成。他可以是你打算在当天、本周、本月、本年之内要达成的，只要是你想要WOOP的愿望都可以。\u003c/p>\u003cp>O：结果。你实现愿望或解决心事之后的最佳结果是什么？\u003c/p>\u003cp>O：障碍。有时候事情并不像我们预想的那样顺利，你自身的阻力事什么？真的吗？找到那个妨碍你达成愿望、解决麻烦的最严重的、内心的障碍。这个障碍里最关键的想法和行为是什么？是不是某种习惯或者先入为主的想法？\u003c/p>\u003cp>P:计划。要克服或规避这个障碍的话，你能怎么做？想一个——最有效的那个——想法或行动，将其牢记在心，然后想一想这个障碍下次出现是在何时何地。接着制订一个“如果……那么……”计划：“如果障碍X出现了（何时何地），那么我就采取行动Y。”\u003c/p>","explains":"\u003cp>我看小伙伴们基本都阅读完了，先跟大家报告一个不好的消息，过完今晚距离2017年只剩下46天了，各位小伙伴年初许下的愿望还有多少没有实现呢？幸运的是我们还有46天，那么在接下来的日子里我们还可以达成一些小目标，更加幸运的是今天这本书带来了方法-\u003cstrong>WOOP\u003c/strong>。它是四个英文单词的首字母缩写，就是“愿望（Wish）、结果（Outcome）、障碍(Obstacle)、计划(Plan)”，也是实现梦想的四个步骤。\u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>设定一个在工作或生活中你想实现的愿望，要具有一点挑战性、可达成，还要有时间期限，听起来有点像SMART原则。&nbsp;\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>展望达成目标的画面和感受。\u003c/p>\u003cp>\u003cstrong>第三步：\u003c/strong>回到现实，从内心去发现可能会阻碍愿望实现的那个最大、最严重的障碍，记录下障碍出现的时候，你的关键想法和行动是什么。\u003c/p>\u003cp>\u003cstrong>第四步：\u003c/strong>我们要制订一个行动计划，当这个障碍下一次在何时、何地出现的时候，我们要采取一个新的行动来代替它。\u003c/p>\u003cp>我举一个自己的小案例来示范这个方法：7月份我学会游泳后订了一个小目标：每周六去健身房游泳1小时，我想到的是每次游完泳后都会感觉神清气爽、心情非常好，可是到现在我只去过1、2次，回想一下我失败的原因，每周六当我醒来的时候，一想到要收拾游泳的衣服、开车去健身房，我的大脑就命令我：那个事情太麻烦了，于是它指挥我继续躺在温暖的被窝里，我被这个关键障碍打败了。学完这个片段的知识后，这周六我就可以这么做，“如果这周六早上我醒来的时候，大脑发出’开车去游泳太麻烦了，还是在家睡觉吧’这个信号，我就立即起床收拾泳衣、把车钥匙放在旁边”。\u003c/p>","interaction":"\u003cp>\u003cstrong>学习者分享的愿望是：减肥，最大的障碍是：内心的“小怪物”\u003c/strong>\u003c/p>\u003cp>困扰了我很久的问题就是减肥，每一次和拆书家一起拆书的时候，我都发现拆书家的方法都特别好用，我想回家把它用起来，马上用起来，但是等到我真正实施的时候，我内心的“小恶魔”突然间跑出来跟我说：这顿吃了也没有事，下顿再减吧。运动的时候，我会想今天早上有点累，晚上等老公一起回来去健身房，晚上的时候内心的“小怪兽”又跑出来了，当老公说去健身的时候，我说不行啊今天太累了不想去。日复一日、年复一年，我今年3月份励志减肥，结果到现在发现去年能穿的衣服今年都穿不上了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480737713000,"updated_at":1480737752000,"ria":true},{"id":879,"topic":"四个步骤，让你无压前行","learn_goal":"挑战1-2","remark":"面对世间繁杂，有木有一种身体被掏空的感觉？\r\n面对各种事项，有木有一种想一直葛优瘫的想法？\r\n文武教你四个步骤，让你无压前行。\r\n","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"文武","city":"日照"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是文武，拆书帮海曲筹备分舵代组织长老，我的标签是写作爱好者和自我提升实践者。今天我给大家带来的片段，来自一本书《WOOP思维心理学：开启梦想与成功的秘密》。\r\n通过这种思维方式，在戒烟、减肥、提高学习成绩、培养良好的人际关系、提高商业经营效率等方面都可以取得显著转变。\r\n这本书最近很多大咖都在强烈推荐，就在4天前，曾作为嘉宾参加2015年首届拆书帮年会的百万粉丝微信公众号作者战隼，发微信头条文章《告别心灵鸡汤用科学的思维方式来培养习惯》专门推荐了此书。\r\n本书作者加布里埃尔是一位女心理学家、美国纽约大学及德国汉堡大学心理学教授，她以20余年的科学研究为基础，提出了这个WOOP思维理论。","ratings_count":0,"texts":[{"id":2729,"quote":"\u003cp>如何才能化乐观为动力？综合学界目前流行的“心理对照（mental contrasting）”和“执行意图（Implementation intentions）”理论，提出了一种“WOOP”的方法。\u003c/p>\u003cp>第一步确定愿望（Wish），许下一个你真心渴望的、非常具体的、有挑战性的愿望——譬如说，公开做一个十五分钟的英文演讲。\u003c/p>\u003cp>第二步想象成果（Outcome），想象达到目标后你将如何从中获益——譬如说，英文演讲既锻炼能力，又提升知名度。\u003c/p>\u003cp>前两步不算太难，第三步才是关键，寻找障碍（Obstacle），对比你的现状和你渴望达到的目标，需要弥补哪些差距，可能遭遇哪些挫折，自己的身心状况在努力过程中可能如何波动——需要一个有吸引力的演讲主题，需要约2500单词的演讲稿，单词发音需要矫正，台风需要更加镇定，可能写稿写得沮丧，可能上台前紧张到怯场，可能上了台发现头脑一片空白……\u003c/p>\u003cp>列出所有能想到的障碍后，就轮到第四步具体计划（Plan），计划亦有特殊技巧，一定要采纳“假如处在X状况下，我就采取Y行动”的计划形式——假如晚饭后我在电脑前，我就开始写演讲稿。假如我在地铁上，我就默默背诵说辞。假如我觉得“我的稿子好糟，我不可能讲好”，我就要对自己说“不管怎样，努力后我会比从前更擅长演讲”……\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>日常生活心灵鸡汤常会告诉我们着眼于事物好的一面，在逆境中保持乐观心态，就可以实现梦想。但是多少人的梦想被现实打败了，碾碎了，为什么？”因为执行力，如何化乐观为动力？…… \u003c/p>\u003cp>但实际上，我们通过WOOP思维的四个步骤，呈现出达成目标的画面，也找出要达成目标的障碍，并找出解决办法。这样去行动起来，才能让美梦成真。\u003c/p>\u003cp>下面分享一个我的实践：大家知道我有一个公众号叫“文武来了”，但是更新总是不太及时。我想做到3天一更新，于是我用WOOP了一下。\u003c/p>\u003cp>W:wish（愿望）：八月份起，每三天更新一篇微信文章。\u003c/p>\u003cp>O:outcome（结果）：通过不断地输出，提高自己的写作水平和个人影响力。写的好了，或许可以链接到更大平台，甚至获得出书的机会。\u003c/p>\u003cp>O:obstacle（障碍）：自己想法灵感挺多，但自己内在动力不足，也没有别人的监督。\u003c/p>\u003cp>P:plan（计划）：于是我和一个小伙伴达成了协议。如果我三天不写微信文章，那么就给她发红包。为了面子也得三天一更新啊！如果我不想更新，那么想一下自己的这个承诺，然后乖乖去更新。\u003c/p>\u003cp>再来看下我的一位微信好友“发愤的草莓”如何使用的WOOP，她的愿望是7月份结束时达成5:30起床。于是她这么列出来。\u003c/p>\u003cp>W:wish（愿望）：7月份坚持每周往前挪15分钟起床，直到达成5：30起床。\u003c/p>\u003cp>O:outcome（结果）：每天都可以有将近2小时读书的时间，并且读完好多自己书架上闲置的书籍，写出很多篇读书心得和大家分享，完善自己的知识体系。\u003c/p>\u003cp>O:obstacle（障碍）：目前每晚总是舍不得休息，睡觉前喜欢刷手机朋友圈。\u003c/p>\u003cp>P:plan（计划）：设置每晚10点半响闹钟，如果，那时候打开手机朋友圈，那么，我就把手机直接丢进抽屉并且爬上床。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>&nbsp;&nbsp;&nbsp;大家读完这个拆页并听完我的分享，了解到这四个步骤了吧？那么请大家想想自己有没有经历过类似情景、有没有过相关的经验，比如，自己有很多想去做的事，有些可能是一件小事，有些可能是自己的一些中长期的目标，它一直存在你的待办事项里，但因为你缺少正确的方法，或者只是幻想着它会完成，导致你迟迟未去做，或者你尝试了一些其他的方法，最终以失败告终。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;请大家在小组内分享，时间为2（根据节奏或现场人数可以调整给定时间）分钟，一会我会邀请小伙伴来跟大家说说自己平时的表达。\u003c/p>\u003cp>我看到有的小组已经讨论的差不多了，你们可以根据案例的经典情况，来确定小组发言人。我们的发言人要组织一下语言，精简一下自己的案例，用1分钟的时间来跟大家分享。\u003c/p>\u003cp>好，我们来请XX分享她平时她的一个案例。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;谢谢XX的分享。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>刚才小伙伴们都分享了自己的类似经历，那么接下来，请大家根据今天所学到的方法，重新对自己的一件想去做或者需要去做的事情，WOOP一下。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;注意，在进行这一部分的时候，大家可以用我刚才分下去的模板直接写下来。\u003c/p>\u003cp>大家可以开始动笔来写了，时间为1分钟，一会我会请小伙伴用1分钟来跟我们分享他的应用。（时间充足再找一位小伙伴来分享。分别用1-2句话点评或总结。）\u003c/p>\u003cp>今天我分享的WOOP思维，其实也就是四个步骤：第一步：确定愿望。第二步：想象成果。第三步：寻找障碍：确定行动。通过这个办法，让我们不再感觉“身体被掏空”，无压地前行。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473599672000,"updated_at":1473599672000,"ria":true}]};